INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95325, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "内科学", "is_correct": true, "explanation": "正确。这里指内科学的课本，“这本”修饰书籍，符合句意。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干是食品，不能作课本的主题。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑部件，不能作课本的主题。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“本”用于计量书籍，书包不能用“这本”计量。"}], "explanations": {"内科学": "正确。这里指内科学的课本，“这本”修饰书籍，符合句意。", "饼干": "语义：饼干是食品，不能作课本的主题。", "窗户": "语义：窗户是建筑部件，不能作课本的主题。", "书包": "搭配：“本”用于计量书籍，书包不能用“这本”计量。"}, "sentence_index": 6, "correct_answer": "内科学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是很好的内科学，每天都在病房里工作。", "explanation": "这里应该用〈内科医生〉。内科学指学问，不指人；表示医生要说“内科医生”。"}, {"text": "他下周要去内科学报到，负责病房。", "explanation": "这里应该用〈内科〉。内科学是学问，不是科室；去科室报到要说“去内科”。"}, {"text": "他去年冬天得了内科学，咳嗽了很久。", "explanation": "这里应该用〈肺炎〉之类的病名。内科学是学问，不是疾病名称，不能说“得了内科学”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc16e87b-3d15-4e1f-8fa1-4ec5a9c7b9e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95325, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我姐姐正在学一条内科学。", "corrected_sentence": "我姐姐正在学一门内科学。", "error_description": "错误在目标词的量词。“条”用于细长的东西，学科应该用“门”，正确说法是“一门内科学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc16e87b-3d15-4e1f-8fa1-4ec5a9c7b9e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95325, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在图书馆认真学习一位内科学。", "corrected_sentence": "他在图书馆认真学习一门内科学。", "error_description": "错误在目标词的量词。“位”用于人，学科应该用“门”，正确说法是“一门内科学”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc16e87b-3d15-4e1f-8fa1-4ec5a9c7b9e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
