INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95327, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西再做一次，让它变得更好。", "primary_collocate": null, "pronunciation": "zài chǔ lǐ", "ipa": "tsaɪ˥˩ ʈʂʰu˨˩˦ li˨˩˦", "syllable_count": 3, "sentences": [{"text": "这张照片太暗了，我想再处理一下。", "target_word": "再处理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个视频声音不清楚，请你再处理一下。", "target_word": "再处理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桌子表面不够光滑，木工把它再处理了一遍。", "target_word": "再处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块布颜色不均匀，要再处理才好看。", "target_word": "再处理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对这张设计图不满意，想再处理，让它更好看。", "target_word": "再处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照片再处理以后，颜色变得更漂亮了。", "target_word": "再处理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "图片边上还有黑点，你把它再处理一下吧。", "target_word": "再处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条皮带做得有点硬，师傅想再处理一次，让它变软。", "target_word": "再处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批照片还不够好，设计师决定再处理一次。", "target_word": "再处理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个模型表面有点粗，我再处理了一次，现在好多了。", "target_word": "再处理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "再处理了", "label": "完成体"}, {"form": "再处理过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "对做得不够好的东西再加工一次使其更好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b37fbea5-e5a7-40fc-aef0-8c6a260a8c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95327, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "再处理", "is_correct": true, "explanation": "正确：再处理指对照片再做一次加工，使它更好，与“太暗了”的语境相符。"}, {"text": "放大", "is_correct": false, "explanation": "语义：放大只是改变照片的尺寸，不能让太暗的照片变亮。"}, {"text": "装订", "is_correct": false, "explanation": "搭配：“装订”用于书本、文件，不能用于照片的明暗。"}, {"text": "缩小", "is_correct": false, "explanation": "语义：缩小说的是尺寸，与“太暗”的问题无关。"}], "explanations": {"再处理": "正确：再处理指对照片再做一次加工，使它更好，与“太暗了”的语境相符。", "放大": "语义：放大只是改变照片的尺寸，不能让太暗的照片变亮。", "装订": "搭配：“装订”用于书本、文件，不能用于照片的明暗。", "缩小": "语义：缩小说的是尺寸，与“太暗”的问题无关。"}, "sentence_index": 0, "correct_answer": "再处理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个女孩要再处理一下，才显得精神。", "explanation": "这里应该用〈打扮〉。“再处理”用于物料，不能用来指人。"}, {"text": "这个男孩太调皮了，我们要再处理他一下，让他变好。", "explanation": "这里应该用〈教育〉。“再处理”指对物料的再加工，不能用于调教人。"}, {"text": "农民每天要再处理他家的母牛。", "explanation": "这里应该用〈喂养〉。“再处理”不用于动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c46cb8d-7db9-433e-929e-cc38fb7b7492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95327, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "再处理", "is_correct": true, "explanation": "正确：再处理指对图片再加工，才能去掉边上的黑点。"}, {"text": "装裱", "is_correct": false, "explanation": "语义：装裱只是装框托裱，并不能去掉图上的黑点。"}, {"text": "打磨", "is_correct": false, "explanation": "搭配：“打磨”多用于金属、玉器等硬物表面，不用于图片。"}, {"text": "加深", "is_correct": false, "explanation": "语义：加深会让颜色更深，黑点只会更明显。"}], "explanations": {"再处理": "正确：再处理指对图片再加工，才能去掉边上的黑点。", "装裱": "语义：装裱只是装框托裱，并不能去掉图上的黑点。", "打磨": "搭配：“打磨”多用于金属、玉器等硬物表面，不用于图片。", "加深": "语义：加深会让颜色更深，黑点只会更明显。"}, "sentence_index": 6, "correct_answer": "再处理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对这位朋友很不满意，就把他再处理了一遍。", "explanation": "这里应该用〈批评〉。“再处理”只用于物料，不能用于人。"}, {"text": "这道题我不会做，老师再处理了一遍。", "explanation": "这里应该用〈讲解〉。“再处理”指对物料的再加工，不能用来指给学生讲解题目。"}, {"text": "老师想再处理他一下，让他的成绩好起来。", "explanation": "这里应该用〈辅导〉。“再处理”不用于指导人学习，只用于物料的再加工。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c46cb8d-7db9-433e-929e-cc38fb7b7492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95327, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张照片我已经再处理了一个次。", "corrected_sentence": "这张照片我已经再处理了一次。", "error_description": "动作次数的量词是“次”，“次”前面的数词“一”不能再加量词“个”。应说“再处理了一次”，不能说“再处理了一个次”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c46cb8d-7db9-433e-929e-cc38fb7b7492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95327, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张图我已经再处理了过。", "corrected_sentence": "这张图我已经再处理过了。", "error_description": "“过”和“了”的顺序不能颠倒：应说“再处理过了”，不能说“再处理了过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c46cb8d-7db9-433e-929e-cc38fb7b7492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
