INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95328, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对已经处理过的事物再次加工处理。", "primary_collocate": null, "pronunciation": "zài chǔ lǐ", "ipa": "tsaɪ˥˩ ʈʂʰu˨˩˦ li˨˩˦", "syllable_count": 3, "sentences": [{"text": "工厂把处理过的污水再处理，然后用来浇花。", "target_word": "再处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些废水已经处理过，还要再处理一次才能排放。", "target_word": "再处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧油经过一次处理后，工人又对它进行再处理。", "target_word": "再处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些废水第一次处理后还不达标，需要再处理。", "target_word": "再处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批旧纸已经处理过一次，现在要再处理。", "target_word": "再处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "再处理后的垃圾，可以变成有用的东西。", "target_word": "再处理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "污泥再处理以后，可以当成肥料用。", "target_word": "再处理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人们把处理过的废钢再处理，做成新的钢板。", "target_word": "再处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司专门做废电池的再处理工作。", "target_word": "再处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "第一次处理后水还不干净，只好再处理了一遍。", "target_word": "再处理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "再处理了", "label": "完成体"}, {"form": "再处理过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "对已处理过的废料、材料等再次加工", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b37fbea5-e5a7-40fc-aef0-8c6a260a8c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95328, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "再处理", "is_correct": true, "explanation": "正确：再处理指对已用过的水再加工，与“然后用来浇花”衔接自然。"}, {"text": "丢弃", "is_correct": false, "explanation": "语义：水丢弃之后又用来浇花，前后矛盾。"}, {"text": "喝掉", "is_correct": false, "explanation": "语义：水喝掉以后就不能再用来浇花了，前后不通。"}, {"text": "晒干", "is_correct": false, "explanation": "语义：水晒干之后就没有水了，不能再用来浇花，前后矛盾。"}], "explanations": {"再处理": "正确：再处理指对已用过的水再加工，与“然后用来浇花”衔接自然。", "丢弃": "语义：水丢弃之后又用来浇花，前后矛盾。", "喝掉": "语义：水喝掉以后就不能再用来浇花了，前后不通。", "晒干": "语义：水晒干之后就没有水了，不能再用来浇花，前后矛盾。"}, "sentence_index": 0, "correct_answer": "再处理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这批刚运来的新鲜木材，要再处理一下才能用。", "explanation": "这里应该用〈处理〉。“再处理”指对已经加工过的东西再加工，刚运来的木材还没有加工过。"}, {"text": "这只小狗很可爱，我们要再处理它，让它吃饱。", "explanation": "这里应该用〈喂养〉。“再处理”只用于废料、材料等物品，不能用于动物。"}, {"text": "这把坏了的椅子要再处理一下，才能坐人。", "explanation": "这里应该用〈修理〉。“再处理”是对废料、材料的再加工，不指修复坏了的家具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c46cb8d-7db9-433e-929e-cc38fb7b7492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95328, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "再处理", "is_correct": true, "explanation": "正确：再处理指对污泥再加工，才能再当成肥料用。"}, {"text": "吃掉", "is_correct": false, "explanation": "语义：污泥吃掉之后就没有了，不能再当成肥料用。"}, {"text": "扔掉", "is_correct": false, "explanation": "语义：污泥扔掉之后就没有了，不能再当成肥料用，前后矛盾。"}, {"text": "玩耍", "is_correct": false, "explanation": "语义：玩耍是娱乐的意思，与“处理后当成肥料用”毫不相关。"}], "explanations": {"再处理": "正确：再处理指对污泥再加工，才能再当成肥料用。", "吃掉": "语义：污泥吃掉之后就没有了，不能再当成肥料用。", "扔掉": "语义：污泥扔掉之后就没有了，不能再当成肥料用，前后矛盾。", "玩耍": "语义：玩耍是娱乐的意思，与“处理后当成肥料用”毫不相关。"}, "sentence_index": 6, "correct_answer": "再处理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "衣服脏了，我得再处理一遍。", "explanation": "这里应该用〈清洗〉。“再处理”指对已加工过的废料、材料再加工，衣服脏了不是这个意思。"}, {"text": "妈妈每天要再处理生病的爷爷。", "explanation": "这里应该用〈照顾〉。“再处理”不用于人，不能用来说照顾老人。"}, {"text": "这本英文书要再处理成中文。", "explanation": "这里应该用〈翻译〉。“再处理”指对物料的再加工，不指语言之间的转换。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c46cb8d-7db9-433e-929e-cc38fb7b7492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95328, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些旧塑料瓶要送去再处理着。", "corrected_sentence": "这些旧塑料瓶要送去再处理。", "error_description": "“要……去”表示将要进行的动作，与表示持续状态的“着”不搭。应说“要送去再处理”，不能说“要送去再处理着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c46cb8d-7db9-433e-929e-cc38fb7b7492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95328, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工厂把废料再处理了一个遍。", "corrected_sentence": "工厂把废料再处理了一遍。", "error_description": "“遍”是动量词，前面的数词“一”后面直接接“遍”，不能加“个”，应说“再处理了一遍”，不能说“再处理了一个遍”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c46cb8d-7db9-433e-929e-cc38fb7b7492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95330, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "夏天", "is_correct": true, "explanation": "夏天与冬天互为反义词，指一年中最热的季节。"}, {"text": "窗户", "is_correct": false, "explanation": "窗户与“冬天”没有反义关系，是具体事物。"}, {"text": "早晨", "is_correct": false, "explanation": "早晨与“冬天”没有反义关系，只是时间词。"}, {"text": "衣服", "is_correct": false, "explanation": "衣服与“冬天”没有反义关系，是具体事物。"}], "correct_answer": "夏天", "explanations": {"夏天": "夏天与冬天互为反义词，指一年中最热的季节。", "窗户": "窗户与“冬天”没有反义关系，是具体事物。", "早晨": "早晨与“冬天”没有反义关系，只是时间词。", "衣服": "衣服与“冬天”没有反义关系，是具体事物。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '293ba40b-5c94-4f9c-adcb-2dc4aaba108d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
