INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95330, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一年四季中最冷的季节。", "primary_collocate": null, "pronunciation": "dōng tiān", "ipa": "tʊŋ˥ tʰjɛn˥", "syllable_count": 2, "sentences": [{"text": "一年有四个季节，冬天是最后一个。", "target_word": "冬天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天、夏天、秋天都过去了，现在是冬天。", "target_word": "冬天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最喜欢的季节是冬天。", "target_word": "冬天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天以后就是冬天。", "target_word": "冬天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在四个季节里，冬天白天最短。", "target_word": "冬天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天过完是秋天，然后才是冬天。", "target_word": "冬天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十二月、一月、二月都属于冬天。", "target_word": "冬天", "complexity_tier": "T3", "furigana": "shí''èr yuè, yī yuè, èr yuè dōu shǔyú dōngtiān", "sentence_source": "generated"}, {"text": "你喜欢夏天还是冬天？", "target_word": "冬天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春夏秋冬四季中，冬天排在最后。", "target_word": "冬天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说四个季节里自己最怕冬天。", "target_word": "冬天", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个冬天", "label": "量词"}], "register": "中性", "sense_fingerprint": "四季中排在最后、最冷的季节", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4747408d-1a98-454a-a674-44dda78aa04a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95330, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "冬天", "is_correct": true, "explanation": "正确答案。"}, {"text": "东边", "is_correct": false, "explanation": "tiān 与 biān 声母不同，意思是东面。"}, {"text": "当天", "is_correct": false, "explanation": "dōng 与 dāng 韵母不同，意思是那一天。"}, {"text": "通天", "is_correct": false, "explanation": "dōng 与 tōng 声母不同，意思是通到天上，多用于“通天本领”。"}], "explanations": {"冬天": "正确答案。", "东边": "tiān 与 biān 声母不同，意思是东面。", "当天": "dōng 与 dāng 韵母不同，意思是那一天。", "通天": "dōng 与 tōng 声母不同，意思是通到天上，多用于“通天本领”。"}, "sentence_index": null, "correct_answer": "冬天"}, "level_3": {"options": [{"text": "冬天", "is_correct": true, "explanation": "正确：“冬天”是四季中排在最后的季节，与“最后一个”相合。"}, {"text": "春天", "is_correct": false, "explanation": "语义：春天是四季中的第一个季节，不能是最后一个。"}, {"text": "秋天", "is_correct": false, "explanation": "语义：秋天在夏天之后、冬天之前，不是最后一个。"}, {"text": "元旦", "is_correct": false, "explanation": "搭配：“元旦”是节日，不属于四季，不能与“季节”并列。"}], "explanations": {"冬天": "正确：“冬天”是四季中排在最后的季节，与“最后一个”相合。", "春天": "语义：春天是四季中的第一个季节，不能是最后一个。", "秋天": "语义：秋天在夏天之后、冬天之前，不是最后一个。", "元旦": "搭配：“元旦”是节日，不属于四季，不能与“季节”并列。"}, "sentence_index": 0, "correct_answer": "冬天"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "下一届冬天奥运会在哪个国家举行？", "explanation": "这里应该用〈冬季〉。“冬季奥运会”是固定名称，不能说“冬天奥运会”。"}, {"text": "农民们秋后在地里种了冬天作物。", "explanation": "这里应该用〈冬季〉。“冬季作物”是固定说法，“冬天作物”不能这样说。"}, {"text": "冬天腊月的夜晚很长，我们早点睡。", "explanation": "这里应该用〈寒冬〉。“寒冬腊月”是固定说法，“冬天腊月”不通顺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '293ba40b-5c94-4f9c-adcb-2dc4aaba108d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95330, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冬天", "is_correct": true, "explanation": "正确：“冬天”指十二月到二月所在的季节，与前面的月份相合。"}, {"text": "夏天", "is_correct": false, "explanation": "语义：十二月至二月不属于夏天，与句意矛盾。"}, {"text": "八月", "is_correct": false, "explanation": "语义：八月不在十二月至二月之间，不能与这些月份并列属于同一季节。"}, {"text": "三伏", "is_correct": false, "explanation": "搭配：“三伏”是夏季最热的一段时间，不能与前面的月份一起“属于”同一类。"}], "explanations": {"冬天": "正确：“冬天”指十二月到二月所在的季节，与前面的月份相合。", "夏天": "语义：十二月至二月不属于夏天，与句意矛盾。", "八月": "语义：八月不在十二月至二月之间，不能与这些月份并列属于同一季节。", "三伏": "搭配：“三伏”是夏季最热的一段时间，不能与前面的月份一起“属于”同一类。"}, "sentence_index": 6, "correct_answer": "冬天"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "寒假我们去山上参加了冬天营。", "explanation": "这里应该用〈冬令〉。“冬令营”是固定说法，不能说“冬天营”。"}, {"text": "他从小练冬天两项，后来进了国家队。", "explanation": "这里应该用〈冬季〉。“冬季两项”是固定名称，“冬天两项”不能说。"}, {"text": "我们是在冬天学期转到这所学校的。", "explanation": "这里应该用〈冬季〉。“冬季学期”是固定说法，“冬天学期”不能说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '293ba40b-5c94-4f9c-adcb-2dc4aaba108d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95330, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只冬天特别冷。", "corrected_sentence": "这个冬天特别冷。", "error_description": "错误：“冬天”前的量词应用“个”，不能用“只”，“只”多用于动物等。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '293ba40b-5c94-4f9c-adcb-2dc4aaba108d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95330, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个的冬天，我们都很开心。", "corrected_sentence": "这个冬天，我们都很开心。", "error_description": "错误：“的”不能放在“这个”后直接修饰“冬天”，应说“这个冬天”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '293ba40b-5c94-4f9c-adcb-2dc4aaba108d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
