INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95334, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "从事书籍、刊物编辑出版工作的机构。", "primary_collocate": null, "pronunciation": "chū bǎn shè", "ipa": "ʈʂʰu˥ pan˨˩ ʂɤ˥˩", "syllable_count": 3, "sentences": [{"text": "这本书是北京的一家出版社出的。", "target_word": "出版社", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在一家出版社做编辑。", "target_word": "出版社", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家出版社出了很多好书。", "target_word": "出版社", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出版社决定下个月印这本书。", "target_word": "出版社", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想把我的小说寄给出版社。", "target_word": "出版社", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家出版社已经成立五十年了。", "target_word": "出版社", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出版社的编辑看了他的稿子。", "target_word": "出版社", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她想去出版社工作，每天和书在一起。", "target_word": "出版社", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个出版社专门出版儿童书。", "target_word": "出版社", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出版社给作者寄了一本新书。", "target_word": "出版社", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "大学出版社", "label": "复合"}], "register": "通用", "sense_fingerprint": "从事书刊编辑出版工作的机构", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17ff06e6-d05a-42d0-84b6-f1fd5eae80ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95334, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出版社", "is_correct": true, "explanation": "出版社：从事书籍、刊物编辑出版工作的机构，“这本书是……出的”指出版机构出版的书。"}, {"text": "理发店", "is_correct": false, "explanation": "语义：理发店不出版书籍，“这本书是……理发店出的”读不通。"}, {"text": "洗衣店", "is_correct": false, "explanation": "语义：洗衣店不出版书籍，“这本书是……洗衣店出的”与其经营内容无关。"}, {"text": "加油站", "is_correct": false, "explanation": "语义：加油站不出版书籍，“这本书是……加油站出的”与其性质不符。"}], "explanations": {"出版社": "出版社：从事书籍、刊物编辑出版工作的机构，“这本书是……出的”指出版机构出版的书。", "理发店": "语义：理发店不出版书籍，“这本书是……理发店出的”读不通。", "洗衣店": "语义：洗衣店不出版书籍，“这本书是……洗衣店出的”与其经营内容无关。", "加油站": "语义：加油站不出版书籍，“这本书是……加油站出的”与其性质不符。"}, "sentence_index": 0, "correct_answer": "出版社"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家出版社写了很多书。", "explanation": "这里应该把主语改为〈作家〉。出版社负责出版和印制，不负责写书，写书的是作家。"}, {"text": "我们学校旁边有一本出版社。", "explanation": "这里应该用〈家〉。出版社是机构，量词用“家”，不能用“本”（“本”多用于书籍）。"}, {"text": "这家出版社每天早上七点起床。", "explanation": "这里应该把主语改为〈员工〉。出版社是机构，不会起床，起床的是员工。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70428954-4397-48b4-b49b-6d906a67ae78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95334, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出版社", "is_correct": true, "explanation": "出版社：从事书籍、刊物编辑出版工作的机构，“出版社的编辑”指出版机构的编辑，符合句意。"}, {"text": "银行", "is_correct": false, "explanation": "语义：银行不出版书刊，“银行的编辑看了他的稿子”读不通。"}, {"text": "超市", "is_correct": false, "explanation": "语义：超市经营日用商品，不出版书刊，“超市的编辑看了他的稿子”读不通。"}, {"text": "餐厅", "is_correct": false, "explanation": "语义：餐厅经营饮食，不出版书刊，“餐厅的编辑看了他的稿子”读不通。"}], "explanations": {"出版社": "出版社：从事书籍、刊物编辑出版工作的机构，“出版社的编辑”指出版机构的编辑，符合句意。", "银行": "语义：银行不出版书刊，“银行的编辑看了他的稿子”读不通。", "超市": "语义：超市经营日用商品，不出版书刊，“超市的编辑看了他的稿子”读不通。", "餐厅": "语义：餐厅经营饮食，不出版书刊，“餐厅的编辑看了他的稿子”读不通。"}, "sentence_index": 6, "correct_answer": "出版社"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "出版社每天给病人看病。", "explanation": "这里应该用〈医院〉。出版社出版书刊，不给病人看病，看病是医院的工作。"}, {"text": "出版社拍了一部新电影。", "explanation": "这里应该用〈电影公司〉。出版社出版书籍，不拍电影；拍电影的是电影公司。"}, {"text": "出版社卖了很多饮料。", "explanation": "这里应该用〈超市〉。出版社卖的是书，不卖饮料；卖饮料的是超市。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70428954-4397-48b4-b49b-6d906a67ae78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95334, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只出版社每年都出版很多教材。", "corrected_sentence": "那家出版社每年都出版很多教材。", "error_description": "量词用错：出版社是机构，应用“家”，不能用“只”（“只”多用于动物或单个的物品）。应说“那家出版社”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70428954-4397-48b4-b49b-6d906a67ae78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95334, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我出版社工作。", "corrected_sentence": "我在出版社工作。", "error_description": "“出版社”表示工作的处所，前面要加“在”。应说“我在出版社工作”，不能省去“在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70428954-4397-48b4-b49b-6d906a67ae78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
