INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95335, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "一家人分开，各自过各自的日子。", "primary_collocate": null, "pronunciation": "fēn jiā", "ipa": "fən˥ tɕja˥", "syllable_count": 2, "sentences": [{"text": "结婚以后，他们和父母分家了。", "target_word": "分家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "儿子长大了，想和爸爸妈妈分家。", "target_word": "分家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分家后，哥哥搬到了城里。", "target_word": "分家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们分家以后，还常常来往。", "target_word": "分家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分家以后，我们各过各的日子。", "target_word": "分家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们早就分家了，不住在一起。", "target_word": "分家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两兄弟分家后，关系还是很好。", "target_word": "分家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈不想让孩子们分家。", "target_word": "分家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为房子太小，他们只好分家。", "target_word": "分家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分家以后，姐姐自己做饭。", "target_word": "分家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分了家", "label": "体标"}, {"form": "分过家", "label": "体标"}], "register": "中性", "sense_fingerprint": "一家人分开住，各过各的生活", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2112c95f-d85a-4cfc-ba9f-40b392804a1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95335, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "结冰", "is_correct": false, "explanation": "语义：水遇冷才结冰，不能用于“和父母”。"}, {"text": "生锈", "is_correct": false, "explanation": "搭配：“生锈”说的是金属，不能用于人际关系。"}, {"text": "分家", "is_correct": true, "explanation": "正确：结婚以后，他们和父母分家，各过各的日子，符合句意。"}, {"text": "开花", "is_correct": false, "explanation": "语义：开花是植物的变化，人不能“开花”。"}], "explanations": {"结冰": "语义：水遇冷才结冰，不能用于“和父母”。", "生锈": "搭配：“生锈”说的是金属，不能用于人际关系。", "分家": "正确：结婚以后，他们和父母分家，各过各的日子，符合句意。", "开花": "语义：开花是植物的变化，人不能“开花”。"}, "sentence_index": 0, "correct_answer": "分家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "同学们分家后，各自去了外地。", "explanation": "这里应该用〈毕业〉。分家指一家人分开，同学之间不能说分家。"}, {"text": "老师把作业本分家给同学们。", "explanation": "这里应该用〈分发〉。分家指一家人分开过日子，不能用于把东西发给别人。"}, {"text": "我们把一个苹果分家，每人吃一半。", "explanation": "这里应该用〈分〉。分家指一家人分开过日子，分东西只说“分”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8274a805-2c34-4a6f-9e45-8d48a0d1896d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95335, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下雨", "is_correct": false, "explanation": "语义：下雨是天气现象，不能说“两兄弟下雨后”。"}, {"text": "分家", "is_correct": true, "explanation": "正确：两兄弟分家后，关系还是很好，符合句意。"}, {"text": "发芽", "is_correct": false, "explanation": "语义：发芽是植物的变化，人不能“发芽”。"}, {"text": "冒烟", "is_correct": false, "explanation": "语义：冒烟是现象，不是两兄弟可以经历的事情。"}], "explanations": {"下雨": "语义：下雨是天气现象，不能说“两兄弟下雨后”。", "分家": "正确：两兄弟分家后，关系还是很好，符合句意。", "发芽": "语义：发芽是植物的变化，人不能“发芽”。", "冒烟": "语义：冒烟是现象，不是两兄弟可以经历的事情。"}, "sentence_index": 6, "correct_answer": "分家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈把蛋糕分家成四块。", "explanation": "这里应该用〈切〉。分家指家人分开过日子，不能用于切蛋糕。"}, {"text": "电影分家后，大家走出影院。", "explanation": "这里应该用〈散场〉。分家只用于家人，不能用于电影。"}, {"text": "会议分家后，大家各自回家。", "explanation": "这里应该用〈散会〉。分家只用于家人，不能用于会议。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8274a805-2c34-4a6f-9e45-8d48a0d1896d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95335, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他打算明年和父母分过家。", "corrected_sentence": "他打算明年和父母分家。", "error_description": "错误形式：“分过家”用于尚未发生的“明年”；正确形式：“分家”。“过”表示曾经有过的经历，不能用于将来的计划。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8274a805-2c34-4a6f-9e45-8d48a0d1896d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95335, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们分家过，又和好了。", "corrected_sentence": "他们分过家，又和好了。", "error_description": "错误形式：“分家过”；正确形式：“分过家”。“分家”是离合词，“过”要放在“分”和“家”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8274a805-2c34-4a6f-9e45-8d48a0d1896d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
