INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95336, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "家庭成员分开，各立门户并分配家产。", "primary_collocate": null, "pronunciation": "fēn jiā", "ipa": "fən˥ tɕja˥", "syllable_count": 2, "sentences": [{"text": "父母去世后，兄弟俩就分家了。", "target_word": "分家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人想在生前分家，给孩子们留些钱。", "target_word": "分家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们分家时，为房子吵了起来。", "target_word": "分家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分家以后，哥哥得到了老房子。", "target_word": "分家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大哥说，分家要公平。", "target_word": "分家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "兄弟们坐下来商量分家的事。", "target_word": "分家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷不同意分家。", "target_word": "分家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们分家时，田地分成了三份。", "target_word": "分家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了分家，兄弟三人吵了很久。", "target_word": "分家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分家后，每个儿子都有自己的房子。", "target_word": "分家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分了家", "label": "体标"}, {"form": "分过家", "label": "体标"}], "register": "中性", "sense_fingerprint": "兄弟等分开立户并分配家产", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2112c95f-d85a-4cfc-ba9f-40b392804a1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95336, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下雨", "is_correct": false, "explanation": "语义：下雨是天气现象，不能用于兄弟俩。"}, {"text": "分家", "is_correct": true, "explanation": "正确：父母去世后，兄弟俩分家，符合句意。"}, {"text": "发芽", "is_correct": false, "explanation": "语义：发芽是植物的变化，人不能“发芽”。"}, {"text": "开花", "is_correct": false, "explanation": "搭配：“开花”的主语是植物，不能用于兄弟俩。"}], "explanations": {"下雨": "语义：下雨是天气现象，不能用于兄弟俩。", "分家": "正确：父母去世后，兄弟俩分家，符合句意。", "发芽": "语义：发芽是植物的变化，人不能“发芽”。", "开花": "搭配：“开花”的主语是植物，不能用于兄弟俩。"}, "sentence_index": 0, "correct_answer": "分家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条河流到山下就分家了，变成两条小河。", "explanation": "这里应该用〈分开〉。分家只用于同一家庭的成员分户、分财产，不能用于河流。"}, {"text": "这对恋人分家后各自回家。", "explanation": "这里应该用〈分手〉。分家指家人分户、分财产，恋人之间不能用。"}, {"text": "人群很快就分家了。", "explanation": "这里应该用〈分散〉。分家只用于家人，不能说人群分家。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8274a805-2c34-4a6f-9e45-8d48a0d1896d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95336, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "结冰", "is_correct": false, "explanation": "语义：水遇冷才结冰，“不同意”不能接自然现象。"}, {"text": "分家", "is_correct": true, "explanation": "正确：爷爷不同意分家，符合句意。"}, {"text": "生锈", "is_correct": false, "explanation": "搭配：“生锈”说的是金属的变化，不能作为“不同意”的内容。"}, {"text": "冒烟", "is_correct": false, "explanation": "语义：冒烟是现象，不是可以同意或不同意的事情。"}], "explanations": {"结冰": "语义：水遇冷才结冰，“不同意”不能接自然现象。", "分家": "正确：爷爷不同意分家，符合句意。", "生锈": "搭配：“生锈”说的是金属的变化，不能作为“不同意”的内容。", "冒烟": "语义：冒烟是现象，不是可以同意或不同意的事情。"}, "sentence_index": 6, "correct_answer": "分家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "苹果分家了，滚到了床底下。", "explanation": "这里应该用〈掉〉。分家只用于家庭成员分户，不能用于苹果。"}, {"text": "我的手机摔分家了，屏幕再也不亮了。", "explanation": "这里应该用〈坏〉。分家只用于家庭成员分户，不能用于手机。"}, {"text": "两根绳子分家了，掉在地上。", "explanation": "这里应该用〈分离〉。分家只用于家人，不能用于绳子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8274a805-2c34-4a6f-9e45-8d48a0d1896d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95336, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "兄弟俩分家过，各自盖了房子。", "corrected_sentence": "兄弟俩分过家，各自盖了房子。", "error_description": "错误形式：“分家过”；正确形式：“分过家”。“分家”是离合词，“过”要放在“分”和“家”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8274a805-2c34-4a6f-9e45-8d48a0d1896d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95336, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "兄弟们分家房子以后，各自盖了房子。", "corrected_sentence": "兄弟们分家以后，各自盖了房子。", "error_description": "错误形式：“分家房子”；正确形式：“分家”。“分家”是不及物的离合词，不能直接带宾语“房子”，句中多出的“房子”应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8274a805-2c34-4a6f-9e45-8d48a0d1896d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
