INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95337, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不多也不少，正合适。", "primary_collocate": null, "pronunciation": "gāng hǎo", "ipa": "kɑŋ˥ xɑʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "这件衣服我穿刚好，不大也不小。", "target_word": "刚好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水的温度刚好，不冷也不热。", "target_word": "刚好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盐放得刚好，汤很好喝。", "target_word": "刚好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双鞋的大小刚好，我很喜欢。", "target_word": "刚好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的天气不冷不热，刚好。", "target_word": "刚好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些钱买一本书刚好，不多也不少。", "target_word": "刚好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他来得不早不晚，时间刚好。", "target_word": "刚好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一碗饭对我来说刚好，不多也不少。", "target_word": "刚好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的帽子戴在头上刚好，不松也不紧。", "target_word": "刚好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间不大不小，两个人住刚好。", "target_word": "刚好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "数量、大小、程度不多不少，正合适", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2112c95f-d85a-4cfc-ba9f-40b392804a1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95337, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大", "is_correct": false, "explanation": "语义：“穿大”说衣服偏大，与后半句“不大也不小”直接矛盾。"}, {"text": "窄", "is_correct": false, "explanation": "语义：“窄”说宽度不够，与“不大也不小”所说的尺寸合适相冲突。"}, {"text": "刚好", "is_correct": true, "explanation": "正确。“刚好”表示衣服的尺寸不多不少、正合适，与后半句呼应。"}, {"text": "漂亮", "is_correct": false, "explanation": "搭配：“漂亮”描述外观，不能说明尺寸合不合身，与“穿”后面的尺寸评价不搭。"}], "explanations": {"大": "语义：“穿大”说衣服偏大，与后半句“不大也不小”直接矛盾。", "窄": "语义：“窄”说宽度不够，与“不大也不小”所说的尺寸合适相冲突。", "刚好": "正确。“刚好”表示衣服的尺寸不多不少、正合适，与后半句呼应。", "漂亮": "搭配：“漂亮”描述外观，不能说明尺寸合不合身，与“穿”后面的尺寸评价不搭。"}, "sentence_index": 0, "correct_answer": "刚好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服刚好大了一大圈，穿着直往下掉。", "explanation": "这里用“刚好”形容尺寸，却与“大了一大圈”矛盾；“刚好”表示不多不少、正合适，尺寸不能偏大。"}, {"text": "这双鞋刚好小了两个号，脚根本穿不进去。", "explanation": "这里用“刚好”形容尺寸，却与“小了两个号”矛盾；尺寸偏小时应说“小了”，不能说“刚好”。"}, {"text": "这件大衣的长短刚好，却长到了脚踝，走路很碍事。", "explanation": "这里用“刚好”形容长短，却与“长到了脚踝”矛盾；“刚好”表示正合适，过长时不能用“刚好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8274a805-2c34-4a6f-9e45-8d48a0d1896d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95337, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "早", "is_correct": false, "explanation": "语义：“时间早”与前面的“不早不晚”正相矛盾。"}, {"text": "晚", "is_correct": false, "explanation": "语义：“晚”与“不早不晚”正相反，不能指同一个时间。"}, {"text": "刚好", "is_correct": true, "explanation": "正确。“刚好”表示时间不早不晚、正合适，与前半句呼应。"}, {"text": "高", "is_correct": false, "explanation": "搭配：“高”描述高度，不能用来形容时间是否合适。"}], "explanations": {"早": "语义：“时间早”与前面的“不早不晚”正相矛盾。", "晚": "语义：“晚”与“不早不晚”正相反，不能指同一个时间。", "刚好": "正确。“刚好”表示时间不早不晚、正合适，与前半句呼应。", "高": "搭配：“高”描述高度，不能用来形容时间是否合适。"}, "sentence_index": 6, "correct_answer": "刚好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "汤里的盐刚好，咸得没法喝。", "explanation": "这里用“刚好”形容盐的多少，却与“咸得没法喝”矛盾；“刚好”表示不多不少、正合适。"}, {"text": "水温刚好，烫得手都不敢伸进去。", "explanation": "这里用“刚好”形容温度，却与“烫得不敢伸手”矛盾；太烫时不能说“刚好”。"}, {"text": "这碗饭的分量刚好，我吃了还饿得厉害。", "explanation": "这里用“刚好”形容分量，却与“还饿得厉害”矛盾；分量不够时不能说“刚好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8274a805-2c34-4a6f-9e45-8d48a0d1896d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95337, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件外套的长短刚好地，我很满意。", "corrected_sentence": "这件外套的长短刚好，我很满意。", "error_description": "“刚好”作形容词作谓语，后面不能加状语标记“地”；应说“这件外套的长短刚好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8274a805-2c34-4a6f-9e45-8d48a0d1896d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95337, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这碗饭的分量刚好得，吃完不饱也不撑。", "corrected_sentence": "这碗饭的分量刚好，吃完不饱也不撑。", "error_description": "“得”引出的补语缺失，句子不完整；应说“这碗饭的分量刚好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8274a805-2c34-4a6f-9e45-8d48a0d1896d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
