INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95338, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8274a805-2c34-4a6f-9e45-8d48a0d1896d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95338, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "恰好；正巧。", "primary_collocate": null, "pronunciation": "gāng hǎo", "ipa": "kɑŋ˥ xɑʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "我到车站的时候，车刚好来了。", "target_word": "刚好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我刚好有空，我们一起吃饭吧。", "target_word": "刚好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他进门时，刚好下起雨来。", "target_word": "刚好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我打电话给她，她刚好在家。", "target_word": "刚好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在路上刚好遇到了老同学。", "target_word": "刚好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天下雨，我刚好带着伞，所以没淋湿。", "target_word": "刚好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你来得真巧，我刚好想找你。", "target_word": "刚好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家商店今天刚好打折，真巧。", "target_word": "刚好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我走到门口，刚好看见老师出来。", "target_word": "刚好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我上车时，他刚好坐在我旁边。", "target_word": "刚好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "表示事情碰巧发生，时间或情况正巧遇上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2112c95f-d85a-4cfc-ba9f-40b392804a1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95338, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "永远", "is_correct": false, "explanation": "语义：“永远”表示持续到将来，不能与表示已经发生的“来了”搭配，句中说的是一次性到达。"}, {"text": "不", "is_correct": false, "explanation": "语义：“车不来了”说车不再来，与“我到车站的时候车到了”的情况正相反。"}, {"text": "刚好", "is_correct": true, "explanation": "正确。“刚好”表示车正巧在我到站时到达，时机恰好。"}, {"text": "一直", "is_correct": false, "explanation": "搭配：“一直”多与持续的动作或否定连用，“一直来了”不成立，应说“一直没来”。"}], "explanations": {"永远": "语义：“永远”表示持续到将来，不能与表示已经发生的“来了”搭配，句中说的是一次性到达。", "不": "语义：“车不来了”说车不再来，与“我到车站的时候车到了”的情况正相反。", "刚好": "正确。“刚好”表示车正巧在我到站时到达，时机恰好。", "一直": "搭配：“一直”多与持续的动作或否定连用，“一直来了”不成立，应说“一直没来”。"}, "sentence_index": 0, "correct_answer": "刚好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他故意刚好在门口等我，等了一个小时。", "explanation": "“刚好”表示碰巧，不能与表示有意的“故意”同用，也不能用于等了很久的安排。"}, {"text": "妈妈特意刚好给我做了饺子。", "explanation": "“刚好”表示碰巧，与“特意”的有意安排相矛盾。"}, {"text": "他每天都刚好七点起床，这是他多年的习惯。", "explanation": "“刚好”表示一次性的巧合，不能用于有规律的习惯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8274a805-2c34-4a6f-9e45-8d48a0d1896d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95338, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "故意", "is_correct": false, "explanation": "语义：“故意”表示有意为之，与“真巧”所说的巧合相矛盾。"}, {"text": "马上", "is_correct": false, "explanation": "搭配：“马上”表示很快发生，“马上想找你”不自然，想念的心情不会“马上”产生。"}, {"text": "刚好", "is_correct": true, "explanation": "正确。“刚好”表示我想找你的时候正好与“你来”的时机相合，与“真巧”呼应。"}, {"text": "不必", "is_correct": false, "explanation": "语义：“不必”表示没有必要，与“真巧”之后紧接“想找你”的语气相冲突。"}], "explanations": {"故意": "语义：“故意”表示有意为之，与“真巧”所说的巧合相矛盾。", "马上": "搭配：“马上”表示很快发生，“马上想找你”不自然，想念的心情不会“马上”产生。", "刚好": "正确。“刚好”表示我想找你的时候正好与“你来”的时机相合，与“真巧”呼应。", "不必": "语义：“不必”表示没有必要，与“真巧”之后紧接“想找你”的语气相冲突。"}, "sentence_index": 6, "correct_answer": "刚好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们早就约好了，所以他刚好来了。", "explanation": "“刚好”表示碰巧，而事先约好的事不是巧合。"}, {"text": "老师有意刚好叫我回答问题。", "explanation": "“刚好”表示碰巧，与“有意”相矛盾。"}, {"text": "他每个星期天都刚好去公园跑步。", "explanation": "“刚好”表示偶然巧合，不能用于每周固定的习惯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8274a805-2c34-4a6f-9e45-8d48a0d1896d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95338, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我到楼下的时候，电梯刚好的到了。", "corrected_sentence": "我到楼下的时候，电梯刚好到了。", "error_description": "“刚好”是副词，修饰动词，后面不能加“的”；错误形式：“电梯刚好的到了”，正确形式：“电梯刚好到了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8274a805-2c34-4a6f-9e45-8d48a0d1896d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95338, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我下楼的时候，朋友很刚好打来电话。", "corrected_sentence": "我下楼的时候，朋友刚好打来电话。", "error_description": "“刚好”是表示时机的副词，前面不能加程度副词“很”；应写作“朋友刚好打来电话”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8274a805-2c34-4a6f-9e45-8d48a0d1896d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95339, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b3da8f-38fb-4b17-bfe6-56ca8c06d98f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95339, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b3da8f-38fb-4b17-bfe6-56ca8c06d98f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95339, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "去加入一场比赛。", "primary_collocate": null, "pronunciation": "cān sài", "ipa": "tsʰan˥ sai˥˩", "syllable_count": 2, "sentences": [{"text": "我们学校的篮球队明天去外地参赛。", "target_word": "参赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他报名了，下个月要去北京参赛。", "target_word": "参赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李因为受伤，不能参赛了。", "target_word": "参赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次有二十个国家的选手来参赛。", "target_word": "参赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小学游泳，今年第一次参赛。", "target_word": "参赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想参赛的话，要先在网上报名。", "target_word": "参赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们三个人一起去参赛，一定很有意思。", "target_word": "参赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说我的中文不错，可以去参赛。", "target_word": "参赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他以前参赛过两次，不太紧张。", "target_word": "参赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛明天开始，参赛的人都到了。", "target_word": "参赛", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "参赛了", "label": "体标（了）"}, {"form": "参赛过", "label": "体标（过）"}, {"form": "参赛者", "label": "复合词"}, {"form": "参赛队", "label": "复合词"}], "register": "中性", "sense_fingerprint": "前往并加入某一场具体的比赛", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40ccaa6c-88be-4174-ab0d-a617460feb36') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95339, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "参赛", "is_correct": true, "explanation": "参赛：去加入比赛，与“去外地”和“篮球队”的语境相符。"}, {"text": "生病", "is_correct": false, "explanation": "语义：篮球队去外地的目的是比赛，“生病”与句意不符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“去外地睡觉”没有合理目的，与球队出行的语境冲突。"}, {"text": "咳嗽", "is_correct": false, "explanation": "搭配：“咳嗽”是身体反应，不能作为“去外地”的目的动作。"}], "explanations": {"参赛": "参赛：去加入比赛，与“去外地”和“篮球队”的语境相符。", "生病": "语义：篮球队去外地的目的是比赛，“生病”与句意不符。", "睡觉": "语义：“去外地睡觉”没有合理目的，与球队出行的语境冲突。", "咳嗽": "搭配：“咳嗽”是身体反应，不能作为“去外地”的目的动作。"}, "sentence_index": 0, "correct_answer": "参赛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨天的婚礼，他没参赛，因为生病了。", "explanation": "这里应该用〈参加〉。参赛只用于比赛，婚礼等场合要用参加。"}, {"text": "这次董事会，他没能参赛。", "explanation": "这里应该用〈出席〉。参赛只用于比赛，董事会要用出席。"}, {"text": "这件事他没有参赛。", "explanation": "这里应该用〈参与〉。参赛只用于比赛，泛指的事情要用参与。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b3da8f-38fb-4b17-bfe6-56ca8c06d98f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95339, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "参赛", "is_correct": true, "explanation": "参赛：去加入比赛，符合“三个人一起去”的句意。"}, {"text": "哭泣", "is_correct": false, "explanation": "搭配：“去”后接“哭泣”这类情绪动作不成立，也与“很有意思”矛盾。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是身体不适，不会让人觉得“很有意思”。"}, {"text": "发烧", "is_correct": false, "explanation": "语义：发烧是身体不适，与“一起去”的轻松语境不符。"}], "explanations": {"参赛": "参赛：去加入比赛，符合“三个人一起去”的句意。", "哭泣": "搭配：“去”后接“哭泣”这类情绪动作不成立，也与“很有意思”矛盾。", "感冒": "语义：感冒是身体不适，不会让人觉得“很有意思”。", "发烧": "语义：发烧是身体不适，与“一起去”的轻松语境不符。"}, "sentence_index": 6, "correct_answer": "参赛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "班长选举的时候，他没有参赛。", "explanation": "这里应该用〈竞选〉。参赛指参加比赛，选班长要用竞选。"}, {"text": "我明天去医院参赛。", "explanation": "这里应该用〈看病〉。参赛只用于比赛，去医院就诊要用看病。"}, {"text": "妹妹明天去邮局参赛。", "explanation": "这里应该用〈寄〉。参赛只用于比赛，去邮局寄东西要用寄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b3da8f-38fb-4b17-bfe6-56ca8c06d98f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95339, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他上个月没参赛了。", "corrected_sentence": "他上个月没参赛。", "error_description": "错误：“没”否定已发生的“参赛”时，句末不能再加“了”。正确说法是“没参赛”，不说“没参赛了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b3da8f-38fb-4b17-bfe6-56ca8c06d98f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95339, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次他被参赛了。", "corrected_sentence": "这次他被选中参赛了。", "error_description": "错误：“参赛”是主动加入比赛的动作，不能直接用“被”引出。正确说法是“被选中参赛”，由“选中”表示被动。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b3da8f-38fb-4b17-bfe6-56ca8c06d98f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
