INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95340, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "参加比赛。", "primary_collocate": null, "pronunciation": "cān sài", "ipa": "tsʰan˥ sai˥˩", "syllable_count": 2, "sentences": [{"text": "参赛的选手请先到一楼报到。", "target_word": "参赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他代表我们班参赛，大家都给他加油。", "target_word": "参赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛，一共有一百多支队伍参赛。", "target_word": "参赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很想参赛，可是时间不够。", "target_word": "参赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们高兴地参赛，不在乎能不能赢。", "target_word": "参赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个参赛的人都会得到一份小礼物。", "target_word": "参赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为什么不参赛？你唱得那么好。", "target_word": "参赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她准备了很久，终于可以参赛了。", "target_word": "参赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们队有五个人参赛，其中两个是女生。", "target_word": "参赛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你参赛的那天，我一定去看你。", "target_word": "参赛", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "参赛了", "label": "体标（了）"}, {"form": "参赛过", "label": "体标（过）"}, {"form": "参赛者", "label": "复合词"}, {"form": "参赛队", "label": "复合词"}], "register": "中性", "sense_fingerprint": "作为选手或队伍参加比赛", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40ccaa6c-88be-4174-ab0d-a617460feb36') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95340, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "参赛", "is_correct": true, "explanation": "参赛：指选手加入比赛，修饰“选手”，符合句意。"}, {"text": "逃跑", "is_correct": false, "explanation": "语义：逃跑的选手不会到一楼报到，与句意冲突。"}, {"text": "失踪", "is_correct": false, "explanation": "语义：失踪的人无法到一楼报到，与句意冲突。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”是天气现象，不能用来修饰选手，“下雨的选手”不成立。"}], "explanations": {"参赛": "参赛：指选手加入比赛，修饰“选手”，符合句意。", "逃跑": "语义：逃跑的选手不会到一楼报到，与句意冲突。", "失踪": "语义：失踪的人无法到一楼报到，与句意冲突。", "下雨": "语义：“下雨”是天气现象，不能用来修饰选手，“下雨的选手”不成立。"}, "sentence_index": 0, "correct_answer": "参赛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨天的派对，我没参赛，因为有点累。", "explanation": "这里应该用〈参加〉。参赛只用于比赛，派对要用参加。"}, {"text": "那场音乐会，爸爸没能参赛。", "explanation": "这里应该用〈出席〉。参赛指加入比赛，音乐会这类场合要用出席。"}, {"text": "这次讨论会，他很积极地参赛。", "explanation": "这里应该用〈参与〉。参赛只用于比赛，讨论会要用参与。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b3da8f-38fb-4b17-bfe6-56ca8c06d98f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95340, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "参赛", "is_correct": true, "explanation": "参赛：指参加比赛，符合“你为什么不”后的劝说语境。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：咳嗽不是可以选择做或不做的事，与“为什么不”的问法不合。"}, {"text": "生病", "is_correct": false, "explanation": "语义：生病不是可以主动选择“不做”的事，与后句的称赞矛盾。"}, {"text": "哭", "is_correct": false, "explanation": "搭配：“为什么不哭”不是常见的劝说搭配，与后句“唱得那么好”也不合。"}], "explanations": {"参赛": "参赛：指参加比赛，符合“你为什么不”后的劝说语境。", "咳嗽": "语义：咳嗽不是可以选择做或不做的事，与“为什么不”的问法不合。", "生病": "语义：生病不是可以主动选择“不做”的事，与后句的称赞矛盾。", "哭": "搭配：“为什么不哭”不是常见的劝说搭配，与后句“唱得那么好”也不合。"}, "sentence_index": 6, "correct_answer": "参赛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "班长选举那天，她没有参赛。", "explanation": "这里应该用〈竞选〉。参赛指参加比赛，选班长要用竞选。"}, {"text": "我妹妹明天要去医院参赛。", "explanation": "这里应该用〈看病〉。参赛只用于比赛，去医院就诊要用看病。"}, {"text": "我爸爸明天要去邮局参赛。", "explanation": "这里应该用〈寄〉。参赛只用于比赛，去邮局寄东西要用寄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b3da8f-38fb-4b17-bfe6-56ca8c06d98f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95340, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我去年没参赛了。", "corrected_sentence": "我去年没参赛。", "error_description": "错误：“没”否定已发生的“参赛”时，句末不能加“了”。正确说法是“没参赛”，不说“没参赛了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b3da8f-38fb-4b17-bfe6-56ca8c06d98f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95340, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹被参赛了。", "corrected_sentence": "妹妹被选中参赛了。", "error_description": "错误：“参赛”是主动加入比赛的动作，不能直接用“被”引出。正确说法是“被选中参赛”，由“选中”表示被动。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b3da8f-38fb-4b17-bfe6-56ca8c06d98f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95341, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "施事", "is_correct": true, "explanation": "施事与受事是一对反义语法术语：施事是动作的发出者，受事是动作的承受者。"}, {"text": "主语", "is_correct": false, "explanation": "主语指句子陈述的对象，与受事不构成反义关系。"}, {"text": "谓语", "is_correct": false, "explanation": "谓语指陈述主语的部分，与受事不构成反义关系。"}, {"text": "定语", "is_correct": false, "explanation": "定语修饰中心语，与受事不构成反义关系。"}], "correct_answer": "施事", "explanations": {"施事": "施事与受事是一对反义语法术语：施事是动作的发出者，受事是动作的承受者。", "主语": "主语指句子陈述的对象，与受事不构成反义关系。", "谓语": "谓语指陈述主语的部分，与受事不构成反义关系。", "定语": "定语修饰中心语，与受事不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cdfabf4-1fd2-44eb-a396-a79b343c6c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95341, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "施事", "is_correct": true, "explanation": "施事与受事是一对反义语法术语：施事是动作的发出者，受事是动作的承受者。"}, {"text": "补语", "is_correct": false, "explanation": "补语补充说明动作的结果或程度，与受事不构成反义关系。"}, {"text": "状语", "is_correct": false, "explanation": "状语修饰动词或形容词，与受事不构成反义关系。"}, {"text": "同位语", "is_correct": false, "explanation": "同位语与前面的名词所指相同，与受事不构成反义关系。"}], "correct_answer": "施事", "explanations": {"施事": "施事与受事是一对反义语法术语：施事是动作的发出者，受事是动作的承受者。", "补语": "补语补充说明动作的结果或程度，与受事不构成反义关系。", "状语": "状语修饰动词或形容词，与受事不构成反义关系。", "同位语": "同位语与前面的名词所指相同，与受事不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cdfabf4-1fd2-44eb-a396-a79b343c6c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95341, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "句子里被动作碰到的那个东西或人。", "primary_collocate": null, "pronunciation": "shòu shì", "ipa": "ʂoʊ˥˩ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "在“我吃苹果”里，苹果是受事。", "target_word": "受事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“他打球”这句话里，球是受事。", "target_word": "受事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，动作碰到的人是受事。", "target_word": "受事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "句子里挨打的人是受事。", "target_word": "受事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在“妈妈洗衣服”中，衣服是受事。", "target_word": "受事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个句子的受事是“门”。", "target_word": "受事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请找出这句话的受事。", "target_word": "受事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "施事做动作，受事接受动作。", "target_word": "受事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“他关了门”里，门是受事。", "target_word": "受事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "课上我们学了受事和施事。", "target_word": "受事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "语法术语：句中承受动作的人或事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c29519-b224-40c3-87a0-c14ac1f50481') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95341, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "受事", "is_correct": true, "explanation": "受事（shòu shì）：句中被动作碰到的人或事物，即目标词。"}, {"text": "手势", "is_correct": false, "explanation": "手势（shǒu shì）的“shǒu”是第三声，与“shòu”（第四声）声调不同，意思是手的动作或姿势。"}, {"text": "收视", "is_correct": false, "explanation": "收视（shōu shì）的“shōu”是第一声，与“shòu”声调不同，意思是收看电视的情况。"}, {"text": "受制", "is_correct": false, "explanation": "受制（shòu zhì）的第二个音节“zhì”与“shì”声母不同（zh 与 sh），意思是受到约束或控制。"}], "explanations": {"受事": "受事（shòu shì）：句中被动作碰到的人或事物，即目标词。", "手势": "手势（shǒu shì）的“shǒu”是第三声，与“shòu”（第四声）声调不同，意思是手的动作或姿势。", "收视": "收视（shōu shì）的“shōu”是第一声，与“shòu”声调不同，意思是收看电视的情况。", "受制": "受制（shòu zhì）的第二个音节“zhì”与“shì”声母不同（zh 与 sh），意思是受到约束或控制。"}, "sentence_index": null, "correct_answer": "受事"}, "level_3": {"options": [{"text": "受事", "is_correct": true, "explanation": "受事：指“苹果”被“吃”这一动作影响，与“是”搭配，符合语境。"}, {"text": "施事", "is_correct": false, "explanation": "配价：“吃”的施事是“我”，“苹果”不能作施事。"}, {"text": "主语", "is_correct": false, "explanation": "配价：“我吃苹果”的主语是“我”，“苹果”不能作主语。"}, {"text": "谓语", "is_correct": false, "explanation": "语义：“吃”才是谓语，“苹果”不是陈述动作的成分。"}], "explanations": {"受事": "受事：指“苹果”被“吃”这一动作影响，与“是”搭配，符合语境。", "施事": "配价：“吃”的施事是“我”，“苹果”不能作施事。", "主语": "配价：“我吃苹果”的主语是“我”，“苹果”不能作主语。", "谓语": "语义：“吃”才是谓语，“苹果”不是陈述动作的成分。"}, "sentence_index": 0, "correct_answer": "受事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "在“我吃苹果”里，我是受事。", "explanation": "这里应该用〈施事〉。“我”发出“吃”的动作，是施事，不是受事。"}, {"text": "“我吃苹果”的受事是“我”。", "explanation": "这里应该用〈主语〉。“我”是句子的主语，受事应是被吃的“苹果”。"}, {"text": "在“我吃苹果”里，“吃”是受事。", "explanation": "这里应该用〈谓语〉。“吃”是陈述动作的谓语，不是被动作碰到的对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cdfabf4-1fd2-44eb-a396-a79b343c6c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95341, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "受事", "is_correct": true, "explanation": "受事：句中承受动作的成分，正是要找出的对象。"}, {"text": "身高", "is_correct": false, "explanation": "语义：句子没有身高，“身高”只用于人，不能说“这句话的身高”。"}, {"text": "长相", "is_correct": false, "explanation": "体貌：“长相”只说人或动物的外貌，不能用于句子。"}, {"text": "重量", "is_correct": false, "explanation": "语义：句子没有重量，“重量”指物体的分量，这里不合语境。"}], "explanations": {"受事": "受事：句中承受动作的成分，正是要找出的对象。", "身高": "语义：句子没有身高，“身高”只用于人，不能说“这句话的身高”。", "长相": "体貌：“长相”只说人或动物的外貌，不能用于句子。", "重量": "语义：句子没有重量，“重量”指物体的分量，这里不合语境。"}, "sentence_index": 6, "correct_answer": "受事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "“他跑得很快”里，“快”是受事。", "explanation": "这里应该用〈补语〉。“快”补充说明“跑”的程度，是补语，不是被动作影响的对象。"}, {"text": "“我昨天买书”里，“昨天”是受事。", "explanation": "这里应该用〈状语〉。“昨天”说明动作发生的时间，是状语，不是受事。"}, {"text": "“我的书”里，“我的”是受事。", "explanation": "这里应该用〈定语〉。“我的”修饰“书”，是定语，不是受事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cdfabf4-1fd2-44eb-a396-a79b343c6c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95341, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "在“他擦桌子”里，桌子受事。", "corrected_sentence": "在“他擦桌子”里，桌子是受事。", "error_description": "错误在“受事”前缺少系动词“是”。“桌子受事”不成句；应说“桌子是受事”，“是”连接主语与受事。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cdfabf4-1fd2-44eb-a396-a79b343c6c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
