INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95342, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "语法上指动作行为所支配或影响的对象。", "primary_collocate": null, "pronunciation": "shòu shì", "ipa": "ʂoʊ˥˩ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "“我读书”里，“书”是动作的受事。", "target_word": "受事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "受事是动作影响的对象。", "target_word": "受事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汉语的受事常常在动词后面。", "target_word": "受事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个动词后面常常带受事。", "target_word": "受事", "complexity_tier": "T3", "furigana": "zhè ge dòngcí hòumiàn chángcháng dài shòushì", "sentence_source": "generated"}, {"text": "老师让我们画出句子的受事。", "target_word": "受事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“我把书放好了”里，书是受事。", "target_word": "受事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写了一篇文章，专门讲“受事”这个语法术语。", "target_word": "受事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有的句子没有受事。", "target_word": "受事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书里有一课专讲受事。", "target_word": "受事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生问：“受事一定是名词吗？”", "target_word": "受事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "语法术语：动作行为支配或影响的对象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c29519-b224-40c3-87a0-c14ac1f50481') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95342, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "受事", "is_correct": true, "explanation": "受事（shòu shì）：句中承受动作支配或影响的对象，即目标词。"}, {"text": "手势", "is_correct": false, "explanation": "手势（shǒu shì）的“shǒu”是第三声，与“shòu”（第四声）声调不同，意思是手的动作或姿势。"}, {"text": "收视", "is_correct": false, "explanation": "收视（shōu shì）的“shōu”是第一声，与“shòu”声调不同，意思是收看电视的情况。"}, {"text": "受制", "is_correct": false, "explanation": "受制（shòu zhì）的第二个音节“zhì”与“shì”声母不同（zh 与 sh），意思是受到约束或控制。"}], "explanations": {"受事": "受事（shòu shì）：句中承受动作支配或影响的对象，即目标词。", "手势": "手势（shǒu shì）的“shǒu”是第三声，与“shòu”（第四声）声调不同，意思是手的动作或姿势。", "收视": "收视（shōu shì）的“shōu”是第一声，与“shòu”声调不同，意思是收看电视的情况。", "受制": "受制（shòu zhì）的第二个音节“zhì”与“shì”声母不同（zh 与 sh），意思是受到约束或控制。"}, "sentence_index": null, "correct_answer": "受事"}, "level_3": {"options": [{"text": "受事", "is_correct": true, "explanation": "受事：“书”被“读”这一动作影响，是动作的受事，符合语境。"}, {"text": "施事", "is_correct": false, "explanation": "配价：“读”的施事是“我”，“书”不能作施事。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“书”不是时间，不能作动作的时间。"}, {"text": "地点", "is_correct": false, "explanation": "语义：“书”不是地点，不能作动作的地点。"}], "explanations": {"受事": "受事：“书”被“读”这一动作影响，是动作的受事，符合语境。", "施事": "配价：“读”的施事是“我”，“书”不能作施事。", "时间": "语义：“书”不是时间，不能作动作的时间。", "地点": "语义：“书”不是地点，不能作动作的地点。"}, "sentence_index": 0, "correct_answer": "受事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "受事通常在动词前面。", "explanation": "这里应该用〈施事〉。汉语里施事一般在动词前，受事一般在动词后。"}, {"text": "受事通常放在被修饰的词前面。", "explanation": "这里应该用〈定语〉。定语才放在被修饰的词前面，受事是动词的对象，不放在那里。"}, {"text": "“他把书放好了”里，“好”是受事。", "explanation": "这里应该用〈补语〉。“好”说明“放”的结果，是补语，不是动作的对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cdfabf4-1fd2-44eb-a396-a79b343c6c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95342, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "受事", "is_correct": true, "explanation": "受事：句中承受动作的成分，是文章所讲的内容，符合语境。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：文章讲的是语法内容，不讲颜色。"}, {"text": "长相", "is_correct": false, "explanation": "体貌：“长相”只说人或动物的外貌，不能作文章的主题。"}, {"text": "嗓音", "is_correct": false, "explanation": "语义：文章是书面内容，不讲嗓音。"}], "explanations": {"受事": "受事：句中承受动作的成分，是文章所讲的内容，符合语境。", "颜色": "语义：文章讲的是语法内容，不讲颜色。", "长相": "体貌：“长相”只说人或动物的外貌，不能作文章的主题。", "嗓音": "语义：文章是书面内容，不讲嗓音。"}, "sentence_index": 6, "correct_answer": "受事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "“他明天来”里，“明天”是受事。", "explanation": "这里应该用〈状语〉。“明天”说明动作的时间，是状语，不是受事。"}, {"text": "“我读书”里，“我”是受事。", "explanation": "这里应该用〈主语〉。“我”是读书的人，是句子的主语，不是被动作影响的对象。"}, {"text": "“我读书”里，“读”是受事。", "explanation": "这里应该用〈谓语〉。“读”是陈述动作本身的谓语，不是承受动作的对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cdfabf4-1fd2-44eb-a396-a79b343c6c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95342, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "“他修自行车”里，“自行车”受事。", "corrected_sentence": "“他修自行车”里，“自行车”是受事。", "error_description": "错误在“受事”前缺少系动词“是”。“自行车受事”不成句，应说“自行车是受事”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cdfabf4-1fd2-44eb-a396-a79b343c6c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95342, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "及物动词一般只带一只受事。", "corrected_sentence": "及物动词一般只带一个受事。", "error_description": "错误在量词：“受事”是抽象的语法概念，不能用“只”（“只”多用于动物等），应说“一个受事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cdfabf4-1fd2-44eb-a396-a79b343c6c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
