INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95346, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "出家修行的佛教男性僧人。", "primary_collocate": null, "pronunciation": "hé shang", "ipa": "xɤ˧˥ ʂɑŋ", "syllable_count": 2, "sentences": [{"text": "这位和尚在山上修行了十年。", "target_word": "和尚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "和尚每天早上五点起床念经。", "target_word": "和尚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他二十岁出家，做了和尚。", "target_word": "和尚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "和尚不吃肉，也不喝酒。", "target_word": "和尚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山下来了一个和尚。", "target_word": "和尚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个和尚正在寺里打坐。", "target_word": "和尚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "和尚剃了光头，穿着灰色的长衣。", "target_word": "和尚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说这位和尚会看病。", "target_word": "和尚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三个和尚在大殿里念经。", "target_word": "和尚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了一个和尚的故事。", "target_word": "和尚", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "小和尚", "label": "复合"}, {"form": "老和尚", "label": "复合"}], "register": "中性", "sense_fingerprint": "和尚：出家修行的佛教男性僧人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '016a8d2a-68e4-4db2-b1cd-c081d7aad3bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95346, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "和尚", "is_correct": true, "explanation": "和尚 hé shang：出家修行的佛教男性僧人。"}, {"text": "合上", "is_correct": false, "explanation": "合上 hé shàng：与“和尚”第二个音节的声调不同，“shàng”为第四声，意思是合拢、关上。"}, {"text": "和善", "is_correct": false, "explanation": "和善 hé shàn：韵母不同（an 与 ang），意思是温和友善。"}, {"text": "何尝", "is_correct": false, "explanation": "何尝 hé cháng：声母不同（ch 与 sh），是副词，意思是“何曾”。"}], "explanations": {"和尚": "和尚 hé shang：出家修行的佛教男性僧人。", "合上": "合上 hé shàng：与“和尚”第二个音节的声调不同，“shàng”为第四声，意思是合拢、关上。", "和善": "和善 hé shàn：韵母不同（an 与 ang），意思是温和友善。", "何尝": "何尝 hé cháng：声母不同（ch 与 sh），是副词，意思是“何曾”。"}, "sentence_index": null, "correct_answer": "和尚"}, "level_3": {"options": [{"text": "和尚", "is_correct": true, "explanation": "和尚：出家修行的僧人，与“在山上修行了十年”相符。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：“修行”是宗教修炼，与厨师的职业身份不合。"}, {"text": "小孩", "is_correct": false, "explanation": "体貌：“小孩”年龄小，与“修行了十年”的时间不合。"}, {"text": "演员", "is_correct": false, "explanation": "语义：演员不从事宗教修行，与“修行”不合。"}], "explanations": {"和尚": "和尚：出家修行的僧人，与“在山上修行了十年”相符。", "厨师": "语义：“修行”是宗教修炼，与厨师的职业身份不合。", "小孩": "体貌：“小孩”年龄小，与“修行了十年”的时间不合。", "演员": "语义：演员不从事宗教修行，与“修行”不合。"}, "sentence_index": 0, "correct_answer": "和尚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她很早就出家，做了和尚。", "explanation": "这里应该用〈尼姑〉。和尚专指男性僧人，女性出家人称尼姑。"}, {"text": "他每天晚上都在和尚里念经。", "explanation": "这里应该用〈寺庙〉。和尚指人，不指场所，念经的地方应说“寺庙”。"}, {"text": "这条和尚每天在庙里念经。", "explanation": "这里应该用〈位〉。和尚指人，量词用“位”或“个”，“条”用于鱼、狗等动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d2236b-4500-4360-93e1-98363f6eb264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95346, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "和尚", "is_correct": true, "explanation": "和尚 hé shang：出家修行的佛教男性僧人。"}, {"text": "合唱", "is_correct": false, "explanation": "合唱 hé chàng：声母不同（ch 与 sh），意思是多人一起唱歌。"}, {"text": "合掌", "is_correct": false, "explanation": "合掌 hé zhǎng：声母不同（zh 与 sh），且声调不同，意思是双手合在一起。"}, {"text": "河长", "is_correct": false, "explanation": "河长 hé zhǎng：声母不同（zh 与 sh），意思是负责河道管理的官员。"}], "explanations": {"和尚": "和尚 hé shang：出家修行的佛教男性僧人。", "合唱": "合唱 hé chàng：声母不同（ch 与 sh），意思是多人一起唱歌。", "合掌": "合掌 hé zhǎng：声母不同（zh 与 sh），且声调不同，意思是双手合在一起。", "河长": "河长 hé zhǎng：声母不同（zh 与 sh），意思是负责河道管理的官员。"}, "sentence_index": null, "correct_answer": "和尚"}, "level_3": {"options": [{"text": "和尚", "is_correct": true, "explanation": "和尚：出家修行的僧人，与“剃了光头，穿着灰色的长衣”相符。"}, {"text": "石头", "is_correct": false, "explanation": "配价：“剃”和“穿着”需要人作主语，石头不能作主语。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能剃光头，也不能穿长衣。"}, {"text": "小猫", "is_correct": false, "explanation": "配价：“剃”和“穿着”需要人作主语，小猫不能作主语。"}], "explanations": {"和尚": "和尚：出家修行的僧人，与“剃了光头，穿着灰色的长衣”相符。", "石头": "配价：“剃”和“穿着”需要人作主语，石头不能作主语。", "桌子": "语义：桌子是家具，不能剃光头，也不能穿长衣。", "小猫": "配价：“剃”和“穿着”需要人作主语，小猫不能作主语。"}, "sentence_index": 6, "correct_answer": "和尚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在教堂里做了和尚，每个星期天主持礼拜。", "explanation": "这里应该用〈神父〉。和尚属佛教，教堂是基督教的场所，主持礼拜的神职人员称神父。"}, {"text": "他是医院里的和尚，每天给病人看病。", "explanation": "这里应该用〈医生〉。和尚是出家修行的僧人，不能用来称呼医务工作者。"}, {"text": "他是饭店里的和尚，每天做很多菜。", "explanation": "这里应该用〈厨师〉。和尚是出家修行的僧人，不能用来称呼做菜的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d2236b-4500-4360-93e1-98363f6eb264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95346, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "寺里住着两只和尚，每天一起念经。", "corrected_sentence": "寺里住着两个和尚，每天一起念经。", "error_description": "错误形式是“两只和尚”，正确形式是“两个和尚”。“只”用于动物，指人应用“个”或“位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d2236b-4500-4360-93e1-98363f6eb264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95346, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "院子里有五个和尚们在扫地。", "corrected_sentence": "院子里有五个和尚在扫地。", "error_description": "错误形式是“五个和尚们”，正确形式是“五个和尚”。“们”不能与数词加量词同用，数量词已表明人数。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d2236b-4500-4360-93e1-98363f6eb264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
