INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95348, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "岂料；没想到。", "primary_collocate": null, "pronunciation": "nǎ zhī dào", "ipa": "na˨˩ ʈʂɻ̩˥ taʊ̯˥˩", "syllable_count": 3, "sentences": [{"text": "我以为他会来，哪知道他没来。", "target_word": "哪知道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气很好，哪知道下午下起了大雨。", "target_word": "哪知道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他本想早点睡，哪知道朋友突然来了。", "target_word": "哪知道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们等了很久，哪知道车早就走了。", "target_word": "哪知道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说会帮我，哪知道自己也很忙。", "target_word": "哪知道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买这本书，哪知道已经卖完了。", "target_word": "哪知道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李准备了好久，哪知道考试取消了。", "target_word": "哪知道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本想去公园玩，哪知道公园关门了。", "target_word": "哪知道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他笑着进门，哪知道我正在生气。", "target_word": "哪知道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我以为很简单，哪知道做了三个小时。", "target_word": "哪知道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "表示事情的结果出乎意料，常接在“以为……”之后", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b37fbea5-e5a7-40fc-aef0-8c6a260a8c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95348, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "哪知道", "is_correct": true, "explanation": "正确：“哪知道”表示结果出乎意料，与前面的“以为”相呼应。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示立即，说明时间，不能表示结果出乎意料。"}, {"text": "已经", "is_correct": false, "explanation": "搭配：“已经”表示完成，与“以为会来”的假设接续不当，“已经他没来”不通。"}, {"text": "一直", "is_correct": false, "explanation": "搭配：“一直”表示持续，不能放在“他没来”前作转折。"}], "explanations": {"哪知道": "正确：“哪知道”表示结果出乎意料，与前面的“以为”相呼应。", "马上": "语义：“马上”表示立即，说明时间，不能表示结果出乎意料。", "已经": "搭配：“已经”表示完成，与“以为会来”的假设接续不当，“已经他没来”不通。", "一直": "搭配：“一直”表示持续，不能放在“他没来”前作转折。"}, "sentence_index": 0, "correct_answer": "哪知道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上都吃面包，哪知道今天也吃面包。", "explanation": "“哪知道”表示结果出乎意料，而“每天都吃面包，今天也吃面包”是平常的事，没有意外，不能用“哪知道”，直接说“今天也吃面包”即可。"}, {"text": "我以为他会来，哪知道他真的来了。", "explanation": "这里应该用〈果然〉。“哪知道”要表示结果与预想相反，而“真的来了”正与“以为会来”相符，不能用。"}, {"text": "春天到了，哪知道树木都绿了。", "explanation": "这里应该用〈果然〉。“哪知道”表示出乎意料，而“春天到了，树木都绿了”是意料之中的事，不能用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c46cb8d-7db9-433e-929e-cc38fb7b7492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95348, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "哪知道", "is_correct": true, "explanation": "正确：“哪知道”引出意外结果，与“准备了好久”之后考试取消的情况相符。"}, {"text": "一定", "is_correct": false, "explanation": "语义：“一定”表示确定，与“准备了好久”之后的意外结果不符。"}, {"text": "正在", "is_correct": false, "explanation": "搭配：“正在”表示动作进行中，与“考试取消了”的完成意义冲突，不能说“正在取消了”。"}, {"text": "一起", "is_correct": false, "explanation": "语义：“一起”表示共同、一块儿做某事，不能引出出乎意料的结果，“一起考试取消了”不通。"}], "explanations": {"哪知道": "正确：“哪知道”引出意外结果，与“准备了好久”之后考试取消的情况相符。", "一定": "语义：“一定”表示确定，与“准备了好久”之后的意外结果不符。", "正在": "搭配：“正在”表示动作进行中，与“考试取消了”的完成意义冲突，不能说“正在取消了”。", "一起": "语义：“一起”表示共同、一块儿做某事，不能引出出乎意料的结果，“一起考试取消了”不通。"}, "sentence_index": 6, "correct_answer": "哪知道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我以为他会迟到，哪知道他果然准时到了。", "explanation": "这里“哪知道”表示与预想相反，而句中的结果与“以为会迟到”的预想相符，应改用〈果真〉之类表示如所料的说法。"}, {"text": "这家店每周二都关门，哪知道今天真的关门了。", "explanation": "这里应该用〈果真〉。“哪知道”表示与预想相反，而“每周二都关门”与“今天真的关门了”相符，没有出乎意料之处。"}, {"text": "我们以为明天放假，哪知道明天果然放假了。", "explanation": "这里“哪知道”表示与预想相反，而句中的结果与“以为明天放假”的预想相符，应改用〈果真〉之类表示如所料的说法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c46cb8d-7db9-433e-929e-cc38fb7b7492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95348, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我本以为票很多，哪知道的早就卖完了。", "corrected_sentence": "我本以为票很多，哪知道早就卖完了。", "error_description": "助词错误：“哪知道”是副词，后面不能加“的”。应说“哪知道早就卖完了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c46cb8d-7db9-433e-929e-cc38fb7b7492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95348, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我特意早起，哪知道了今天放假。", "corrected_sentence": "我特意早起，哪知道今天放假。", "error_description": "助词错误：“哪知道”是副词，后面不能加“了”。应说“哪知道今天放假”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c46cb8d-7db9-433e-929e-cc38fb7b7492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
