INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95349, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不高兴或不信的时候，从鼻子里发出的声音。", "primary_collocate": null, "pronunciation": "hēng", "ipa": "xəŋ˥", "syllable_count": 1, "sentences": [{"text": "他听了我的话，从鼻子里哼了一声。", "target_word": "哼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板不信我，只是哼了一声。", "target_word": "哼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她不高兴，鼻子里哼了一下。", "target_word": "哼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸看了看成绩单，冷冷地哼了一声。", "target_word": "哼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不相信，轻轻哼了一下就走了。", "target_word": "哼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟不高兴时，总是用鼻子哼一声。", "target_word": "哼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我说我没钱，妈妈从鼻子里哼了一下。", "target_word": "哼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听到这个消息，他哼了一声，没有说话。", "target_word": "哼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师不信他的话，只哼了一声。", "target_word": "哼", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她看着我，鼻子里哼了一声，转身走了。", "target_word": "哼", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "哼了", "label": "体标"}, {"form": "哼着", "label": "体标"}, {"form": "哼过", "label": "体标"}], "register": "口语", "sense_fingerprint": "不高兴或不相信时从鼻子里发出声音", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17ff06e6-d05a-42d0-84b6-f1fd5eae80ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95349, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "哼", "is_correct": true, "explanation": "哼（hēng）：不高兴或不信的时候，从鼻子里发出的声音。"}, {"text": "横", "is_correct": false, "explanation": "横（héng）与 hēng 声调不同，是第二声，意思是横向。"}, {"text": "坑", "is_correct": false, "explanation": "坑（kēng）与 hēng 声母不同，k 与 h 不同，意思是坑洞。"}, {"text": "轰", "is_correct": false, "explanation": "轰（hōng）与 hēng 韵母不同，o 与 e 不同，意思是轰隆的声音。"}, {"text": "生", "is_correct": false, "explanation": "生（shēng）与 hēng 声母不同，sh 与 h 不同，意思是出生、生活。"}], "explanations": {"哼": "哼（hēng）：不高兴或不信的时候，从鼻子里发出的声音。", "横": "横（héng）与 hēng 声调不同，是第二声，意思是横向。", "坑": "坑（kēng）与 hēng 声母不同，k 与 h 不同，意思是坑洞。", "轰": "轰（hōng）与 hēng 韵母不同，o 与 e 不同，意思是轰隆的声音。", "生": "生（shēng）与 hēng 声母不同，sh 与 h 不同，意思是出生、生活。"}, "sentence_index": null, "correct_answer": "哼"}, "level_3": {"options": [{"text": "哼", "is_correct": true, "explanation": "哼：不高兴或不信时从鼻子里发出的声音，与“从鼻子里”搭配。"}, {"text": "喷", "is_correct": false, "explanation": "搭配：“喷”指液体或气体猛然射出，不能说从鼻子里发出声音。"}, {"text": "吹", "is_correct": false, "explanation": "搭配：“吹”多指送出气流或吹哨，不用于从鼻子发出不满的声音。"}, {"text": "吸", "is_correct": false, "explanation": "语义：“吸”是把气体吸入，与发出声音的动作相反。"}], "explanations": {"哼": "哼：不高兴或不信时从鼻子里发出的声音，与“从鼻子里”搭配。", "喷": "搭配：“喷”指液体或气体猛然射出，不能说从鼻子里发出声音。", "吹": "搭配：“吹”多指送出气流或吹哨，不用于从鼻子发出不满的声音。", "吸": "语义：“吸”是把气体吸入，与发出声音的动作相反。"}, "sentence_index": 0, "correct_answer": "哼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一见到我，高兴得直拍手，哼了一声。", "explanation": "这里应该用〈欢呼〉。“哼”表示不满或不屑，高兴时的声音要用“欢呼”之类的叫声，不能用“哼”。"}, {"text": "他看见老师，热情地哼了一声，打了个招呼。", "explanation": "这里应该改为〈说了声“你好”〉。“哼”表示不满或不信，热情打招呼不能“哼”一声。"}, {"text": "他向我道谢，哼了一声，表示感激。", "explanation": "这里应该改为〈说了声“谢谢”〉。“哼”表示不满或不屑，不能表示感激。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70428954-4397-48b4-b49b-6d906a67ae78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95349, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "哼", "is_correct": true, "explanation": "哼（hēng）：不高兴或不信的时候，从鼻子里发出的声音。"}, {"text": "恒", "is_correct": false, "explanation": "恒（héng）与 hēng 声调不同，是第二声，意思是长久、不变。"}, {"text": "烘", "is_correct": false, "explanation": "烘（hōng）与 hēng 韵母不同，o 与 e 不同，意思是用火或热气使干燥。"}, {"text": "烹", "is_correct": false, "explanation": "烹（pēng）与 hēng 声母不同，p 与 h 不同，意思是烹饪。"}, {"text": "哄", "is_correct": false, "explanation": "哄（hōng）与 hēng 韵母不同，o 与 e 不同，意思是哄劝、吵闹的声音。"}], "explanations": {"哼": "哼（hēng）：不高兴或不信的时候，从鼻子里发出的声音。", "恒": "恒（héng）与 hēng 声调不同，是第二声，意思是长久、不变。", "烘": "烘（hōng）与 hēng 韵母不同，o 与 e 不同，意思是用火或热气使干燥。", "烹": "烹（pēng）与 hēng 声母不同，p 与 h 不同，意思是烹饪。", "哄": "哄（hōng）与 hēng 韵母不同，o 与 e 不同，意思是哄劝、吵闹的声音。"}, "sentence_index": null, "correct_answer": "哼"}, "level_3": {"options": [{"text": "哼", "is_correct": true, "explanation": "哼：不高兴或不信时从鼻子里发出的声音，与“从鼻子里”搭配。"}, {"text": "吞", "is_correct": false, "explanation": "语义：“吞”指把东西咽下去，与发出声音的动作不符。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：“咬”要用嘴进行，不能从鼻子里咬。"}, {"text": "眨", "is_correct": false, "explanation": "搭配：“眨”是眼睛的动作，不能用来指鼻子发出的声音。"}], "explanations": {"哼": "哼：不高兴或不信时从鼻子里发出的声音，与“从鼻子里”搭配。", "吞": "语义：“吞”指把东西咽下去，与发出声音的动作不符。", "咬": "搭配：“咬”要用嘴进行，不能从鼻子里咬。", "眨": "搭配：“眨”是眼睛的动作，不能用来指鼻子发出的声音。"}, "sentence_index": 6, "correct_answer": "哼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她高兴地哼了一声，转身走了。", "explanation": "这里应该用〈笑〉。“哼”表示不满或不信的鼻音，高兴时应该是“笑了一声”。"}, {"text": "她接到录取通知，兴奋地哼了一声。", "explanation": "这里应该用〈叫〉。“哼”表示不满或不信，惊喜时应该说“兴奋地叫了一声”（如“哇”）。"}, {"text": "她听到孩子生病的消息，哽咽地哼了一声。", "explanation": "这里应该用〈叹〉。伤心时应该说“叹了一声”，“哼”表示不满或不屑，不能用在这里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70428954-4397-48b4-b49b-6d906a67ae78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95349, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他不服气，哼了一个声。", "corrected_sentence": "他不服气，哼了一声。", "error_description": "错误：“哼了一个声”；正确：“哼了一声”。表示声音的量词要用“声”，不能用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70428954-4397-48b4-b49b-6d906a67ae78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95349, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她哼着一声，不肯理我。", "corrected_sentence": "她哼了一声，不肯理我。", "error_description": "错误：“哼着一声”；正确：“哼了一声”。“哼”这一次发出声音的动作已经完成，要用“了”，不用“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70428954-4397-48b4-b49b-6d906a67ae78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
