INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95354, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "表示领会、明白的叹词。", "primary_collocate": null, "pronunciation": "ò", "ipa": "ɔ˥˩", "syllable_count": 1, "sentences": [{"text": "噢，我明白了，谢谢你。", "target_word": "噢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "噢，原来你是我同学的哥哥。", "target_word": "噢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说：“这里要用第四声。”我说：“噢，我懂了。”", "target_word": "噢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "噢，是这样啊，我以前不知道。", "target_word": "噢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "噢，你的意思是明天不上课？", "target_word": "噢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "噢，我听懂了，你是说红色的那个。", "target_word": "噢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说完以后，我点点头说：“噢。”", "target_word": "噢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "噢，难怪他今天这么高兴。", "target_word": "噢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "噢，那我明白你为什么不去了。", "target_word": "噢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“我们要坐地铁去。”“噢，好的，我知道了。”", "target_word": "噢", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "听了别人的解释后表示领会、明白", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40ccaa6c-88be-4174-ab0d-a617460feb36') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95354, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "噢", "is_correct": true, "explanation": "噢：表示领会、明白，符合“我明白了”的句意。"}, {"text": "嘘", "is_correct": false, "explanation": "语义：“嘘”表示让人安静，与“谢谢你”的应答语境不合。"}, {"text": "喂", "is_correct": false, "explanation": "语义：“喂”是招呼语，不表示领会。"}, {"text": "哼", "is_correct": false, "explanation": "语域：“哼”带轻蔑或不满的口气，与礼貌道谢的语域不合。"}], "explanations": {"噢": "噢：表示领会、明白，符合“我明白了”的句意。", "嘘": "语义：“嘘”表示让人安静，与“谢谢你”的应答语境不合。", "喂": "语义：“喂”是招呼语，不表示领会。", "哼": "语域：“哼”带轻蔑或不满的口气，与礼貌道谢的语域不合。"}, "sentence_index": 0, "correct_answer": "噢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "噢，我完全听不懂你在说什么。", "explanation": "这里应该用〈哎〉。噢表示领会、明白，这里说听不懂，表示困惑要用哎。"}, {"text": "噢，我的手好疼！", "explanation": "这里应该用〈哎哟〉。噢表示领会，表示疼痛要用哎哟。"}, {"text": "噢，我还是不清楚他为什么走。", "explanation": "这里应该用〈哎呀〉。噢表示领会，句中说仍不清楚，与之矛盾；着急、懊恼用哎呀。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b3da8f-38fb-4b17-bfe6-56ca8c06d98f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95354, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "噢", "is_correct": true, "explanation": "噢：表示领会，点头应答时说“噢”符合句意。"}, {"text": "嘘", "is_correct": false, "explanation": "语义：“嘘”表示让人安静，与点头应答的意思不合。"}, {"text": "呸", "is_correct": false, "explanation": "语域：“呸”表示唾弃，不能用于这种平和的应答。"}, {"text": "咳", "is_correct": false, "explanation": "语义：“咳”是咳嗽声，不是应答，与句意无关。"}], "explanations": {"噢": "噢：表示领会，点头应答时说“噢”符合句意。", "嘘": "语义：“嘘”表示让人安静，与点头应答的意思不合。", "呸": "语域：“呸”表示唾弃，不能用于这种平和的应答。", "咳": "语义：“咳”是咳嗽声，不是应答，与句意无关。"}, "sentence_index": 6, "correct_answer": "噢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "噢，我还是没看懂这张地图。", "explanation": "这里应该用〈哎〉。噢表示领会，句中说仍没看懂，与之矛盾；表示困惑用哎。"}, {"text": "噢，我完全不明白为什么今天又下雨了。", "explanation": "这里应该用〈哎〉。噢表示领会，句中说完全不明白，与之矛盾；表示困惑用哎。"}, {"text": "噢，我还是猜不到他为什么迟到。", "explanation": "这里应该用〈哎呀〉。噢表示领会，句中说仍猜不到，与之矛盾；着急、懊恼用哎呀。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b3da8f-38fb-4b17-bfe6-56ca8c06d98f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
