INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95356, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "国家的元首，是国家最高的职位之一。", "primary_collocate": null, "pronunciation": "guó jiā zhǔ xí", "ipa": "kuo˧˥ tɕja˥ ʈʂu˨˩ ɕi˧˥", "syllable_count": 4, "sentences": [{"text": "国家主席是国家最高的职位之一。", "target_word": "国家主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他工作了很多年，后来成了国家主席。", "target_word": "国家主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "选国家主席的会议在北京开。", "target_word": "国家主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家主席要代表国家接待外国客人。", "target_word": "国家主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家主席的工作非常忙。", "target_word": "国家主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的国家主席是一位女士。", "target_word": "国家主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家主席由全国人民代表大会选举产生。", "target_word": "国家主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想做国家主席，只想当老师。", "target_word": "国家主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家主席的任期是五年。", "target_word": "国家主席", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家主席上个月来我们城市参观了。", "target_word": "国家主席", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位国家主席", "label": "量词"}, {"form": "國家主席", "label": "繁体"}], "register": "正式", "sense_fingerprint": "国家元首的职位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f60e3e1-7e5c-4460-8a03-18319ddd28e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95356, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国家主席", "is_correct": true, "explanation": "正确：国家主席是国家的元首，是国家最高的职位之一。"}, {"text": "首都", "is_correct": false, "explanation": "语义：「首都」指首都城市，不是国家职位。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：「厨师」是职业，不是国家最高的职位。"}, {"text": "公园", "is_correct": false, "explanation": "搭配：「公园」是游览场所，不能与「职位」搭配。"}], "explanations": {"国家主席": "正确：国家主席是国家的元首，是国家最高的职位之一。", "首都": "语义：「首都」指首都城市，不是国家职位。", "厨师": "语义：「厨师」是职业，不是国家最高的职位。", "公园": "搭配：「公园」是游览场所，不能与「职位」搭配。"}, "sentence_index": 0, "correct_answer": "国家主席"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "国家主席要代表本市接待外国客人。", "explanation": "这里应该用〈市长〉。市长代表本市接待客人；国家主席代表国家，不能只代表一个城市。"}, {"text": "国家主席要代表学校接待外国客人。", "explanation": "这里应该用〈校长〉。校长代表学校接待客人；国家主席是国家元首，不能代表一所学校。"}, {"text": "这个社团的国家主席明天要去参加比赛。", "explanation": "这里应该用〈社长〉。社团的负责人应说社长，国家主席指国家最高领导人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79a7f742-7ea7-4ddd-8813-2caa673a1ddf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95356, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国家主席", "is_correct": true, "explanation": "正确：国家主席由全国人民代表大会选举产生，符合句中的语境。"}, {"text": "大熊猫", "is_correct": false, "explanation": "配价：「选举产生」要求人或团体作主体，大熊猫不能被选举。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：「图书馆」是场所，不能由代表大会选举产生。"}, {"text": "电视剧", "is_correct": false, "explanation": "语义：「电视剧」是影视作品，不能由代表大会选举产生。"}], "explanations": {"国家主席": "正确：国家主席由全国人民代表大会选举产生，符合句中的语境。", "大熊猫": "配价：「选举产生」要求人或团体作主体，大熊猫不能被选举。", "图书馆": "语义：「图书馆」是场所，不能由代表大会选举产生。", "电视剧": "语义：「电视剧」是影视作品，不能由代表大会选举产生。"}, "sentence_index": 6, "correct_answer": "国家主席"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司的国家主席下个月去德国出差。", "explanation": "这里应该用〈董事长〉。公司的负责人应说董事长，国家主席指国家元首。"}, {"text": "我们班的国家主席每天都帮老师发作业。", "explanation": "这里应该用〈班长〉。班级的负责人应说班长，国家主席指国家元首。"}, {"text": "病房里的国家主席每天给病人量体温。", "explanation": "这里应该用〈护士〉。给病人量体温的人应说护士，国家主席指国家元首。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79a7f742-7ea7-4ddd-8813-2caa673a1ddf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95356, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他终于当了上国家主席。", "corrected_sentence": "他终于当上了国家主席。", "error_description": "补语错误：「上」应紧跟动词「当」，说「当上」，「了」放在「上」后面，应说「当上了国家主席」，不能说「当了上」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79a7f742-7ea7-4ddd-8813-2caa673a1ddf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95356, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他当了五个年国家主席。", "corrected_sentence": "他当了五年国家主席。", "error_description": "量词错误：「年」本身可以直接跟数词，不需要量词「个」，应说「五年」，不能说「五个年」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79a7f742-7ea7-4ddd-8813-2caa673a1ddf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95357, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "私营", "is_correct": true, "explanation": "私营指私人经营，与国营（国家开办）相对，是反义词。"}, {"text": "寒冷", "is_correct": false, "explanation": "“寒冷”形容温度，与国营的所有制意义无关，不是反义词。"}, {"text": "聪明", "is_correct": false, "explanation": "“聪明”形容头脑，与国营的所有制意义无关，不是反义词。"}, {"text": "漂亮", "is_correct": false, "explanation": "“漂亮”形容外貌，与国营的所有制意义无关，不是反义词。"}], "correct_answer": "私营", "explanations": {"私营": "私营指私人经营，与国营（国家开办）相对，是反义词。", "寒冷": "“寒冷”形容温度，与国营的所有制意义无关，不是反义词。", "聪明": "“聪明”形容头脑，与国营的所有制意义无关，不是反义词。", "漂亮": "“漂亮”形容外貌，与国营的所有制意义无关，不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79a7f742-7ea7-4ddd-8813-2caa673a1ddf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95357, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "私营", "is_correct": true, "explanation": "私营指私人经营，与国营（国家开办）相对，是反义词。"}, {"text": "悲伤", "is_correct": false, "explanation": "“悲伤”形容情绪，与国营的所有制意义无关，不是反义词。"}, {"text": "高大", "is_correct": false, "explanation": "“高大”形容体型或高度，与国营的所有制意义无关，不是反义词。"}, {"text": "辛辣", "is_correct": false, "explanation": "“辛辣”形容味道，与国营的所有制意义无关，不是反义词。"}], "correct_answer": "私营", "explanations": {"私营": "私营指私人经营，与国营（国家开办）相对，是反义词。", "悲伤": "“悲伤”形容情绪，与国营的所有制意义无关，不是反义词。", "高大": "“高大”形容体型或高度，与国营的所有制意义无关，不是反义词。", "辛辣": "“辛辣”形容味道，与国营的所有制意义无关，不是反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79a7f742-7ea7-4ddd-8813-2caa673a1ddf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95357, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "由国家来开的，不是个人开的。", "primary_collocate": null, "pronunciation": "guó yíng", "ipa": "kwo˧˥ jiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这家商店是国营的，不是私人开的。", "target_word": "国营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷以前在一家国营工厂工作。", "target_word": "国营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国营饭店的菜又好吃又便宜。", "target_word": "国营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那时候，城里的大商店大多是国营的。", "target_word": "国营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国营书店里有很多旧书。", "target_word": "国营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家附近有一家国营医院。", "target_word": "国营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是国营农场，不是个人的。", "target_word": "国营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他爸爸在国营商店卖了三十年东西。", "target_word": "国营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司是私人的，不是国营的。", "target_word": "国营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候，我常去国营百货商店买糖。", "target_word": "国营", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "国营企业", "label": "复合"}], "register": "中性", "sense_fingerprint": "国家开办的，不是私人开办的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f60e3e1-7e5c-4460-8a03-18319ddd28e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95357, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "漂亮", "is_correct": false, "explanation": "语义：“漂亮”说外观，与“是国营还是私人开的”的语境无关。"}, {"text": "国营", "is_correct": true, "explanation": "国营指由国家开办，不是私人开办，与句中“不是私人开的”相符。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：“矮”描述高度，不能用来说明商店由谁开办。"}, {"text": "私营", "is_correct": false, "explanation": "语义：“私营”是私人经营，与“不是私人开的”正相矛盾。"}], "explanations": {"漂亮": "语义：“漂亮”说外观，与“是国营还是私人开的”的语境无关。", "国营": "国营指由国家开办，不是私人开办，与句中“不是私人开的”相符。", "矮": "体貌：“矮”描述高度，不能用来说明商店由谁开办。", "私营": "语义：“私营”是私人经营，与“不是私人开的”正相矛盾。"}, "sentence_index": 0, "correct_answer": "国营"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家门口的那棵大树是国营的。", "explanation": "这里把“国营”误用成了〈公共〉的意思。国营说的是由国家经营的单位，树不是单位，不能这样说。"}, {"text": "他爸爸是国营的，每天在家做饭。", "explanation": "这里把“国营”误用来形容人，误成了〈职业身份〉的意思。国营只说明单位的所有制，不能修饰人。"}, {"text": "这次考试是国营的，所有学生都要参加。", "explanation": "这里把“国营”误用成了〈全国性〉的意思。国营说的是单位由国家经营，考试不是单位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79a7f742-7ea7-4ddd-8813-2caa673a1ddf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95357, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "寒冷", "is_correct": false, "explanation": "语义：“寒冷”说温度，不能修饰农场，句子不通。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”形容人或动物的身形，不能修饰农场。"}, {"text": "国营", "is_correct": true, "explanation": "国营农场指由国家开办的农场，与“不是个人的”相符。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”形容人的头脑，不能用来修饰农场。"}], "explanations": {"寒冷": "语义：“寒冷”说温度，不能修饰农场，句子不通。", "瘦": "体貌：“瘦”形容人或动物的身形，不能修饰农场。", "国营": "国营农场指由国家开办的农场，与“不是个人的”相符。", "聪明": "语义：“聪明”形容人的头脑，不能用来修饰农场。"}, "sentence_index": 6, "correct_answer": "国营"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天上那朵云是国营的，谁都能看见。", "explanation": "这里把“国营”误用成了〈公开〉的意思。国营说的是由国家经营的单位，云不是单位，不能这样说。"}, {"text": "我养的那只小狗是国营的，很听话。", "explanation": "这里把“国营”误用成了〈公家养的〉的意思。国营说的是单位由国家经营，小狗不是单位，不能这样说。"}, {"text": "我和她的友谊是国营的，很长久。", "explanation": "这里把“国营”误用成了〈共同〉的意思。国营只修饰由国家经营的单位，友谊不是单位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79a7f742-7ea7-4ddd-8813-2caa673a1ddf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95357, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家饭店很国营的，价格比较低。", "corrected_sentence": "这家饭店是国营的，价格比较低。", "error_description": "“国营”表示所有制，不能受程度副词“很”修饰；作谓语时要说“是国营的”，不能把“是”换成“很”，说成“很国营的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79a7f742-7ea7-4ddd-8813-2caa673a1ddf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95357, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座城市有一家很国营剧院，每周都演出。", "corrected_sentence": "这座城市有一家国营剧院，每周都演出。", "error_description": "“国营”表示所有制，不能受程度副词“很”修饰；修饰名词时前面不能加“很”，应说“一家国营剧院”，不能说“一家很国营剧院”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79a7f742-7ea7-4ddd-8813-2caa673a1ddf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95358, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "私营", "is_correct": true, "explanation": "私营指私人经营，与国营（国家投资经营）相对，是反义词。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”形容明白或清晰，与国营的所有制意义无关，不是反义词。"}, {"text": "宽广", "is_correct": false, "explanation": "“宽广”形容面积或范围大，与国营的所有制意义无关，不是反义词。"}, {"text": "迟钝", "is_correct": false, "explanation": "“迟钝”形容反应慢，与国营的所有制意义无关，不是反义词。"}], "correct_answer": "私营", "explanations": {"私营": "私营指私人经营，与国营（国家投资经营）相对，是反义词。", "清楚": "“清楚”形容明白或清晰，与国营的所有制意义无关，不是反义词。", "宽广": "“宽广”形容面积或范围大，与国营的所有制意义无关，不是反义词。", "迟钝": "“迟钝”形容反应慢，与国营的所有制意义无关，不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79a7f742-7ea7-4ddd-8813-2caa673a1ddf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95358, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "私营", "is_correct": true, "explanation": "私营指私人经营，与国营（国家投资经营）相对，是反义词。"}, {"text": "寒冷", "is_correct": false, "explanation": "“寒冷”形容温度，与国营的所有制意义无关，不是反义词。"}, {"text": "高大", "is_correct": false, "explanation": "“高大”形容体型或高度，与国营的所有制意义无关，不是反义词。"}, {"text": "辛辣", "is_correct": false, "explanation": "“辛辣”形容味道，与国营的所有制意义无关，不是反义词。"}], "correct_answer": "私营", "explanations": {"私营": "私营指私人经营，与国营（国家投资经营）相对，是反义词。", "寒冷": "“寒冷”形容温度，与国营的所有制意义无关，不是反义词。", "高大": "“高大”形容体型或高度，与国营的所有制意义无关，不是反义词。", "辛辣": "“辛辣”形容味道，与国营的所有制意义无关，不是反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79a7f742-7ea7-4ddd-8813-2caa673a1ddf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95358, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "由国家投资经营的。", "primary_collocate": null, "pronunciation": "guó yíng", "ipa": "kwo˧˥ jiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "国家投钱办了这家国营企业。", "target_word": "国营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国营企业的工人工资比较稳定。", "target_word": "国营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家国营银行在全国有很多分行。", "target_word": "国营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他毕业后想进国营公司工作。", "target_word": "国营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国营电视台每天播放新闻。", "target_word": "国营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条铁路是国营的，由国家管理。", "target_word": "国营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国营工厂生产的产品，质量都不错。", "target_word": "国营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府给国营医院很多钱。", "target_word": "国营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国营农场种了很多苹果。", "target_word": "国营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国营企业也要学会赚钱。", "target_word": "国营", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "国营企业", "label": "复合"}], "register": "中性", "sense_fingerprint": "国家投资并经营的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f60e3e1-7e5c-4460-8a03-18319ddd28e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95358, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "甜", "is_correct": false, "explanation": "语义：“甜”描述味道，不能用来修饰企业。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”形容人或动物的身形，不能用来修饰企业。"}, {"text": "国营", "is_correct": true, "explanation": "国营指由国家投资经营，与“国家投钱办”的语境相符。"}, {"text": "私营", "is_correct": false, "explanation": "语义：“私营”指私人经营，与“国家投钱办”正相矛盾。"}], "explanations": {"甜": "语义：“甜”描述味道，不能用来修饰企业。", "瘦": "体貌：“瘦”形容人或动物的身形，不能用来修饰企业。", "国营": "国营指由国家投资经营，与“国家投钱办”的语境相符。", "私营": "语义：“私营”指私人经营，与“国家投钱办”正相矛盾。"}, "sentence_index": 0, "correct_answer": "国营"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我姐姐是国营的，她很喜欢画画。", "explanation": "这里把“国营”误用来形容人，误成了〈职业身份〉的意思。国营说的是单位由国家投资经营，不能修饰人。"}, {"text": "天上的太阳是国营的，每天都很亮。", "explanation": "这里把“国营”误用成了〈公共〉的意思。国营说的是由国家投资经营的单位，太阳不是单位。"}, {"text": "他的梦想是国营的，一直没有改变。", "explanation": "这里把“国营”误用成了〈共有〉的意思。国营只修饰由国家投资经营的单位，梦想不是单位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79a7f742-7ea7-4ddd-8813-2caa673a1ddf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95358, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "悲伤", "is_correct": false, "explanation": "语义：“悲伤”形容情绪，不能用来修饰工厂，句子不通。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：“矮”形容高度，不能用来修饰工厂。"}, {"text": "国营", "is_correct": true, "explanation": "国营工厂指由国家投资经营的工厂，与句中“产品质量不错”的语境相符。"}, {"text": "辣", "is_correct": false, "explanation": "语义：“辣”形容味道，不能用来修饰工厂。"}], "explanations": {"悲伤": "语义：“悲伤”形容情绪，不能用来修饰工厂，句子不通。", "矮": "体貌：“矮”形容高度，不能用来修饰工厂。", "国营": "国营工厂指由国家投资经营的工厂，与句中“产品质量不错”的语境相符。", "辣": "语义：“辣”形容味道，不能用来修饰工厂。"}, "sentence_index": 6, "correct_answer": "国营"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家的小猫是国营的，每天都陪我玩。", "explanation": "这里把“国营”误用成了〈公家养的〉的意思。国营说的是单位由国家投资经营，小猫不是单位，不能这样说。"}, {"text": "明天的天气是国营的，大家都很期待。", "explanation": "这里把“国营”误用成了〈全民所有〉的意思。国营说的是由国家投资经营的单位，天气不是单位。"}, {"text": "这个笑话是国营的，大家都笑了。", "explanation": "这里把“国营”误用成了〈公开〉的意思。国营说的是由国家投资经营的单位，笑话不是单位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79a7f742-7ea7-4ddd-8813-2caa673a1ddf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95358, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座公园很国营的，门票比较便宜。", "corrected_sentence": "这座公园是国营的，门票比较便宜。", "error_description": "“国营”表示所有制，不能受程度副词“很”修饰；作谓语时要说“是国营的”，不能把“是”换成“很”，说成“很国营的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79a7f742-7ea7-4ddd-8813-2caa673a1ddf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95358, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家电台不国营的，是私人的。", "corrected_sentence": "这家电台不是国营的，是私人的。", "error_description": "“国营”作谓语时要说“是国营的”，否定要说“不是国营的”，不能漏掉“是”，说成“不国营的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79a7f742-7ea7-4ddd-8813-2caa673a1ddf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
