INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95359, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "打到别的国家去的电话。", "primary_collocate": null, "pronunciation": "guó jì diàn huà", "ipa": "kwɔ˧˥ tɕi˥˩ tjɛn˥˩ xwa˥˩", "syllable_count": 4, "sentences": [{"text": "我想打一个国际电话去日本。", "target_word": "国际电话", "complexity_tier": "T3", "furigana": "wǒ xiǎng dǎ yí ge guójì diànhuà qù Rìběn", "sentence_source": "generated"}, {"text": "国际电话要先拨国家号码。", "target_word": "国际电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥在英国，我想给他打国际电话。", "target_word": "国际电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，国际电话怎么打？", "target_word": "国际电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话费很高，因为那是国际电话。", "target_word": "国际电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她拨了一个国际电话，马上说起英语。", "target_word": "国际电话", "complexity_tier": "T3", "furigana": "tā bō le yí ge guójì diànhuà, mǎshàng shuō qǐ Yīngyǔ", "sentence_source": "generated"}, {"text": "这是一个打到法国的国际电话。", "target_word": "国际电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国际电话一分钟要多少钱？", "target_word": "国际电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在办公室里给国外的家人打国际电话。", "target_word": "国际电话", "complexity_tier": "T3", "furigana": "tā zài bàngōngshì lǐ gěi guówài de jiārén dǎ guójì diànhuà", "sentence_source": "generated"}, {"text": "我家的电话不能打国际电话。", "target_word": "国际电话", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "通", "label": "量词"}], "register": "中性", "sense_fingerprint": "打到别的国家去的电话，强调跨国拨打", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c29519-b224-40c3-87a0-c14ac1f50481') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95359, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国际电话", "is_correct": true, "explanation": "国际电话：打到外国的电话，与“去日本”相合，符合语境。"}, {"text": "国内电话", "is_correct": false, "explanation": "语义：“去日本”说明打到国外，“国内电话”与之矛盾。"}, {"text": "电脑", "is_correct": false, "explanation": "搭配：“打”不与“电脑”搭配，不能说打电脑去日本。"}, {"text": "空调", "is_correct": false, "explanation": "搭配：“打”不与“空调”搭配，不能说打空调去日本。"}], "explanations": {"国际电话": "国际电话：打到外国的电话，与“去日本”相合，符合语境。", "国内电话": "语义：“去日本”说明打到国外，“国内电话”与之矛盾。", "电脑": "搭配：“打”不与“电脑”搭配，不能说打电脑去日本。", "空调": "搭配：“打”不与“空调”搭配，不能说打空调去日本。"}, "sentence_index": 0, "correct_answer": "国际电话"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在北京，想给上海的同学打国际电话。", "explanation": "这里应该用〈国内电话〉。国际电话是打到别的国家去的电话，北京在国内，应该用国内电话。"}, {"text": "他去上海出差，打国际电话回北京的家。", "explanation": "这里应该用〈长途电话〉。北京在国内，国际电话指打到国外，应该用长途电话。"}, {"text": "我昨晚接到一封国际电话。", "explanation": "这里应该用〈通〉。电话用“通”或“个”计量，“封”用于信件，不能用于电话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cdfabf4-1fd2-44eb-a396-a79b343c6c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95359, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国际电话", "is_correct": true, "explanation": "国际电话：打到外国的电话，与“打到法国”相合，符合语境。"}, {"text": "本地电话", "is_correct": false, "explanation": "语义：本地电话是本地通话，与“打到法国的”矛盾。"}, {"text": "电视", "is_correct": false, "explanation": "搭配：“打”不与“电视”搭配，不能说打到法国的电视。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“打到法国的”修饰的是电话，不能是天气。"}], "explanations": {"国际电话": "国际电话：打到外国的电话，与“打到法国”相合，符合语境。", "本地电话": "语义：本地电话是本地通话，与“打到法国的”矛盾。", "电视": "搭配：“打”不与“电视”搭配，不能说打到法国的电视。", "天气": "语义：“打到法国的”修饰的是电话，不能是天气。"}, "sentence_index": 6, "correct_answer": "国际电话"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在北京，给住在北京的朋友打国际电话。", "explanation": "这里应该用〈市内电话〉。朋友也在北京，是本地通话，国际电话指打到别的国家去的电话。"}, {"text": "妈妈昨天打来一首国际电话。", "explanation": "这里应该用〈通〉。“首”用于诗歌、歌曲，电话不用“首”。"}, {"text": "她打了一根国际电话给我。", "explanation": "这里应该用〈个〉。“根”用于细长的东西，电话不用“根”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cdfabf4-1fd2-44eb-a396-a79b343c6c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95359, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想给巴黎的姐姐打一张国际电话。", "corrected_sentence": "我想给巴黎的姐姐打一个国际电话。", "error_description": "错误在量词：“电话”应用“个”或“通”，不能用“张”（“张”用于纸张、桌子等）。应说“一个国际电话”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cdfabf4-1fd2-44eb-a396-a79b343c6c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95359, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他想给巴西的朋友打一把国际电话。", "corrected_sentence": "他想给巴西的朋友打一个国际电话。", "error_description": "量词错误：“电话”应用“个”或“通”，不能用“把”（“把”用于有柄的东西）。应说“一个国际电话”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cdfabf4-1fd2-44eb-a396-a79b343c6c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
