INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95360, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "与外国之间通话的电话。", "primary_collocate": null, "pronunciation": "guó jì diàn huà", "ipa": "kwɔ˧˥ tɕi˥˩ tjɛn˥˩ xwa˥˩", "syllable_count": 4, "sentences": [{"text": "我给在美国的朋友打了国际电话。", "target_word": "国际电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国际电话比国内电话贵。", "target_word": "国际电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天晚上妈妈接到一个国际电话。", "target_word": "国际电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手机可以打国际电话吗？", "target_word": "国际电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每个星期都打国际电话回家。", "target_word": "国际电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打国际电话以前，先看一下时间。", "target_word": "国际电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张卡可以便宜地打国际电话。", "target_word": "国际电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在宾馆里打过国际电话。", "target_word": "国际电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国际电话的声音有点儿小。", "target_word": "国际电话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很想家，常常打国际电话。", "target_word": "国际电话", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "通", "label": "量词"}], "register": "中性", "sense_fingerprint": "与外国之间通话的电话，常与打、接搭配", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c29519-b224-40c3-87a0-c14ac1f50481') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95360, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国际电话", "is_correct": true, "explanation": "国际电话：打到外国的电话，与“在美国的朋友”相合，符合语境。"}, {"text": "国内电话", "is_correct": false, "explanation": "语义：朋友在美国，打“国内电话”与语境矛盾。"}, {"text": "电脑", "is_correct": false, "explanation": "搭配：“打”不与“电脑”搭配，不能说打电脑给朋友。"}, {"text": "电视", "is_correct": false, "explanation": "搭配：“打”不与“电视”搭配，不能说打电视给朋友。"}], "explanations": {"国际电话": "国际电话：打到外国的电话，与“在美国的朋友”相合，符合语境。", "国内电话": "语义：朋友在美国，打“国内电话”与语境矛盾。", "电脑": "搭配：“打”不与“电脑”搭配，不能说打电脑给朋友。", "电视": "搭配：“打”不与“电视”搭配，不能说打电视给朋友。"}, "sentence_index": 0, "correct_answer": "国际电话"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在上海，给住在湖南老家的父母打了国际电话。", "explanation": "这里应该用〈长途电话〉。国际电话指打到外国的电话，湖南在国内，应该用长途电话。"}, {"text": "我在北京，想给上海的同学打国际电话。", "explanation": "这里应该用〈国内电话〉。国际电话是打到别的国家去的电话，上海在国内，应该用国内电话。"}, {"text": "我接到一只国际电话。", "explanation": "这里应该用〈个〉。电话用“个”或“通”计量，“只”用于动物等，不用于电话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cdfabf4-1fd2-44eb-a396-a79b343c6c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95360, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国际电话", "is_correct": true, "explanation": "国际电话：打到外国的电话，可以用这张卡便宜地拨打，符合语境。"}, {"text": "电影", "is_correct": false, "explanation": "搭配：“打”不与“电影”搭配，不能说打电影。"}, {"text": "礼物", "is_correct": false, "explanation": "搭配：“打”不与“礼物”搭配，不能说打礼物。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“打”的对象不能是天气，这句话说的是打电话。"}], "explanations": {"国际电话": "国际电话：打到外国的电话，可以用这张卡便宜地拨打，符合语境。", "电影": "搭配：“打”不与“电影”搭配，不能说打电影。", "礼物": "搭配：“打”不与“礼物”搭配，不能说打礼物。", "天气": "语义：“打”的对象不能是天气，这句话说的是打电话。"}, "sentence_index": 6, "correct_answer": "国际电话"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她在上海，常常给住在上海的弟弟打国际电话。", "explanation": "这里应该用〈市内电话〉。弟弟也在上海，是本地通话，国际电话指打到国外的电话。"}, {"text": "她很想家，常常打一首国际电话。", "explanation": "这里应该用〈通〉。“首”用于诗歌、歌曲，电话不用“首”。"}, {"text": "她很想家，常常打一根国际电话。", "explanation": "这里应该用〈个〉。“根”用于细长的东西，电话不用“根”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cdfabf4-1fd2-44eb-a396-a79b343c6c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95360, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每次出差都会打一只国际电话回家。", "corrected_sentence": "他每次出差都会打一个国际电话回家。", "error_description": "错误在量词：电话应用“个”或“通”，不能用“只”（“只”多用于动物等）。应说“一个国际电话”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cdfabf4-1fd2-44eb-a396-a79b343c6c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95360, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她刚才打了完一通国际电话。", "corrected_sentence": "她刚才打完了一通国际电话。", "error_description": "错误在补语位置：“打完”是动补结构，“完”应紧接“打”，“了”放在“完”后。应说“打完了”，不能说“打了完”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cdfabf4-1fd2-44eb-a396-a79b343c6c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
