INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95363, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很多人聚在一起形成的一大群人。", "primary_collocate": null, "pronunciation": "dà duì", "ipa": "ta˥˩ tweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "一大队人走进了小村子。", "target_word": "大队", "complexity_tier": "T3", "furigana": "yī dà duì rén zǒu jìn le xiǎo cūn zi", "sentence_source": "generated"}, {"text": "山下来了一大队游客。", "target_word": "大队", "complexity_tier": "T3", "furigana": "shān xià lái le yī dà duì yóu kè", "sentence_source": "generated"}, {"text": "路上来了一大队学生。", "target_word": "大队", "complexity_tier": "T3", "furigana": "lù shang lái le yī dà duì xué sheng", "sentence_source": "generated"}, {"text": "一大队人跟着老师去公园。", "target_word": "大队", "complexity_tier": "T3", "furigana": "yī dà duì rén gēn zhe lǎo shī qù gōng yuán", "sentence_source": "generated"}, {"text": "一大队客人都到了饭店门口。", "target_word": "大队", "complexity_tier": "T3", "furigana": "yī dà duì kè rén dōu dào le fàn diàn mén kǒu", "sentence_source": "generated"}, {"text": "他带着一大队人回家了。", "target_word": "大队", "complexity_tier": "T3", "furigana": "tā dài zhe yī dà duì rén huí jiā le", "sentence_source": "generated"}, {"text": "看，一大队工人往工厂走去。", "target_word": "大队", "complexity_tier": "T3", "furigana": "kàn yī dà duì gōng rén wǎng gōng chǎng zǒu qù", "sentence_source": "generated"}, {"text": "一大队人在门外等着你。", "target_word": "大队", "complexity_tier": "T3", "furigana": "yī dà duì rén zài mén wài děng zhe nǐ", "sentence_source": "generated"}, {"text": "一大队人排着队上了车。", "target_word": "大队", "complexity_tier": "T3", "furigana": "yī dà duì rén pái zhe duì shàng le chē", "sentence_source": "generated"}, {"text": "节日里，一大队游客走进了公园。", "target_word": "大队", "complexity_tier": "T3", "furigana": "jié rì lǐ yī dà duì yóu kè zǒu jìn le gōng yuán", "sentence_source": "generated"}], "morphological_forms": [{"form": "大隊", "label": "繁体"}, {"form": "大队人马", "label": "复合词"}], "register": "中性", "sense_fingerprint": "很多人聚在一起的一大群人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ec53b00-6195-460c-9dc7-5a5e3f5ff1e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95363, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "瓶", "is_correct": false, "explanation": "语义：“瓶”是盛液体的器具，装不下人，不能说“一瓶人”。"}, {"text": "大队", "is_correct": true, "explanation": "“一大队人”指由很多人合在一起的一群人，符合句意。"}, {"text": "箱", "is_correct": false, "explanation": "语义：“箱”是装东西的容器，不能装人，“一箱人”说不通。"}, {"text": "手", "is_correct": false, "explanation": "搭配：“一手”指一只手或一种本领，不能用来数人。"}], "explanations": {"瓶": "语义：“瓶”是盛液体的器具，装不下人，不能说“一瓶人”。", "大队": "“一大队人”指由很多人合在一起的一群人，符合句意。", "箱": "语义：“箱”是装东西的容器，不能装人，“一箱人”说不通。", "手": "搭配：“一手”指一只手或一种本领，不能用来数人。"}, "sentence_index": 0, "correct_answer": "大队"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "山上长着一大队树。", "explanation": "这里应该用〈一大片〉。大队指一群人或军队、学校的编制单位，成片的树林要用〈大片〉。"}, {"text": "他有一大队问题要解决。", "explanation": "这里应该用〈一大堆〉。大队只用于一群人或编制单位，抽象的问题不能用它作量词。"}, {"text": "他口袋里装着一大队铅笔。", "explanation": "这里应该用〈一大把〉。大队只用于人群或编制单位，成把的铅笔不能用它作量词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '941e0a09-4e7f-42c2-bcae-44406f5b4567') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95363, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "桶", "is_correct": false, "explanation": "语义：“桶”是盛水或装东西的容器，不能装工人，“一桶工人”说不通。"}, {"text": "大队", "is_correct": true, "explanation": "“一大队工人”指一群工人，符合句意。"}, {"text": "盆", "is_correct": false, "explanation": "语义：“盆”是盛物的器皿，装不下工人，“一盆工人”说不通。"}, {"text": "宫廷", "is_correct": false, "explanation": "语义：“宫廷”指帝王的朝廷，不是一群工人，“一宫廷工人”说不通。"}], "explanations": {"桶": "语义：“桶”是盛水或装东西的容器，不能装工人，“一桶工人”说不通。", "大队": "“一大队工人”指一群工人，符合句意。", "盆": "语义：“盆”是盛物的器皿，装不下工人，“一盆工人”说不通。", "宫廷": "语义：“宫廷”指帝王的朝廷，不是一群工人，“一宫廷工人”说不通。"}, "sentence_index": 6, "correct_answer": "大队"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "港口运来了一大队货物。", "explanation": "这里应该用〈一大批〉。大队用于一群人或编制单位，成批的货物要用〈批〉。"}, {"text": "书桌上放着一大队书。", "explanation": "这里应该用〈一大摞〉。大队用于一群人，成摞的书要用〈摞〉。"}, {"text": "床上堆着一大队棉花。", "explanation": "这里应该用〈一大团〉。大队用于人群，团状的棉花要用〈团〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '941e0a09-4e7f-42c2-bcae-44406f5b4567') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95363, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一大队们在门口排着队。", "corrected_sentence": "一大队人在门口排着队。", "error_description": "错误：“人”误写成了“们”。“们”不能用在数量词“一大队”之后，应说“一大队人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '941e0a09-4e7f-42c2-bcae-44406f5b4567') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95363, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一大队个人在公园门口集合。", "corrected_sentence": "一大队人在公园门口集合。", "error_description": "错误：“个”与“一大队”重复，数量词之后不能再加量词“个”，应说“一大队人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '941e0a09-4e7f-42c2-bcae-44406f5b4567') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
