INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95364, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "军队、学校等中比中队更大的编队。", "primary_collocate": null, "pronunciation": "dà duì", "ipa": "ta˥˩ tweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "这个大队有三百多个战士。", "target_word": "大队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校有一个大队，下面分成好几个中队。", "target_word": "大队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在大队工作了五年。", "target_word": "大队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大队里的人比中队多得多。", "target_word": "大队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们大队今天上午开会。", "target_word": "大队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个大队都有自己的旗子。", "target_word": "大队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个大队的同学都爱劳动。", "target_word": "大队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从中队调到了大队。", "target_word": "大队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支军队分成了三个大队。", "target_word": "大队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们大队明天去公园做活动。", "target_word": "大队", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "大隊", "label": "繁体"}, {"form": "大队长", "label": "复合词"}, {"form": "大队部", "label": "复合词"}], "register": "中性", "sense_fingerprint": "军队或学校里比中队更大的编队", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ec53b00-6195-460c-9dc7-5a5e3f5ff1e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95364, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "瓶", "is_correct": false, "explanation": "语义：“瓶”是盛液体的器具，装不下三百多个战士，“这个瓶有三百多个战士”说不通。"}, {"text": "大队", "is_correct": true, "explanation": "“大队”指军队或学校中比中队大的编制单位，正合句意。"}, {"text": "箱", "is_correct": false, "explanation": "语义：“箱”是装东西的容器，不能作为编制单位装战士，“这个箱有三百多个战士”说不通。"}, {"text": "身躯", "is_correct": false, "explanation": "语义：“身躯”指一个人的身体，不能指由三百多个战士组成的编制单位。"}], "explanations": {"瓶": "语义：“瓶”是盛液体的器具，装不下三百多个战士，“这个瓶有三百多个战士”说不通。", "大队": "“大队”指军队或学校中比中队大的编制单位，正合句意。", "箱": "语义：“箱”是装东西的容器，不能作为编制单位装战士，“这个箱有三百多个战士”说不通。", "身躯": "语义：“身躯”指一个人的身体，不能指由三百多个战士组成的编制单位。"}, "sentence_index": 0, "correct_answer": "大队"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班是一个大队。", "explanation": "这里应该用〈中队〉。大队比中队大，一个班只是一个中队，不能称作大队。"}, {"text": "一个中队下面分成好几个大队。", "explanation": "大队比中队大，应该是一个大队下面分成好几个中队。"}, {"text": "他从大队升到了中队，管的人更多了。", "explanation": "中队比大队小，从大队到中队管的人会更少，应说从中队升到大队。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '941e0a09-4e7f-42c2-bcae-44406f5b4567') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95364, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "桶", "is_correct": false, "explanation": "语义：“桶”是容器，不能指同学所在的集体，“这个桶的同学”说不通。"}, {"text": "大队", "is_correct": true, "explanation": "“这个大队的同学”指这个编制单位里的同学，符合句意。"}, {"text": "锅", "is_correct": false, "explanation": "语义：“锅”是炊具，不能指同学所在的集体，“这个锅的同学”说不通。"}, {"text": "宫廷", "is_correct": false, "explanation": "语义：“宫廷”指朝廷或宫殿，不能指同学所在的集体，“这个宫廷的同学”说不通。"}], "explanations": {"桶": "语义：“桶”是容器，不能指同学所在的集体，“这个桶的同学”说不通。", "大队": "“这个大队的同学”指这个编制单位里的同学，符合句意。", "锅": "语义：“锅”是炊具，不能指同学所在的集体，“这个锅的同学”说不通。", "宫廷": "语义：“宫廷”指朝廷或宫殿，不能指同学所在的集体，“这个宫廷的同学”说不通。"}, "sentence_index": 6, "correct_answer": "大队"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "中队里的人比大队多得多。", "explanation": "大队比中队大，大队里的人比中队多，不是中队比大队多。"}, {"text": "我们中队下面有三个大队。", "explanation": "大队是比中队更大的编队，中队下面不能有大队。"}, {"text": "我们家是一个大队。", "explanation": "大队是军队、学校等的编制单位，一个家庭不能叫大队。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '941e0a09-4e7f-42c2-bcae-44406f5b4567') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95364, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个大队分成了三个大队。", "corrected_sentence": "这个大队分成了三个中队。", "error_description": "错误：后面的“大队”用错了。大队比中队大，一个大队下面分成的是几个中队，不能再分成大队，应说“三个中队”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '941e0a09-4e7f-42c2-bcae-44406f5b4567') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95364, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只大队有三百多个战士。", "corrected_sentence": "这支大队有三百多个战士。", "error_description": "量词用错：指军队单位的“大队”要用量词“支”，“只”指动物或单个小物件，不能用来修饰“大队”，应为“这支大队”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '941e0a09-4e7f-42c2-bcae-44406f5b4567') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95365, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2719f7f7-cdc3-4f8d-9820-b62991c85628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
