INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95365, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "生下来就特别聪明、学东西特别快的人。", "primary_collocate": null, "pronunciation": "tiān cái", "ipa": "tʰjɛn˥ tsʰaɪ˧˥", "syllable_count": 2, "sentences": [{"text": "他是天才，什么都学得很快。", "target_word": "天才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我弟弟不是天才，但是很努力。", "target_word": "天才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小孩是个天才，三岁就会算数。", "target_word": "天才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人说他是天才，因为他一学就会。", "target_word": "天才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天才也要努力学习。", "target_word": "天才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小就是天才，老师都喜欢她。", "target_word": "天才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不是天才，学汉语学了三年。", "target_word": "天才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个天才孩子十岁就上了大学。", "target_word": "天才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看过一遍就记住了，真是天才。", "target_word": "天才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的儿子是个天才，一教就会。", "target_word": "天才", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}], "register": "中性", "sense_fingerprint": "天生聪明、学什么都特别快的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ba864ba-6cc7-447b-a4fb-522b2fbca27b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95365, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "天才", "is_correct": true, "explanation": "正确。“天才”指生下来就特别聪明、学东西特别快的人。"}, {"text": "甜菜", "is_correct": false, "explanation": "“甜菜”与“天才”第一个音节声调不同（二声与一声），第二个音节声调也不同（四声与二声），意思是一种作物。"}, {"text": "添彩", "is_correct": false, "explanation": "“添彩”与“天才”第二个音节声调不同（三声与二声），意思是增添光彩。"}, {"text": "添菜", "is_correct": false, "explanation": "“添菜”与“天才”第一个音节相同，第二个音节只有声调不同（四声与二声），意思是加菜。"}], "explanations": {"天才": "正确。“天才”指生下来就特别聪明、学东西特别快的人。", "甜菜": "“甜菜”与“天才”第一个音节声调不同（二声与一声），第二个音节声调也不同（四声与二声），意思是一种作物。", "添彩": "“添彩”与“天才”第二个音节声调不同（三声与二声），意思是增添光彩。", "添菜": "“添菜”与“天才”第一个音节相同，第二个音节只有声调不同（四声与二声），意思是加菜。"}, "sentence_index": null, "correct_answer": "天才"}, "level_3": {"options": [{"text": "天才", "is_correct": true, "explanation": "正确。“他是天才”指他特别聪明，学东西很快。"}, {"text": "石头", "is_correct": false, "explanation": "配价：“是”后面要说指人的名词，石头是物，不能说“他是石头”指人。"}, {"text": "冰箱", "is_correct": false, "explanation": "配价：冰箱是家用电器，不能说“他是冰箱”指人。"}, {"text": "文盲", "is_correct": false, "explanation": "语义：文盲是不认字的人，与“什么都学得很快”矛盾。"}], "explanations": {"天才": "正确。“他是天才”指他特别聪明，学东西很快。", "石头": "配价：“是”后面要说指人的名词，石头是物，不能说“他是石头”指人。", "冰箱": "配价：冰箱是家用电器，不能说“他是冰箱”指人。", "文盲": "语义：文盲是不认字的人，与“什么都学得很快”矛盾。"}, "sentence_index": 0, "correct_answer": "天才"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班来了一只天才。", "explanation": "量词用错。“只”用于动物或单个物件，指人的“天才”应用“个”或“位”。"}, {"text": "这把椅子是天才，学什么都快。", "explanation": "“天才”指人，椅子不会学东西，不能说“这把椅子是天才”。"}, {"text": "这块石头是天才，学什么都快。", "explanation": "“天才”指人，石头不会学东西，不能说“这块石头是天才”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2719f7f7-cdc3-4f8d-9820-b62991c85628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95365, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天才", "is_correct": true, "explanation": "正确。“我不是天才，学汉语学了三年”中，“天才”指天生聪明的人。"}, {"text": "白发", "is_correct": false, "explanation": "体貌：“白发”说头发的颜色，是外表特征，不能说“我不是白发”来解释学习情况。"}, {"text": "双眼皮", "is_correct": false, "explanation": "体貌：“双眼皮”说眼睛的样子，与学汉语的快慢无关，不能这样否定。"}, {"text": "汉字", "is_correct": false, "explanation": "语义：汉字是字，不是人，不能说“我不是汉字”。"}], "explanations": {"天才": "正确。“我不是天才，学汉语学了三年”中，“天才”指天生聪明的人。", "白发": "体貌：“白发”说头发的颜色，是外表特征，不能说“我不是白发”来解释学习情况。", "双眼皮": "体貌：“双眼皮”说眼睛的样子，与学汉语的快慢无关，不能这样否定。", "汉字": "语义：汉字是字，不是人，不能说“我不是汉字”。"}, "sentence_index": 6, "correct_answer": "天才"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的儿子是一棵天才，一教就会。", "explanation": "量词用错。“棵”用于植物，指人的“天才”应用“个”或“位”。"}, {"text": "这本书是天才，一教就会。", "explanation": "“天才”指人，书不会学东西，不能说“这本书是天才”。"}, {"text": "她的儿子长得很天才，一教就会。", "explanation": "这里应该用〈漂亮〉。“漂亮”可以形容长相，“天才”指人的能力，不能说“长得很天才”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2719f7f7-cdc3-4f8d-9820-b62991c85628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95365, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我哥哥是只天才，学数学一点就通。", "corrected_sentence": "我哥哥是个天才，学数学一点就通。", "error_description": "量词错误：“只”用于动物或单个物件，指人的“天才”应用“个”。正确说“是个天才”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2719f7f7-cdc3-4f8d-9820-b62991c85628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95365, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个男孩是棵天才，一教就会。", "corrected_sentence": "这个男孩是个天才，一教就会。", "error_description": "量词错误：“棵”用于植物，指人的“天才”应用“个”。正确说“是个天才”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2719f7f7-cdc3-4f8d-9820-b62991c85628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
