INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95366, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在某方面具有极高天赋的人。", "primary_collocate": null, "pronunciation": "tiān cái", "ipa": "tʰjɛn˥ tsʰaɪ˧˥", "syllable_count": 2, "sentences": [{"text": "他是数学天才。", "target_word": "天才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位画家是绘画天才。", "target_word": "天才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是音乐天才，五岁就会弹钢琴。", "target_word": "天才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明是足球天才，球踢得特别好。", "target_word": "天才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都叫他电脑天才。", "target_word": "天才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个唱歌天才让所有人都很吃惊。", "target_word": "天才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是我们学校的象棋天才。", "target_word": "天才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位天才演员演过很多电影。", "target_word": "天才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是语言天才，还会说五种语言。", "target_word": "天才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是跳舞天才，老师都很喜欢她。", "target_word": "天才", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}], "register": "中性", "sense_fingerprint": "在某个领域天赋极高的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ba864ba-6cc7-447b-a4fb-522b2fbca27b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95366, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "天才", "is_correct": true, "explanation": "正确。“天才”指在某方面天赋极高的人。"}, {"text": "甜菜", "is_correct": false, "explanation": "“甜菜”与“天才”第一个音节声调不同（二声与一声），第二个音节声调也不同（四声与二声），意思是一种作物。"}, {"text": "添彩", "is_correct": false, "explanation": "“添彩”与“天才”第二个音节声调不同（三声与二声），意思是增添光彩。"}, {"text": "添菜", "is_correct": false, "explanation": "“添菜”与“天才”第一个音节相同，第二个音节只有声调不同（四声与二声），意思是加菜。"}], "explanations": {"天才": "正确。“天才”指在某方面天赋极高的人。", "甜菜": "“甜菜”与“天才”第一个音节声调不同（二声与一声），第二个音节声调也不同（四声与二声），意思是一种作物。", "添彩": "“添彩”与“天才”第二个音节声调不同（三声与二声），意思是增添光彩。", "添菜": "“添菜”与“天才”第一个音节相同，第二个音节只有声调不同（四声与二声），意思是加菜。"}, "sentence_index": null, "correct_answer": "天才"}, "level_3": {"options": [{"text": "天才", "is_correct": true, "explanation": "正确。“他是数学天才”指他在数学上天赋极高。"}, {"text": "书", "is_correct": false, "explanation": "配价：“书”是物，不能说“他是数学书”。"}, {"text": "墙", "is_correct": false, "explanation": "语义：墙是物，不能说“他是数学墙”。"}, {"text": "笔", "is_correct": false, "explanation": "配价：“笔”是文具，不能说“他是数学笔”指人。"}], "explanations": {"天才": "正确。“他是数学天才”指他在数学上天赋极高。", "书": "配价：“书”是物，不能说“他是数学书”。", "墙": "语义：墙是物，不能说“他是数学墙”。", "笔": "配价：“笔”是文具，不能说“他是数学笔”指人。"}, "sentence_index": 0, "correct_answer": "天才"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小明是一头足球天才，球踢得特别好。", "explanation": "量词用错。“头”用于牛、猪等牲畜，指人的“天才”应用“个”或“位”。"}, {"text": "这只足球是天才，球踢得特别好。", "explanation": "“天才”指人，足球不会踢球，不能说“这只足球是天才”。"}, {"text": "这块草地是天才，球踢得特别好。", "explanation": "“天才”指人，草地不会踢球，不能说“这块草地是天才”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2719f7f7-cdc3-4f8d-9820-b62991c85628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95366, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天才", "is_correct": true, "explanation": "正确。“他是我们学校的象棋天才”指他的象棋天赋极高。"}, {"text": "歌手", "is_correct": false, "explanation": "搭配：“歌手”与象棋无关，不说“象棋歌手”。"}, {"text": "演员", "is_correct": false, "explanation": "搭配：“象棋”是棋类，不说“象棋演员”。"}, {"text": "长发", "is_correct": false, "explanation": "体貌：“长发”说的是外表，这里要说的是棋艺天赋，不是外貌。"}], "explanations": {"天才": "正确。“他是我们学校的象棋天才”指他的象棋天赋极高。", "歌手": "搭配：“歌手”与象棋无关，不说“象棋歌手”。", "演员": "搭配：“象棋”是棋类，不说“象棋演员”。", "长发": "体貌：“长发”说的是外表，这里要说的是棋艺天赋，不是外貌。"}, "sentence_index": 6, "correct_answer": "天才"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她是一条跳舞天才，老师都很喜欢她。", "explanation": "量词用错。“条”用于长条形物件或动物，指人的“天才”应用“个”或“位”。"}, {"text": "这张桌子是天才，老师都很喜欢它。", "explanation": "“天才”指人，桌子不会有天赋，不能说“这张桌子是天才”。"}, {"text": "这把尺子是天才，老师都很喜欢它。", "explanation": "“天才”指人，尺子不会有天赋，不能说“这把尺子是天才”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2719f7f7-cdc3-4f8d-9820-b62991c85628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95366, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她的哥哥是只数学天才，十岁就上了大学。", "corrected_sentence": "她的哥哥是个数学天才，十岁就上了大学。", "error_description": "量词错误：“只”用于动物或单个物件，指人的“天才”应用“个”。正确说“是个数学天才”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2719f7f7-cdc3-4f8d-9820-b62991c85628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95366, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个男孩是一只绘画天才。", "corrected_sentence": "这个男孩是一个绘画天才。", "error_description": "量词错误：“只”用于动物或单个物件，指人的“天才”应用“个”。正确说“是一个绘画天才”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2719f7f7-cdc3-4f8d-9820-b62991c85628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
