INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95367, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "爸爸妈妈叫儿子的妻子的话。", "primary_collocate": null, "pronunciation": "xí fu", "ipa": "ɕi˧˥ fu", "syllable_count": 2, "sentences": [{"text": "我儿子结婚了，新娶的媳妇很好。", "target_word": "媳妇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈对邻居说：“我媳妇很能干。”", "target_word": "媳妇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说儿子的媳妇是老师。", "target_word": "媳妇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老两口说，媳妇今天来看他们。", "target_word": "媳妇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶给新媳妇做了一件红衣服。", "target_word": "媳妇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家娶了一个好媳妇。", "target_word": "媳妇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈和媳妇一起去买菜。", "target_word": "媳妇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈带着媳妇去看医生。", "target_word": "媳妇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "李奶奶的媳妇是医生。", "target_word": "媳妇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们对媳妇像对女儿一样好。", "target_word": "媳妇", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "新媳妇", "label": "复合"}, {"form": "儿媳妇", "label": "复合"}, {"form": "媳婦", "label": "繁体"}], "register": "口语", "sense_fingerprint": "父母称呼儿子的妻子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ba864ba-6cc7-447b-a4fb-522b2fbca27b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95367, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "媳妇", "is_correct": true, "explanation": "正确答案：媳妇（xí fu），指儿子的妻子。"}, {"text": "西服", "is_correct": false, "explanation": "xī（第一声）与 xí（第二声）声调不同，西服是西装，与媳妇意思无关。"}, {"text": "戏服", "is_correct": false, "explanation": "xì（第四声）与 xí（第二声）声调不同，戏服指戏剧表演时穿的服装。"}, {"text": "姨夫", "is_correct": false, "explanation": "yí 与 xí 声母不同（y 与 x），姨夫指母亲姐妹的丈夫。"}, {"text": "喜服", "is_correct": false, "explanation": "xǐ（第三声）与 xí（第二声）声调不同，喜服指结婚时穿的衣服。"}], "explanations": {"媳妇": "正确答案：媳妇（xí fu），指儿子的妻子。", "西服": "xī（第一声）与 xí（第二声）声调不同，西服是西装，与媳妇意思无关。", "戏服": "xì（第四声）与 xí（第二声）声调不同，戏服指戏剧表演时穿的服装。", "姨夫": "yí 与 xí 声母不同（y 与 x），姨夫指母亲姐妹的丈夫。", "喜服": "xǐ（第三声）与 xí（第二声）声调不同，喜服指结婚时穿的衣服。"}, "sentence_index": null, "correct_answer": "媳妇"}, "level_3": {"options": [{"text": "媳妇", "is_correct": true, "explanation": "媳妇指儿子的妻子，与“儿子结婚了”的语境相符。"}, {"text": "女婿", "is_correct": false, "explanation": "语义：女婿是女儿的丈夫，是男性，不能说“新娶的女婿”。"}, {"text": "女儿", "is_correct": false, "explanation": "语义：女儿是自己生的孩子，不能“娶”，“新娶的女儿”说不通。"}, {"text": "女朋友", "is_correct": false, "explanation": "语义：娶了以后就是媳妇，不再是女朋友，“新娶的女朋友”说不通。"}], "explanations": {"媳妇": "媳妇指儿子的妻子，与“儿子结婚了”的语境相符。", "女婿": "语义：女婿是女儿的丈夫，是男性，不能说“新娶的女婿”。", "女儿": "语义：女儿是自己生的孩子，不能“娶”，“新娶的女儿”说不通。", "女朋友": "语义：娶了以后就是媳妇，不再是女朋友，“新娶的女朋友”说不通。"}, "sentence_index": 0, "correct_answer": "媳妇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我女儿的媳妇是医生。", "explanation": "这里应该用〈女婿〉。媳妇指儿子的妻子，女儿的丈夫要说女婿，女儿不可能有媳妇。"}, {"text": "我和他是媳妇，两家经常一起吃饭。", "explanation": "这里应该用〈亲家〉。媳妇指儿子的妻子，两家因子女结婚而结成的关系不能说“是媳妇”。"}, {"text": "我爸爸是我爷爷的媳妇，他很能干。", "explanation": "这里应该用〈儿子〉。媳妇指儿子的妻子，是女性身份，爸爸是男性，不能说是媳妇。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2719f7f7-cdc3-4f8d-9820-b62991c85628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95367, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "媳妇", "is_correct": true, "explanation": "媳妇指妻子，“一起去买菜”的是人，符合语境。"}, {"text": "冰箱", "is_correct": false, "explanation": "配价：“去买菜”需要人作主语，冰箱不能和妈妈一起去。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不会去买菜，“妈妈和汽车一起去买菜”说不通。"}, {"text": "桌子", "is_correct": false, "explanation": "配价：桌子不能一起去买菜，“去”的主语必须是人。"}], "explanations": {"媳妇": "媳妇指妻子，“一起去买菜”的是人，符合语境。", "冰箱": "配价：“去买菜”需要人作主语，冰箱不能和妈妈一起去。", "汽车": "语义：汽车不会去买菜，“妈妈和汽车一起去买菜”说不通。", "桌子": "配价：桌子不能一起去买菜，“去”的主语必须是人。"}, "sentence_index": 6, "correct_answer": "媳妇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的媳妇还没结婚。", "explanation": "这里应该用〈恋人〉。媳妇指已经结婚的儿子的妻子，与“还没结婚”矛盾。"}, {"text": "我们家请了一个媳妇，她做饭很好吃。", "explanation": "这里应该用〈保姆〉。媳妇是家里人，不能像请保姆一样“请”来。"}, {"text": "我媳妇今年八岁。", "explanation": "这里应该用〈孙子〉。媳妇指已经结婚的儿子的妻子，八岁的孩子不可能是媳妇。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2719f7f7-cdc3-4f8d-9820-b62991c85628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95367, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爷爷常夸他的那只媳妇会做菜。", "corrected_sentence": "爷爷常夸他的那个媳妇会做菜。", "error_description": "错误：“那只媳妇”，“只”不能用来数人。正确：“那个媳妇”。媳妇指人，量词用“个”，“只”多用于动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2719f7f7-cdc3-4f8d-9820-b62991c85628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95367, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "李叔叔的儿子今年结婚，娶了一条媳妇。", "corrected_sentence": "李叔叔的儿子今年结婚，娶了一个媳妇。", "error_description": "量词错误：“条”用于细长的东西，不能用来数人。正确：“一个媳妇”，“媳妇”指人，量词用“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2719f7f7-cdc3-4f8d-9820-b62991c85628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
