INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95372, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "供学生或员工集体居住的房屋。", "primary_collocate": null, "pronunciation": "sù shè", "ipa": "su⁵¹ ʂɤ⁵¹", "syllable_count": 2, "sentences": [{"text": "我们学校的宿舍在图书馆后面。", "target_word": "宿舍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她和三个同学住在一间宿舍里。", "target_word": "宿舍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宿舍晚上十一点关门，我得早点回去。", "target_word": "宿舍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的员工可以申请公司的宿舍。", "target_word": "宿舍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每天从宿舍走到教室只要五分钟。", "target_word": "宿舍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把行李搬进了宿舍。", "target_word": "宿舍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宿舍管理员正在检查每个房间的电器。", "target_word": "宿舍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们宿舍的四个人都喜欢打篮球。", "target_word": "宿舍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我在宿舍里洗衣服、打扫卫生。", "target_word": "宿舍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宿舍里不能做饭，也不能养宠物。", "target_word": "宿舍", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "间", "label": "量词"}, {"form": "宿舍楼", "label": "复合词"}, {"form": "学生宿舍", "label": "复合词"}], "register": "中性", "sense_fingerprint": "学校或单位提供给学生、员工住的集体住房", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3ab1b92-169b-4c40-8f7b-26a651420c25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95372, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "宿舍", "is_correct": true, "explanation": "宿舍是学校或单位提供的集体住房，“我们学校的宿舍在图书馆后面”语义通顺，是正确答案。"}, {"text": "学期", "is_correct": false, "explanation": "语义：学期是一段时间，不能位于某个地点，“在图书馆后面”说不通。"}, {"text": "学费", "is_correct": false, "explanation": "语义：学费是金钱，不是有位置的实体，不能说在图书馆后面。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“在……后面”要求具体场所或物体，“天气”不能用来指方位。"}], "explanations": {"宿舍": "宿舍是学校或单位提供的集体住房，“我们学校的宿舍在图书馆后面”语义通顺，是正确答案。", "学期": "语义：学期是一段时间，不能位于某个地点，“在图书馆后面”说不通。", "学费": "语义：学费是金钱，不是有位置的实体，不能说在图书馆后面。", "天气": "搭配：“在……后面”要求具体场所或物体，“天气”不能用来指方位。"}, "sentence_index": 0, "correct_answer": "宿舍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "爷爷奶奶住在自己家的宿舍里，房子是他们自己盖的。", "explanation": "这里应该用〈房子〉。宿舍由学校或单位提供，自己盖的家要说房子。"}, {"text": "我们在郊区买了一套宿舍。", "explanation": "这里应该用〈住宅〉。宿舍由学校或单位提供，个人不能买下，买房子要说住宅。"}, {"text": "他在市中心租了一套宿舍。", "explanation": "这里应该用〈公寓〉。宿舍由学校或单位提供，不是私人房东出租的房子，租房要说公寓。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bfad034-e6c0-407b-b152-54d3eb16b850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95372, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "宿舍", "is_correct": true, "explanation": "宿舍管理员是管理学生宿舍的人员，与“检查每个房间的电器”语境相符，是正确答案。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“管理员”指人，前面的名词要表示场所或组织，“冰箱”不能与“管理员”组成这种关系。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车管理员管理的是停车场所，不负责检查房间的电器。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是可以管理的场所或机构，“石头管理员”不成立。"}], "explanations": {"宿舍": "宿舍管理员是管理学生宿舍的人员，与“检查每个房间的电器”语境相符，是正确答案。", "冰箱": "搭配：“管理员”指人，前面的名词要表示场所或组织，“冰箱”不能与“管理员”组成这种关系。", "汽车": "语义：汽车管理员管理的是停车场所，不负责检查房间的电器。", "石头": "语义：石头不是可以管理的场所或机构，“石头管理员”不成立。"}, "sentence_index": 6, "correct_answer": "宿舍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工地上有一只宿舍，工人都住在里面。", "explanation": "这里应该用〈间〉。宿舍作为房间用“间”，“只”用于动物，不能用于宿舍。"}, {"text": "学校新盖了一把宿舍。", "explanation": "这里应该用〈栋〉。宿舍作为楼用“栋”，“把”用于有柄的器具，不能用于宿舍。"}, {"text": "我们班有一支宿舍。", "explanation": "这里应该用〈间〉。宿舍作为房间用“间”，“支”用于笔、队伍等，不能用于宿舍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bfad034-e6c0-407b-b152-54d3eb16b850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95372, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们三个人住一张宿舍。", "corrected_sentence": "他们三个人住一间宿舍。", "error_description": "错误：量词“张”用错。宿舍是房间，应用量词“间”，写作“一间宿舍”。“张”用于床、桌等物体。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bfad034-e6c0-407b-b152-54d3eb16b850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95372, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把这辆宿舍收拾得很干净。", "corrected_sentence": "我把这间宿舍收拾得很干净。", "error_description": "错误：量词“辆”用错。“辆”用于车，宿舍是房间，应用量词“间”，写作“这间宿舍”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bfad034-e6c0-407b-b152-54d3eb16b850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95374, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "稀", "is_correct": true, "explanation": "正确。“稀”指空隙大，与“密”构成反义关系。"}, {"text": "圆", "is_correct": false, "explanation": "无反义关系：“圆”指形状，与“密”的空隙义无关。"}, {"text": "亮", "is_correct": false, "explanation": "无反义关系：“亮”指光线或颜色明亮，与“密”的空隙义无关。"}, {"text": "咸", "is_correct": false, "explanation": "无反义关系：“咸”指味道，与“密”的空隙义无关。"}], "correct_answer": "稀", "explanations": {"稀": "正确。“稀”指空隙大，与“密”构成反义关系。", "圆": "无反义关系：“圆”指形状，与“密”的空隙义无关。", "亮": "无反义关系：“亮”指光线或颜色明亮，与“密”的空隙义无关。", "咸": "无反义关系：“咸”指味道，与“密”的空隙义无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d2236b-4500-4360-93e1-98363f6eb264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95374, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "疏", "is_correct": true, "explanation": "正确。“疏”指空隙大，与“密”构成反义关系。"}, {"text": "深", "is_correct": false, "explanation": "无反义关系：“深”指距离或程度，与“密”的空隙义无关。"}, {"text": "轻", "is_correct": false, "explanation": "无反义关系：“轻”指分量，与“密”的空隙义无关。"}, {"text": "酸", "is_correct": false, "explanation": "无反义关系：“酸”指味道，与“密”的空隙义无关。"}], "correct_answer": "疏", "explanations": {"疏": "正确。“疏”指空隙大，与“密”构成反义关系。", "深": "无反义关系：“深”指距离或程度，与“密”的空隙义无关。", "轻": "无反义关系：“轻”指分量，与“密”的空隙义无关。", "酸": "无反义关系：“酸”指味道，与“密”的空隙义无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d2236b-4500-4360-93e1-98363f6eb264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95374, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "事物之间距离近、空隙小；稠密。", "primary_collocate": null, "pronunciation": "mì", "ipa": "mi˥˩", "syllable_count": 1, "sentences": [{"text": "山上的树林非常密。", "target_word": "密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗外的雨下得又急又密。", "target_word": "密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的胡子很密。", "target_word": "密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市里的楼房盖得很密。", "target_word": "密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜空中的星星又多又密。", "target_word": "密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "篱笆扎得很密，小狗钻不过去。", "target_word": "密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片竹林长得很密，走进去很难。", "target_word": "密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把菜苗种得很密。", "target_word": "密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "渔网的网眼很密，小鱼逃不掉。", "target_word": "密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙上的照片贴得很密。", "target_word": "密", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "密密麻麻", "label": "复合"}, {"form": "稠密", "label": "复合"}], "register": "中性", "sense_fingerprint": "形容词：事物之间距离近、空隙小，稠密", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '016a8d2a-68e4-4db2-b1cd-c081d7aad3bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95374, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "密", "is_correct": true, "explanation": "正确。mì（第四声），意思是事物之间距离近、空隙小。"}, {"text": "米", "is_correct": false, "explanation": "mǐ（第三声）与 mì（第四声）声调不同，意思是米。"}, {"text": "迷", "is_correct": false, "explanation": "mí（第二声）与 mì（第四声）声调不同，意思是迷路。"}, {"text": "必", "is_correct": false, "explanation": "bì 与 mì 声母不同，意思是必须。"}, {"text": "闭", "is_correct": false, "explanation": "bì 与 mì 声母不同，意思是关闭。"}], "explanations": {"密": "正确。mì（第四声），意思是事物之间距离近、空隙小。", "米": "mǐ（第三声）与 mì（第四声）声调不同，意思是米。", "迷": "mí（第二声）与 mì（第四声）声调不同，意思是迷路。", "必": "bì 与 mì 声母不同，意思是必须。", "闭": "bì 与 mì 声母不同，意思是关闭。"}, "sentence_index": null, "correct_answer": "密"}, "level_3": {"options": [{"text": "密", "is_correct": true, "explanation": "正确。“非常密”描写树林的疏密，与“事物之间空隙小”相合。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”指味道，不能形容树林的疏密。"}, {"text": "慢", "is_correct": false, "explanation": "语义：“慢”说速度，与树林的疏密描写不符。"}, {"text": "硬", "is_correct": false, "explanation": "搭配：“硬”形容质地，不用于描写树林的稀密。"}], "explanations": {"密": "正确。“非常密”描写树林的疏密，与“事物之间空隙小”相合。", "甜": "语义：“甜”指味道，不能形容树林的疏密。", "慢": "语义：“慢”说速度，与树林的疏密描写不符。", "硬": "搭配：“硬”形容质地，不用于描写树林的稀密。"}, "sentence_index": 0, "correct_answer": "密"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这面墙很密，我得踩着凳子才够得着。", "explanation": "这里应该用〈高〉。密说空隙小，不表示高度，墙的高矮要用〈高〉。"}, {"text": "这个杯子很密，水很快就满了。", "explanation": "这里应该用〈小〉。密说空隙小，不表示容量，杯子的大小要用〈小〉。"}, {"text": "这间屋子很密，住十个人也不挤。", "explanation": "这里应该用〈大〉。密说东西之间空隙小，面积大小要用〈大〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d2236b-4500-4360-93e1-98363f6eb264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95374, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "密", "is_correct": true, "explanation": "正确。mì（第四声），意思是事物之间距离近、空隙小。"}, {"text": "眯", "is_correct": false, "explanation": "mī（第一声）与 mì（第四声）声调不同，意思是眯起眼睛。"}, {"text": "毕", "is_correct": false, "explanation": "bì 与 mì 声母不同，意思是完毕或毕业。"}, {"text": "腻", "is_correct": false, "explanation": "nì 与 mì 声母不同，意思是油腻。"}], "explanations": {"密": "正确。mì（第四声），意思是事物之间距离近、空隙小。", "眯": "mī（第一声）与 mì（第四声）声调不同，意思是眯起眼睛。", "毕": "bì 与 mì 声母不同，意思是完毕或毕业。", "腻": "nì 与 mì 声母不同，意思是油腻。"}, "sentence_index": null, "correct_answer": "密"}, "level_3": {"options": [{"text": "密", "is_correct": true, "explanation": "正确。“长得很密”描写竹林的疏密，与“事物之间空隙小”相合。"}, {"text": "稀", "is_correct": false, "explanation": "语义：“稀”指空隙大，与后句“走进去很难”矛盾。"}, {"text": "脆", "is_correct": false, "explanation": "搭配：“脆”形容质地，不用来描写竹林的长势。"}, {"text": "凉", "is_correct": false, "explanation": "搭配：“凉”指温度，不能用来形容竹林长得密不密。"}], "explanations": {"密": "正确。“长得很密”描写竹林的疏密，与“事物之间空隙小”相合。", "稀": "语义：“稀”指空隙大，与后句“走进去很难”矛盾。", "脆": "搭配：“脆”形容质地，不用来描写竹林的长势。", "凉": "搭配：“凉”指温度，不能用来形容竹林长得密不密。"}, "sentence_index": 6, "correct_answer": "密"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这盏台灯很密，看书很舒服。", "explanation": "这里应该用〈亮〉。密说空隙小，光线明暗要用〈亮〉。"}, {"text": "这个操场很密，可以踢足球。", "explanation": "这里应该用〈大〉。密说空隙小，场地大小要用〈大〉。"}, {"text": "这把椅子很密，坐着很舒服。", "explanation": "这里应该用〈软〉。密说空隙小，不表示软硬；椅子坐着舒服要用〈软〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d2236b-4500-4360-93e1-98363f6eb264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95374, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这片小区的树种得密很。", "corrected_sentence": "这片小区的树种得很密。", "error_description": "错误：“密很”语序颠倒，程度副词“很”应放在形容词之前。正确：“种得很密”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d2236b-4500-4360-93e1-98363f6eb264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95374, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "院子里的花盆摆很密。", "corrected_sentence": "院子里的花盆摆得很密。", "error_description": "错误：“摆很密”缺少补语标记“得”。正确：动词与补语“很密”之间需用“得”，应说“摆得很密”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04d2236b-4500-4360-93e1-98363f6eb264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
