INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95375, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "学生到真正的地方去做事，边做边学。", "primary_collocate": null, "pronunciation": "shí xí", "ipa": "ʂɻ̩˧˥ ɕi˧˥", "syllable_count": 2, "sentences": [{"text": "我暑假要去一家公司实习。", "target_word": "实习", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李在医院实习了三个月。", "target_word": "实习", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她大学三年级时在报社实习。", "target_word": "实习", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们明年去工厂实习。", "target_word": "实习", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在银行实习，每天都很忙。", "target_word": "实习", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟想去饭店实习，学做菜。", "target_word": "实习", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在这家商店实习过一个月。", "target_word": "实习", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们在学校旁边的医院实习。", "target_word": "实习", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业以前，你要去哪儿实习？", "target_word": "实习", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一边实习，一边学习做事。", "target_word": "实习", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "实习过", "label": "体标"}, {"form": "实习生", "label": "复合"}, {"form": "實習", "label": "繁体"}], "register": "中性", "sense_fingerprint": "学生到真实场所边做边学", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f60e3e1-7e5c-4460-8a03-18319ddd28e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95375, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "实习", "is_correct": true, "explanation": "正确：实习指学生到公司边做边学，与“去一家公司”相符。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：公司不是游泳的地方，“去一家公司游泳”说不通。"}, {"text": "写作业", "is_correct": false, "explanation": "搭配：“写作业”属于学校学习，不能与“去一家公司”搭配。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：去公司睡觉不合常理，句子说的是去公司做事。"}], "explanations": {"实习": "正确：实习指学生到公司边做边学，与“去一家公司”相符。", "游泳": "语义：公司不是游泳的地方，“去一家公司游泳”说不通。", "写作业": "搭配：“写作业”属于学校学习，不能与“去一家公司”搭配。", "睡觉": "语义：去公司睡觉不合常理，句子说的是去公司做事。"}, "sentence_index": 0, "correct_answer": "实习"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我奶奶每天早上去菜市场实习，只是为了逛街。", "explanation": "这里应该用〈逛街〉。实习是到单位学习做事，老人去市场逛街不是实习。"}, {"text": "他在银行实习了十年。", "explanation": "这里应该用〈工作〉。实习是短期的学习锻炼，不能用于连续十年的正式工作。"}, {"text": "孩子们在操场上实习。", "explanation": "这里应该用〈玩〉。实习有学习或工作的目的，不用于在操场上游戏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79a7f742-7ea7-4ddd-8813-2caa673a1ddf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95375, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "实习", "is_correct": true, "explanation": "正确：“在这家商店实习过”指在商店做事学习过。"}, {"text": "看病", "is_correct": false, "explanation": "搭配：“看病”要与医院搭配，商店不能说看病。"}, {"text": "游览", "is_correct": false, "explanation": "语义：商店不是游览的地方，“游览过一个月”说不通。"}, {"text": "散步", "is_correct": false, "explanation": "语义：在商店散步一个月不合常理，句子说的是在商店做事。"}], "explanations": {"实习": "正确：“在这家商店实习过”指在商店做事学习过。", "看病": "搭配：“看病”要与医院搭配，商店不能说看病。", "游览": "语义：商店不是游览的地方，“游览过一个月”说不通。", "散步": "语义：在商店散步一个月不合常理，句子说的是在商店做事。"}, "sentence_index": 6, "correct_answer": "实习"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "暑假时我们全家去海边实习。", "explanation": "这里应该用〈度假〉。全家去海边休息放松要说度假，实习是为了在单位学习做事。"}, {"text": "我每天晚上躺在床上实习，很舒服。", "explanation": "这里应该用〈休息〉。实习是到单位边做边学，躺在床上舒服地休息不是实习。"}, {"text": "我爸爸每天在超市实习，买了很多零食。", "explanation": "这里应该用〈购物〉。实习是到单位学习做事，去超市买零食不是实习。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79a7f742-7ea7-4ddd-8813-2caa673a1ddf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95375, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在公司实习着一个月。", "corrected_sentence": "我在公司实习了一个月。", "error_description": "错误：“实习着一个月”。正确：“实习了一个月”。“着”表示动作或状态正在进行，不用来叙述已经结束的一段实习经历；叙述已完成的时段，应用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79a7f742-7ea7-4ddd-8813-2caa673a1ddf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95375, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在医院实习得两个星期。", "corrected_sentence": "我在医院实习过两个星期。", "error_description": "错误：“实习得两个星期”。正确：“实习过两个星期”。“得”接在动词后作补语，不能接表示时段的“两个星期”；表示曾经有过的经历要用“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79a7f742-7ea7-4ddd-8813-2caa673a1ddf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
