INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95376, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "学生将所学知识应用于实际工作中进行锻炼。", "primary_collocate": null, "pronunciation": "shí xí", "ipa": "ʂɻ̩˧˥ ɕi˧˥", "syllable_count": 2, "sentences": [{"text": "老师让我们去公司实习，用上学到的知识。", "target_word": "实习", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想去学校当老师，先实习一年。", "target_word": "实习", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学法律的学生要去法院实习。", "target_word": "实习", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在实习的时候学到了很多。", "target_word": "实习", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学电脑的人可以去公司实习。", "target_word": "实习", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在设计公司实习，用课上学的知识画图。", "target_word": "实习", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生必须实习半年才能毕业。", "target_word": "实习", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想找一个地方实习，把课上学的知识用到工作里。", "target_word": "实习", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在医院实习，慢慢学会了看病。", "target_word": "实习", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们都在找地方实习。", "target_word": "实习", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "实习过", "label": "体标"}, {"form": "实习期", "label": "复合"}, {"form": "實習", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把所学知识用于实际工作来锻炼", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f60e3e1-7e5c-4460-8a03-18319ddd28e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95376, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "实习", "is_correct": true, "explanation": "正确：实习指把所学知识用于工作，与“老师让我们去公司”相符。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：去公司游泳与“用上学到的知识”的意思冲突。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：去公司睡觉与“用上学到的知识”冲突。"}, {"text": "写作业", "is_correct": false, "explanation": "搭配：“写作业”与学校搭配，不能用于公司。"}], "explanations": {"实习": "正确：实习指把所学知识用于工作，与“老师让我们去公司”相符。", "游泳": "语义：去公司游泳与“用上学到的知识”的意思冲突。", "睡觉": "语义：去公司睡觉与“用上学到的知识”冲突。", "写作业": "搭配：“写作业”与学校搭配，不能用于公司。"}, "sentence_index": 0, "correct_answer": "实习"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天晚上在沙发上实习，很放松。", "explanation": "这里应该用〈休息〉。实习是到单位学习做事，在沙发上放松不是实习。"}, {"text": "我们在海边实习，玩得很开心。", "explanation": "这里应该用〈度假〉。实习是为了在单位学习做事，与“玩得很开心”的休闲意思不符。"}, {"text": "爸爸已经实习了，每天在公园散步。", "explanation": "这里应该用〈退休〉。实习是学习锻炼，已经退休的爸爸应说退休。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79a7f742-7ea7-4ddd-8813-2caa673a1ddf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95376, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "实习", "is_correct": true, "explanation": "正确：实习指学生把所学用于工作，与“必须……才能毕业”相符。"}, {"text": "旅游", "is_correct": false, "explanation": "语义：旅游不是毕业前必须的学习，与“才能毕业”冲突。"}, {"text": "散步", "is_correct": false, "explanation": "语义：散步半年不是毕业要求，与句意冲突。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉半年不能代替毕业要求，与句意冲突。"}], "explanations": {"实习": "正确：实习指学生把所学用于工作，与“必须……才能毕业”相符。", "旅游": "语义：旅游不是毕业前必须的学习，与“才能毕业”冲突。", "散步": "语义：散步半年不是毕业要求，与句意冲突。", "睡觉": "语义：睡觉半年不能代替毕业要求，与句意冲突。"}, "sentence_index": 6, "correct_answer": "实习"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "同学们晚上都去操场实习，打篮球。", "explanation": "这里应该用〈锻炼〉。实习指到单位学习做事，去操场打篮球是体育锻炼，不是实习。"}, {"text": "爷爷每天下午在床上实习，睡得很香。", "explanation": "这里应该用〈睡觉〉。实习是把所学知识用到实际工作中，在床上睡得很香是睡觉，不是实习。"}, {"text": "我每天早上去超市实习，买了很多东西。", "explanation": "这里应该用〈购物〉。实习是到单位学习做事，去超市买东西不是实习。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79a7f742-7ea7-4ddd-8813-2caa673a1ddf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95376, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在工厂实习着一年。", "corrected_sentence": "她在工厂实习了一年。", "error_description": "错误：“实习着一年”。正确：“实习了一年”。“着”表示动作或状态正在进行，不用来叙述已经结束的一段实习经历；叙述已完成的时段，应用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79a7f742-7ea7-4ddd-8813-2caa673a1ddf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95376, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他工厂实习过两个月。", "corrected_sentence": "他在工厂实习过两个月。", "error_description": "错误：缺少“在”，写成“工厂实习过”。正确：“在工厂实习过”。表示地点的介词“在”不能省略。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79a7f742-7ea7-4ddd-8813-2caa673a1ddf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95377, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "特别", "is_correct": true, "explanation": "特别：与“平常”构成反义，指与众不同、有突出之处。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚：形容明白、不模糊，与“平常”没有反义关系。"}, {"text": "复杂", "is_correct": false, "explanation": "复杂：形容事情或结构繁多，与“平常”没有反义关系。"}, {"text": "柔软", "is_correct": false, "explanation": "柔软：形容质地不硬，与“平常”没有反义关系。"}], "correct_answer": "特别", "explanations": {"特别": "特别：与“平常”构成反义，指与众不同、有突出之处。", "清楚": "清楚：形容明白、不模糊，与“平常”没有反义关系。", "复杂": "复杂：形容事情或结构繁多，与“平常”没有反义关系。", "柔软": "柔软：形容质地不硬，与“平常”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12927d7c-59d1-40f3-ad1f-89500df274f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
