INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95377, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "和每一天都一样，没有什么特别的。", "primary_collocate": null, "pronunciation": "píng cháng", "ipa": "pʰiŋ˧˥ ʈʂʰɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "今天是很平常的一天。", "target_word": "平常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个星期过得很平常。", "target_word": "平常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末的早上很平常，我们在家吃早饭。", "target_word": "平常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的生日过得很平常，没有蛋糕。", "target_word": "平常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天的工作很平常，没有什么新鲜事。", "target_word": "平常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那是平常的一个晚上，我在家看书。", "target_word": "平常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这天过得和别的日子一样平常。", "target_word": "平常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的生活很平常，也很安静。", "target_word": "平常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一切都很平常，没有人觉得奇怪。", "target_word": "平常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春节过后，大家又回到了平常的日子。", "target_word": "平常", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "平平常常", "label": "重叠"}, {"form": "不平常", "label": "否定"}], "register": "中性", "sense_fingerprint": "和平时每天一样，没有特别的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cbe411f-991a-416c-a28b-6dca83adf8ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95377, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "平常", "is_correct": true, "explanation": "平常：和每天一样，没有特别之处，修饰“一天”正合适。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”形容人的智力，不能用来形容一天。"}, {"text": "年轻", "is_correct": false, "explanation": "语义：“年轻”形容人的年龄，不能用来形容一天。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物的体型，不能用来形容一天。"}], "explanations": {"平常": "平常：和每天一样，没有特别之处，修饰“一天”正合适。", "聪明": "语义：“聪明”形容人的智力，不能用来形容一天。", "年轻": "语义：“年轻”形容人的年龄，不能用来形容一天。", "高大": "体貌：“高大”形容人或物的体型，不能用来形容一天。"}, "sentence_index": 0, "correct_answer": "平常"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祝你一路平常，一切顺利。", "explanation": "这里应该用〈平安〉。“一路平安”是固定的祝福说法，平常只表示普通、没有特别之处，不能用来祝愿旅途平安。"}, {"text": "湖面很平常，没有一点波浪。", "explanation": "这里应该用〈平静〉。形容水面没有波浪要说平静，平常只表示普通，不用来形容水面。"}, {"text": "他的体温很平常，已经三十九度了。", "explanation": "这里应该用〈高〉。体温三十九度说明体温很高，平常只表示普通，不能描述异常的体温。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12927d7c-59d1-40f3-ad1f-89500df274f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95377, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "平常", "is_correct": true, "explanation": "平常：与“一样”搭配，表示与别的日子没有差别。"}, {"text": "热情", "is_correct": false, "explanation": "语义：“热情”形容人的态度，不能用来说日子过得怎样。"}, {"text": "诚实", "is_correct": false, "explanation": "语义：“诚实”形容人的品质，不能用来说日子过得怎样。"}, {"text": "高", "is_correct": false, "explanation": "体貌：“高”指身高或高度，“一样高”不能用来说日子。"}], "explanations": {"平常": "平常：与“一样”搭配，表示与别的日子没有差别。", "热情": "语义：“热情”形容人的态度，不能用来说日子过得怎样。", "诚实": "语义：“诚实”形容人的品质，不能用来说日子过得怎样。", "高": "体貌：“高”指身高或高度，“一样高”不能用来说日子。"}, "sentence_index": 6, "correct_answer": "平常"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们一路很平常，差点出了车祸。", "explanation": "这里应该用〈惊险〉。平常只表示普通、没有特别之处，路上差点出车祸要用〈惊险〉。"}, {"text": "这次考试他的分数很平常，全班第一。", "explanation": "这里应该用〈优秀〉。平常只表示普通，“全班第一”说明成绩突出，要用〈优秀〉。"}, {"text": "面对批评，他的情绪很平常，当场激动得站了起来。", "explanation": "这里应该用〈激动〉。平常只表示普通，“激动得站了起来”说明情绪强烈，要用〈激动〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12927d7c-59d1-40f3-ad1f-89500df274f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95377, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一个很平常早晨。", "corrected_sentence": "这是一个很平常的早晨。", "error_description": "错误形式：“很平常早晨”；正确形式：“很平常的早晨”。形容词“平常”修饰名词时，中间要加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12927d7c-59d1-40f3-ad1f-89500df274f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95377, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "春节一过，我们又回到了平常地日子。", "corrected_sentence": "春节一过，我们又回到了平常的日子。", "error_description": "错误形式：“平常地日子”；正确形式：“平常的日子”。名词前的修饰语用“的”，“地”用在动词前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12927d7c-59d1-40f3-ad1f-89500df274f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
