INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95378, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "普通；不特别。", "primary_collocate": null, "pronunciation": "píng cháng", "ipa": "pʰiŋ˧˥ ʈʂʰɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他只是一个很平常的人。", "target_word": "平常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一件很平常的事，不用担心。", "target_word": "平常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店的菜很平常。", "target_word": "平常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她穿着一件很平常的衣服。", "target_word": "平常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他长得很平常，但是笑起来很好看。", "target_word": "平常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个想法很平常，没有什么新意。", "target_word": "平常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的成绩很平常，不好也不坏。", "target_word": "平常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只是一部平常的电影。", "target_word": "平常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他住在一个平常的小城市。", "target_word": "平常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别看他样子很平常，其实很有本事。", "target_word": "平常", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "平平常常", "label": "重叠"}, {"form": "不平常", "label": "否定"}], "register": "中性", "sense_fingerprint": "人或事物普通，没有突出的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cbe411f-991a-416c-a28b-6dca83adf8ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95378, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "平常", "is_correct": true, "explanation": "平常：修饰“人”，表示普通、没有突出之处。"}, {"text": "辽阔", "is_correct": false, "explanation": "语义：“辽阔”形容地域或空间，不能用来形容一个人。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”多形容声音，不用来形容人。"}, {"text": "空旷", "is_correct": false, "explanation": "语义：“空旷”形容空间没有人或物，不能用来形容一个人。"}], "explanations": {"平常": "平常：修饰“人”，表示普通、没有突出之处。", "辽阔": "语义：“辽阔”形容地域或空间，不能用来形容一个人。", "清脆": "搭配：“清脆”多形容声音，不用来形容人。", "空旷": "语义：“空旷”形容空间没有人或物，不能用来形容一个人。"}, "sentence_index": 0, "correct_answer": "平常"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祝你一路平常，早点到家。", "explanation": "这里应该用〈平安〉。“一路平安”是固定的祝福说法，平常只表示普通，不能用来祝愿旅途平安。"}, {"text": "海面很平常，没有一丝风浪。", "explanation": "这里应该用〈平静〉。形容海面没有风浪要说平静，平常只表示普通，不用来形容海面。"}, {"text": "他跑完步以后，心跳很平常，喘得厉害。", "explanation": "这里应该用〈剧烈〉。心跳快、喘得厉害要说剧烈，平常只表示普通，不能描述剧烈的心跳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12927d7c-59d1-40f3-ad1f-89500df274f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95378, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "平常", "is_correct": true, "explanation": "平常：与“不好也不坏”相呼应，表示中等、不突出。"}, {"text": "优秀", "is_correct": false, "explanation": "语义：“优秀”表示很好，与“不好也不坏”矛盾。"}, {"text": "出色", "is_correct": false, "explanation": "语义：“出色”表示突出，与“不好也不坏”矛盾。"}, {"text": "宽阔", "is_correct": false, "explanation": "搭配：“宽阔”多形容场地、道路，不用来形容成绩。"}], "explanations": {"平常": "平常：与“不好也不坏”相呼应，表示中等、不突出。", "优秀": "语义：“优秀”表示很好，与“不好也不坏”矛盾。", "出色": "语义：“出色”表示突出，与“不好也不坏”矛盾。", "宽阔": "搭配：“宽阔”多形容场地、道路，不用来形容成绩。"}, "sentence_index": 6, "correct_answer": "平常"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在班里很平常，成绩总是第一。", "explanation": "这里应该用〈出众〉。平常只表示普通，与“成绩总是第一”矛盾。"}, {"text": "这个玩笑很平常，大家都笑得很厉害。", "explanation": "这里应该用〈有趣〉。平常只表示普通，不表示好笑；“大家都笑得很厉害”说明玩笑要用〈有趣〉。"}, {"text": "这场演出很平常，观众都站起来鼓掌了。", "explanation": "这里应该用〈精彩〉。平常只表示普通，观众站起来鼓掌说明演出要用〈精彩〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12927d7c-59d1-40f3-ad1f-89500df274f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95378, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他只是一个很平常同学。", "corrected_sentence": "他只是一个很平常的同学。", "error_description": "错误形式：“很平常同学”；正确形式：“很平常的同学”。形容词修饰名词时，中间要加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12927d7c-59d1-40f3-ad1f-89500df274f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95378, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他有一件很平常地毛衣。", "corrected_sentence": "他有一件很平常的毛衣。", "error_description": "错误形式：“很平常地毛衣”；正确形式：“很平常的毛衣”。名词前的修饰语要用“的”，“地”用在动词前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12927d7c-59d1-40f3-ad1f-89500df274f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
