INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95379, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "可以看的画面和可以听的声音。", "primary_collocate": null, "pronunciation": "yǐng yīn", "ipa": "iŋ²¹⁴ in⁵⁵", "syllable_count": 2, "sentences": [{"text": "这家店卖各种影音设备。", "target_word": "影音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客厅里的影音系统效果非常好。", "target_word": "影音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢在网上找一些影音资源。", "target_word": "影音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手机的影音功能很强，看电影很清楚。", "target_word": "影音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把旧的影音文件都存到了电脑里。", "target_word": "影音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "影音资料可以让学生更容易理解课文。", "target_word": "影音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网站上有很多免费的影音内容。", "target_word": "影音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末他常在家享受影音娱乐。", "target_word": "影音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台电视的影音质量比以前的好。", "target_word": "影音", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用影音材料给我们上课。", "target_word": "影音", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "影音设备", "label": "复合词"}, {"form": "影音文件", "label": "复合词"}], "register": "中性", "sense_fingerprint": "能看的画面加能听的声音，多指娱乐内容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3ab1b92-169b-4c40-8f7b-26a651420c25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95379, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "影音", "is_correct": true, "explanation": "影音指能看的画面和能听的声音，即影像与声音的组合，是正确答案。"}, {"text": "影印", "is_correct": false, "explanation": "影印（yǐng yìn）与影音（yǐng yīn）第二个音节声调不同，影印指复印，意思不同。"}, {"text": "英音", "is_correct": false, "explanation": "英音（yīng yīn）与影音（yǐng yīn）第一个音节声调不同，意思是英式发音。"}, {"text": "硬音", "is_correct": false, "explanation": "硬音（yìng yīn）与影音（yǐng yīn）第一个音节声调不同，意思是用力较强的发音。"}], "explanations": {"影音": "影音指能看的画面和能听的声音，即影像与声音的组合，是正确答案。", "影印": "影印（yǐng yìn）与影音（yǐng yīn）第二个音节声调不同，影印指复印，意思不同。", "英音": "英音（yīng yīn）与影音（yǐng yīn）第一个音节声调不同，意思是英式发音。", "硬音": "硬音（yìng yīn）与影音（yǐng yīn）第一个音节声调不同，意思是用力较强的发音。"}, "sentence_index": null, "correct_answer": "影音"}, "level_3": {"options": [{"text": "影音", "is_correct": true, "explanation": "“这家店卖各种影音设备”语义通顺，影音设备指播放画面和声音的设备，是正确答案。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：蔬菜是食物，不是设备，“卖各种蔬菜设备”说不通。"}, {"text": "衣服", "is_correct": false, "explanation": "搭配：“设备”不与“衣服”搭配，不能说衣服设备。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果是食物，不是设备，与“设备”语义冲突。"}], "explanations": {"影音": "“这家店卖各种影音设备”语义通顺，影音设备指播放画面和声音的设备，是正确答案。", "蔬菜": "语义：蔬菜是食物，不是设备，“卖各种蔬菜设备”说不通。", "衣服": "搭配：“设备”不与“衣服”搭配，不能说衣服设备。", "水果": "语义：水果是食物，不是设备，与“设备”语义冲突。"}, "sentence_index": 0, "correct_answer": "影音"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张照片的影音很清楚。", "explanation": "这里应该用〈影像〉。影音包含声音，照片只有静态画面，要说影像。"}, {"text": "这盘录音带的影音很清楚。", "explanation": "这里应该用〈声音〉。录音带只有声音，没有画面，不能说影音。"}, {"text": "这本书的影音很好。", "explanation": "这里应该用〈文字〉。书是文字媒介，没有影音，说书的内容要用文字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bfad034-e6c0-407b-b152-54d3eb16b850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95379, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "影音", "is_correct": true, "explanation": "“网站上有很多免费的影音内容”语义通顺，影音内容指可看可听的娱乐材料，是正确答案。"}, {"text": "食物", "is_correct": false, "explanation": "语义：食物不是内容，“免费的食物内容”说不通。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油是燃料，不属于可以提供的内容，与“内容”语义冲突。"}, {"text": "人民", "is_correct": false, "explanation": "搭配：“人民”不能作“内容”的定语，“免费的人民内容”不成立。"}], "explanations": {"影音": "“网站上有很多免费的影音内容”语义通顺，影音内容指可看可听的娱乐材料，是正确答案。", "食物": "语义：食物不是内容，“免费的食物内容”说不通。", "汽油": "语义：汽油是燃料，不属于可以提供的内容，与“内容”语义冲突。", "人民": "搭配：“人民”不能作“内容”的定语，“免费的人民内容”不成立。"}, "sentence_index": 6, "correct_answer": "影音"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一本影音，回家看了一晚上。", "explanation": "这里应该用〈段〉。“本”用于书籍，影音应说“一段影音”。"}, {"text": "老师借了一只影音给我们。", "explanation": "这里应该用〈段〉。“只”用于动物，影音不能用“只”，应说“一段影音”。"}, {"text": "他买了一把影音。", "explanation": "这里应该用〈段〉。“把”用于有柄的器具，影音应说“一段影音”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bfad034-e6c0-407b-b152-54d3eb16b850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95379, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把那只影音删掉了。", "corrected_sentence": "他把那段影音删掉了。", "error_description": "错误：“影音”的量词用错。“只”用于动物，影音应用“段”，写作“那段影音”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bfad034-e6c0-407b-b152-54d3eb16b850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95379, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们班看过这只影音。", "corrected_sentence": "我们班看过这段影音。", "error_description": "错误：量词“只”用错。“只”用于动物，影音应用“段”，写作“这段影音”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bfad034-e6c0-407b-b152-54d3eb16b850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
