INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95381, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "遇到危险时，把伤员或物资转送到后面比较安全的地方去。", "primary_collocate": null, "pronunciation": "hòu sòng", "ipa": "xoʊ˥˩ sʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "医生把伤员后送到县医院。", "target_word": "后送", "complexity_tier": "T3", "furigana": "hòu sòng", "sentence_source": "generated"}, {"text": "洪水来了，救援队把伤员后送到安全的地方。", "target_word": "后送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现场太危险，伤员要马上后送，再做治疗。", "target_word": "后送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人病情危急，要立即后送。", "target_word": "后送", "complexity_tier": "T3", "furigana": "hòu sòng", "sentence_source": "generated"}, {"text": "矿井塌方后，救援人员把伤员后送到地面。", "target_word": "后送", "complexity_tier": "T3", "furigana": "hòu sòng", "sentence_source": "generated"}, {"text": "大火越烧越近，救援人员决定立即后送伤员。", "target_word": "后送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震后，直升机把重伤员后送到市区医院。", "target_word": "后送", "complexity_tier": "T3", "furigana": "hòu sòng", "sentence_source": "generated"}, {"text": "余震不断，伤员要后送到后面的安全区。", "target_word": "后送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些伤员不能留在现场，要马上后送。", "target_word": "后送", "complexity_tier": "T3", "furigana": "hòu sòng", "sentence_source": "generated"}, {"text": "现场条件差，所以重伤员要从事故点后送到医院。", "target_word": "后送", "complexity_tier": "T3", "furigana": "hòu sòng", "sentence_source": "generated"}], "morphological_forms": [{"form": "后送了", "label": "完成体"}, {"form": "后送过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "遇到危险时把伤员或物资转送到后面安全处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b37fbea5-e5a7-40fc-aef0-8c6a260a8c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95381, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "后送", "is_correct": true, "explanation": "正确：后送指把伤员或物资送往后方安全处，与“把伤员……到县医院”的意思相符。"}, {"text": "寄", "is_correct": false, "explanation": "搭配：“寄”只用于物品，不能用于人，不能说寄伤员。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是随手抛出，不能用来表示安全转送伤员。"}, {"text": "摔", "is_correct": false, "explanation": "语义：“摔”是猛然掷下，与把伤员安全送医的意思相反。"}], "explanations": {"后送": "正确：后送指把伤员或物资送往后方安全处，与“把伤员……到县医院”的意思相符。", "寄": "搭配：“寄”只用于物品，不能用于人，不能说寄伤员。", "扔": "语义：“扔”是随手抛出，不能用来表示安全转送伤员。", "摔": "语义：“摔”是猛然掷下，与把伤员安全送医的意思相反。"}, "sentence_index": 0, "correct_answer": "后送"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "救援队把伤员后送到火线上。", "explanation": "这里应该用〈前送〉。后送是把伤员或物资送往后方安全处，送往火线是前送，方向正好相反。"}, {"text": "部队把自己后送到了后方。", "explanation": "这里应该用〈撤退〉。后送的对象是伤员或物资，由别人送走，部队自己转移不用后送。"}, {"text": "他把这个想法后送到了后方。", "explanation": "这里应该用〈传达〉。后送的宾语只能是伤员或物资，想法这类抽象事物要用传达。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c46cb8d-7db9-433e-929e-cc38fb7b7492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95381, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "后送", "is_correct": true, "explanation": "正确：后送指把伤员送到后方安全处，与“直升机把重伤员……到市区医院”相符。"}, {"text": "投掷", "is_correct": false, "explanation": "语义：“投掷”是用力扔出，与安全转运重伤员的意思不符。"}, {"text": "散发", "is_correct": false, "explanation": "搭配：“散发”的对象是气味、传单等，不能用于人，不能说散发重伤员。"}, {"text": "遗弃", "is_correct": false, "explanation": "语义：“遗弃”指丢下不管，与救护重伤员的语境正好相反。"}], "explanations": {"后送": "正确：后送指把伤员送到后方安全处，与“直升机把重伤员……到市区医院”相符。", "投掷": "语义：“投掷”是用力扔出，与安全转运重伤员的意思不符。", "散发": "搭配：“散发”的对象是气味、传单等，不能用于人，不能说散发重伤员。", "遗弃": "语义：“遗弃”指丢下不管，与救护重伤员的语境正好相反。"}, "sentence_index": 6, "correct_answer": "后送"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "司机后送客人到机场。", "explanation": "这里应该用〈接送〉。后送指把伤员或物资送往后方安全处，接送乘客去机场是日常事务，要用接送。"}, {"text": "部队把健康的新兵后送到后方医院。", "explanation": "这里应该用〈调派〉。后送只用于伤员或需要转移的物资，把健康的新兵调往后方要用调派。"}, {"text": "快递员把包裹后送到我家。", "explanation": "这里应该用〈投递〉。后送指把伤员或物资送往后方，把包裹送到住处属于日常投递，要用投递。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c46cb8d-7db9-433e-929e-cc38fb7b7492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95381, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "护士把病人后送市里的医院。", "corrected_sentence": "护士把病人后送到市里的医院。", "error_description": "“后送”后面表示送达地点要用介词“到”，漏掉“到”，说成“后送市里的医院”，句子不通。正确形式是“后送到市里的医院”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c46cb8d-7db9-433e-929e-cc38fb7b7492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95381, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "救护队把重伤员后送在市区医院。", "corrected_sentence": "救护队把重伤员后送到市区医院。", "error_description": "“后送”后面表示送达地点要用“到”，不能用“在”，说成“后送在市区医院”是错的。正确形式是“后送到市区医院”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c46cb8d-7db9-433e-929e-cc38fb7b7492') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
