INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95386, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "加快速度；赶紧。", "primary_collocate": null, "pronunciation": "kuài diǎn", "ipa": "kʰuai̯˥˩ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "快点，我们要迟到了！", "target_word": "快点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快点起床，已经七点了。", "target_word": "快点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快点吧，大家都在等你。", "target_word": "快点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你快点回家，妈妈在找你。", "target_word": "快点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快点把作业做完，然后再玩。", "target_word": "快点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快点走，火车就要开了。", "target_word": "快点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快点来，饭已经做好了。", "target_word": "快点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨下大了，快点进屋吧。", "target_word": "快点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快点给他打电话，他还不知道。", "target_word": "快点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快点穿上外套，外面很冷。", "target_word": "快点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "快点儿", "label": "儿化"}, {"form": "快一点", "label": "扩展"}], "register": "口语", "sense_fingerprint": "放在动词前或单独使用，催促对方赶紧行动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e84f4cb-bc76-4322-ba77-d1f9128bfffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95386, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "快点", "is_correct": true, "explanation": "快点：催促对方赶紧行动。这里“快点，我们要迟到了”是催对方赶紧。"}, {"text": "慢点", "is_correct": false, "explanation": "语义：“慢点”是请人放慢，与“我们要迟到了”的紧迫语境矛盾。"}, {"text": "慢慢", "is_correct": false, "explanation": "语义：“慢慢”表示缓慢地做，与“我们要迟到了”的催促语境相反。"}, {"text": "轻点", "is_correct": false, "explanation": "搭配：“轻点”多用于动作力度或声音，不用来催促行动的速度。"}], "explanations": {"快点": "快点：催促对方赶紧行动。这里“快点，我们要迟到了”是催对方赶紧。", "慢点": "语义：“慢点”是请人放慢，与“我们要迟到了”的紧迫语境矛盾。", "慢慢": "语义：“慢慢”表示缓慢地做，与“我们要迟到了”的催促语境相反。", "轻点": "搭配：“轻点”多用于动作力度或声音，不用来催促行动的速度。"}, "sentence_index": 0, "correct_answer": "快点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他快点回家了，妈妈很高兴。", "explanation": "这里应该用〈赶紧〉。“快点”用于请对方加快动作，不能用来叙述他已经完成的回家；描述他急忙回去要用“赶紧”。"}, {"text": "我的手表快点了五分钟，你该调一下。", "explanation": "这里应该说〈快了〉，表示钟表比标准时间走得快。“快点”是催人加快动作的用法，不能用来描述钟表的快慢。"}, {"text": "他快点把作业交了，老师很满意。", "explanation": "这里应该用〈迅速〉。“快点”用于请对方加快动作；叙述他已经完成交作业这件事，要用“迅速”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b0cbc1-5c91-41cb-be3a-9ff8c12920a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95386, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "快点", "is_correct": true, "explanation": "快点：催促对方赶紧行动。这里是催对方快来吃饭。"}, {"text": "晚点", "is_correct": false, "explanation": "语义：“晚点”说时间靠后，与“饭已经做好了”催人快来的语境相反。"}, {"text": "慢些", "is_correct": false, "explanation": "语义：“慢些”是放慢速度，与“饭已经做好了”催促快来的语境矛盾。"}, {"text": "稍微", "is_correct": false, "explanation": "搭配：“稍微”修饰程度，不直接修饰“来”来表示催促。"}], "explanations": {"快点": "快点：催促对方赶紧行动。这里是催对方快来吃饭。", "晚点": "语义：“晚点”说时间靠后，与“饭已经做好了”催人快来的语境相反。", "慢些": "语义：“慢些”是放慢速度，与“饭已经做好了”催促快来的语境矛盾。", "稍微": "搭配：“稍微”修饰程度，不直接修饰“来”来表示催促。"}, "sentence_index": 6, "correct_answer": "快点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他快点就回来了，大家都很惊讶。", "explanation": "这里应该用〈很快〉。“快点”是催促用语，不能用“快点就”来叙述他已经回来的速度；描述速度要说“很快就”。"}, {"text": "这是一个快点的发展。", "explanation": "这里应该用〈快速〉。“快点”是副词，不能修饰名词“发展”。"}, {"text": "妈妈快点把饭做好了，我们都很饿。", "explanation": "这里应该用〈马上〉。“快点”用于请对方加快动作，不能用来叙述妈妈已经做完饭的事；表示很快做完要用“马上”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b0cbc1-5c91-41cb-be3a-9ff8c12920a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95386, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "快点了收衣服，要下雨了。", "corrected_sentence": "快点收衣服，要下雨了。", "error_description": "“了”位置错误：催促对方快做事时，“快点”后面不加“了”，应说“快点收衣服”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b0cbc1-5c91-41cb-be3a-9ff8c12920a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95386, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你快点一点去，我们等你吃饭。", "corrected_sentence": "你快点去，我们等你吃饭。", "error_description": "多余的“一点”：“快点”本身已含“快一点”的意思，不能再加“一点”，应说“你快点去”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b0cbc1-5c91-41cb-be3a-9ff8c12920a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
