INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95387, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "向别人问一问，想知道一件事。", "primary_collocate": null, "pronunciation": "dǎ wèn", "ipa": "ta˨˩ wən˥˩", "syllable_count": 2, "sentences": [{"text": "我想打问一下，附近有没有药店？", "target_word": "打问", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想向您打问一件事。", "target_word": "打问", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他打问了一下明天几点开会。", "target_word": "打问", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我去办公室打问考试的时间。", "target_word": "打问", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈打问我在学校的情况。", "target_word": "打问", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "游客向路人打问去博物馆怎么走。", "target_word": "打问", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你帮我打问打问这本书多少钱。", "target_word": "打问", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我打问过了，这家店周日不开门。", "target_word": "打问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她给同学打电话，打问作业是什么。", "target_word": "打问", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他走进店里，打问那件衣服的价钱。", "target_word": "打问", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "打问了", "label": "完成体"}, {"form": "打问过", "label": "经历体"}, {"form": "打问打问", "label": "重叠"}, {"form": "打問", "label": "繁体"}], "register": "方言", "sense_fingerprint": "方言动词，向别人问一问，想弄清楚某件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf8e96ba-5843-41cb-ac70-b4245e09e15d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95387, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "打问", "is_correct": true, "explanation": "正确。打问（dǎ wèn）指向别人问一问，想弄清楚某件事，是方言词。"}, {"text": "大吻", "is_correct": false, "explanation": "dà（第四声）与 dǎ（第三声）、wěn（第三声）与 wèn（第四声），声母韵母相同、仅声调不同；大吻指屋脊两端的装饰构件，与“打问”意思无关。"}, {"text": "答问", "is_correct": false, "explanation": "dá（第二声）与 dǎ（第三声）声调不同；答问意思是回答问题。"}, {"text": "打稳", "is_correct": false, "explanation": "wěn（第三声）与 wèn（第四声）声调不同；打稳意思是使牢固，如“打稳基础”，与“打问”意思无关。"}], "explanations": {"打问": "正确。打问（dǎ wèn）指向别人问一问，想弄清楚某件事，是方言词。", "大吻": "dà（第四声）与 dǎ（第三声）、wěn（第三声）与 wèn（第四声），声母韵母相同、仅声调不同；大吻指屋脊两端的装饰构件，与“打问”意思无关。", "答问": "dá（第二声）与 dǎ（第三声）声调不同；答问意思是回答问题。", "打稳": "wěn（第三声）与 wèn（第四声）声调不同；打稳意思是使牢固，如“打稳基础”，与“打问”意思无关。"}, "sentence_index": null, "correct_answer": "打问"}, "level_3": {"options": [{"text": "打问", "is_correct": true, "explanation": "正确。打问表示向别人打听，与“想”“一下”“附近有没有药店”的语境相符。"}, {"text": "买", "is_correct": false, "explanation": "配价：“买”需要具体的物品作宾语，不能接“附近有没有药店”这样的问句。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的意思是吃东西，与询问药店位置不相关。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”是清理卫生，与“附近有没有药店”的询问意思不符。"}], "explanations": {"打问": "正确。打问表示向别人打听，与“想”“一下”“附近有没有药店”的语境相符。", "买": "配价：“买”需要具体的物品作宾语，不能接“附近有没有药店”这样的问句。", "吃": "语义：“吃”的意思是吃东西，与询问药店位置不相关。", "打扫": "语义：“打扫”是清理卫生，与“附近有没有药店”的询问意思不符。"}, "sentence_index": 0, "correct_answer": "打问"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师在课堂上打问了我一个数学问题。", "explanation": "这里应该用〈提问〉。打问表示向人打听情况，不用于老师在课堂上向学生提出问题。"}, {"text": "经理打问大家准时下班。", "explanation": "这里应该用〈吩咐〉。打问只表示打听，不表示下命令让大家做事。"}, {"text": "他把碗打问碎了。", "explanation": "这里应该用〈打碎〉。“打”在此是打碎的义，打问表示打听，不能表示打碎东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccae7654-d98f-4311-ad19-924bf3796791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95387, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打问", "is_correct": true, "explanation": "正确。打问表示向人打听情况，“帮我打问打问”后接“这本书多少钱”，语义通顺。"}, {"text": "切", "is_correct": false, "explanation": "语义：“切”是把东西切开，与询问书价的意思不符。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”不能接“这本书多少钱”这样的询问结构。"}, {"text": "修", "is_correct": false, "explanation": "语义：“修”是修理，与询问书价的意思不符。"}], "explanations": {"打问": "正确。打问表示向人打听情况，“帮我打问打问”后接“这本书多少钱”，语义通顺。", "切": "语义：“切”是把东西切开，与询问书价的意思不符。", "喝": "搭配：“喝”不能接“这本书多少钱”这样的询问结构。", "修": "语义：“修”是修理，与询问书价的意思不符。"}, "sentence_index": 6, "correct_answer": "打问"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "班主任打问我们注意安全。", "explanation": "这里应该用〈嘱咐〉。打问表示打听，不表示叮嘱对方注意什么。"}, {"text": "大家打问她的歌声。", "explanation": "这里应该用〈赞美〉。打问的对象是情况或消息，不能用来评价歌声。"}, {"text": "我打问邻居照看孩子。", "explanation": "这里应该用〈拜托〉。打问表示打听情况，不表示请邻居帮忙照看孩子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccae7654-d98f-4311-ad19-924bf3796791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95387, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想了打问一下，这个小区的物业费怎么交。", "corrected_sentence": "我想打问一下，这个小区的物业费怎么交。", "error_description": "错误形式“想了打问”，正确形式“想打问”。“了”是完成标记，不能插在动词“打问”之前，应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccae7654-d98f-4311-ad19-924bf3796791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95387, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我不想打问了他的隐私。", "corrected_sentence": "我不想打问他的隐私。", "error_description": "错误形式“不想打问了”，正确形式“不想打问”。“不想”表示意愿，与完成标记“了”搭配不当，“了”应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccae7654-d98f-4311-ad19-924bf3796791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
