INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95390, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用相机摄取影像。", "primary_collocate": null, "pronunciation": "pāi zhào", "ipa": "pʰaɪ̯˥ ʈʂaʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "这里的风景很美，我想拍照。", "target_word": "拍照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你帮我们拍照，好吗？", "target_word": "拍照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里不能拍照。", "target_word": "拍照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每次旅游都喜欢拍照。", "target_word": "拍照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用新相机拍照，照片很清楚。", "target_word": "拍照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家站好，我要拍照了。", "target_word": "拍照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿着相机在公园里拍照。", "target_word": "拍照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你喜欢在这里拍照吗？", "target_word": "拍照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们笑着让妈妈拍照。", "target_word": "拍照", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "拍照的时候，请不要眨眼。", "target_word": "拍照", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "拍了照", "label": "体标（了）"}, {"form": "拍过照", "label": "体标（过）"}, {"form": "拍张照", "label": "离合"}], "register": "中性", "sense_fingerprint": "用相机摄取影像的动作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a65ce783-209c-496d-8375-67116e6f7c33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95390, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拍照", "is_correct": true, "explanation": "“拍照”指用相机拍影像，想在风景很美的地方做这件事，句意通顺。"}, {"text": "讲课", "is_correct": false, "explanation": "语义：“讲课”与前句的风景无关，不能表达想做的事。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”的对象须是可修的东西，风景不能修理，说不通。"}, {"text": "考试", "is_correct": false, "explanation": "语义：“考试”与风景无关，不能接在“我想”后面表达对风景的愿望。"}], "explanations": {"拍照": "“拍照”指用相机拍影像，想在风景很美的地方做这件事，句意通顺。", "讲课": "语义：“讲课”与前句的风景无关，不能表达想做的事。", "修理": "语义：“修理”的对象须是可修的东西，风景不能修理，说不通。", "考试": "语义：“考试”与风景无关，不能接在“我想”后面表达对风景的愿望。"}, "sentence_index": 0, "correct_answer": "拍照"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部电视剧的外景在海边拍照，拍了三个月。", "explanation": "这里应该用〈拍摄〉。拍照指用相机拍下静态影像，拍电影、电视剧要说拍摄。"}, {"text": "他用抹布把桌子拍照干净了。", "explanation": "这里应该用〈擦〉。拍照指用相机摄影，用抹布清洁桌子要说擦。"}, {"text": "他困得厉害，不停地拍照。", "explanation": "这里应该用〈打哈欠〉。拍照指用相机摄影，困了时的动作要说打哈欠。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '979e2659-c933-4818-bcef-e3cf85849824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95390, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拍照", "is_correct": true, "explanation": "“拍照”指用相机拍影像，与“拿着相机在公园里”的动作相符。"}, {"text": "下棋", "is_correct": false, "explanation": "语义：“下棋”与“拿着相机”的动作不搭，句中也没有棋具。"}, {"text": "演奏", "is_correct": false, "explanation": "语义：“演奏”需要乐器，与“拿着相机”的动作无关。"}, {"text": "照料", "is_correct": false, "explanation": "配价：“照料”需要照顾的对象作宾语，句中缺少这一成分，说不通。"}], "explanations": {"拍照": "“拍照”指用相机拍影像，与“拿着相机在公园里”的动作相符。", "下棋": "语义：“下棋”与“拿着相机”的动作不搭，句中也没有棋具。", "演奏": "语义：“演奏”需要乐器，与“拿着相机”的动作无关。", "照料": "配价：“照料”需要照顾的对象作宾语，句中缺少这一成分，说不通。"}, "sentence_index": 6, "correct_answer": "拍照"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他拍照，表示不同意。", "explanation": "这里应该用〈摇头〉。拍照指用相机摄影，表示不同意要说摇头。"}, {"text": "他听了表扬，拍照了。", "explanation": "这里应该用〈脸红〉。拍照指用相机摄影，害羞时要说脸红。"}, {"text": "他想了很久，终于拍照同意了。", "explanation": "这里应该用〈点头〉。拍照指用相机摄影，表示同意要说点头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '979e2659-c933-4818-bcef-e3cf85849824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95390, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在长城上拍照得很好看。", "corrected_sentence": "我们在长城上拍照拍得很好看。", "error_description": "错误形式：拍照得；正确形式：拍照拍得。离合词“拍照”带补语时要重复动词“拍”，再用“得”连接补语，直接说“拍照得”是常见错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '979e2659-c933-4818-bcef-e3cf85849824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95390, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们去年在北京拍照过，很难忘。", "corrected_sentence": "我们去年在北京拍过照，很难忘。", "error_description": "错误形式：拍照过；正确形式：拍过照。动态助词“过”应紧跟动词“拍”，放在离合词“拍照”中间，不能放在句尾。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '979e2659-c933-4818-bcef-e3cf85849824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
