INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95391, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "新的一年开始的日子，大家都很开心。", "primary_collocate": null, "pronunciation": "xīn nián", "ipa": "ɕin˥ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "新年到了，大家都很开心。", "target_word": "新年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新年那天，我们一家人一起吃饺子。", "target_word": "新年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新年的时候，孩子们都收到了红包。", "target_word": "新年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最喜欢新年，因为可以见到朋友。", "target_word": "新年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新年前，妈妈把房子打扫得很干净。", "target_word": "新年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新年那天，街上有很多人在唱歌跳舞。", "target_word": "新年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新年快乐！祝你身体健康。", "target_word": "新年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在新年晚会上唱了歌。", "target_word": "新年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新年就要到了，商店里很热闹。", "target_word": "新年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新年的第一天，我们去公园玩。", "target_word": "新年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "新年快乐", "label": "祝福语"}], "register": "中性", "sense_fingerprint": "新一年开始的节日，气氛开心热闹", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e84f4cb-bc76-4322-ba77-d1f9128bfffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95391, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "新年", "is_correct": true, "explanation": "新年：新的一年开始的日子，大家都很开心。这里“新年到了”正是指节日来临。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试到来并不会让大家开心，与“大家都很开心”的语境冲突。"}, {"text": "暴雨", "is_correct": false, "explanation": "语义：暴雨到来让人担心，与“大家都很开心”的语境不合。"}, {"text": "去年", "is_correct": false, "explanation": "搭配：“去年”指已经过去的时间，不说“去年到了”。"}], "explanations": {"新年": "新年：新的一年开始的日子，大家都很开心。这里“新年到了”正是指节日来临。", "考试": "语义：考试到来并不会让大家开心，与“大家都很开心”的语境冲突。", "暴雨": "语义：暴雨到来让人担心，与“大家都很开心”的语境不合。", "去年": "搭配：“去年”指已经过去的时间，不说“去年到了”。"}, "sentence_index": 0, "correct_answer": "新年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的新年很大了，还在努力工作。", "explanation": "这里应该用〈年纪〉。“新年”指新的一年开始的节日，不能用来说人的年龄。"}, {"text": "我每天早上看新年，了解世界大事。", "explanation": "这里应该用〈新闻〉。“新年”是节日，不能用“看”来说了解大事；了解世界大事要说“看新闻”。"}, {"text": "我们班来了一个新年。", "explanation": "这里应该用〈新人〉。“新年”指节日时间，不能指新来的人；班里来的新同学要说“新人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b0cbc1-5c91-41cb-be3a-9ff8c12920a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95391, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "新年", "is_correct": true, "explanation": "新年：新的一年开始的日子，大家都很开心。这里“新年快乐”是常用的祝福语。"}, {"text": "手术", "is_correct": false, "explanation": "语义：祝福语不能用于手术，“手术快乐”与祝福的语境不合。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：“感冒快乐”与祝福的语境相反。"}, {"text": "晚上", "is_correct": false, "explanation": "搭配：“晚上快乐”不是常用的祝福语，应说“晚安”。"}], "explanations": {"新年": "新年：新的一年开始的日子，大家都很开心。这里“新年快乐”是常用的祝福语。", "手术": "语义：祝福语不能用于手术，“手术快乐”与祝福的语境不合。", "感冒": "语义：“感冒快乐”与祝福的语境相反。", "晚上": "搭配：“晚上快乐”不是常用的祝福语，应说“晚安”。"}, "sentence_index": 6, "correct_answer": "新年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新年穿着红色的礼服，非常漂亮。", "explanation": "这里应该用〈新娘〉。“新年”指节日，不能指穿礼服的人；婚礼上穿红色礼服的人要说“新娘”。"}, {"text": "今天的新年很好，大家都很高兴。", "explanation": "这里应该用〈天气〉。“新年”指节日，不能用来形容天气好坏；说今天天气好要用“天气”。"}, {"text": "我们班的新年要考试了。", "explanation": "这里应该用〈新学期〉。“新年”指节日，不能当作学校的学期或考试时间；学校开学的时间要说“新学期”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b0cbc1-5c91-41cb-be3a-9ff8c12920a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95391, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们一家人过了一条开心的新年。", "corrected_sentence": "我们一家人过了一个开心的新年。", "error_description": "量词错误：“新年”是时间，应用“个”，“条”多用于细长的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b0cbc1-5c91-41cb-be3a-9ff8c12920a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95391, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "祝你和家人新年快乐了。", "corrected_sentence": "祝你和家人新年快乐。", "error_description": "“了”多余：祝福语“新年快乐”后面不加“了”，应说“祝你和家人新年快乐”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b0cbc1-5c91-41cb-be3a-9ff8c12920a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
