INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95393, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "一个接着一个，按顺序来。", "primary_collocate": null, "pronunciation": "cì dì", "ipa": "tsʰɨ˥˩ ti˥˩", "syllable_count": 2, "sentences": [{"text": "春天来了，山上的花次第开放。", "target_word": "次第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜幕降临，街边的灯次第亮了起来。", "target_word": "次第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨过天晴，田里的小草次第冒出了头。", "target_word": "次第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑了，村里的灯火次第亮起。", "target_word": "次第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天到了，树上的叶子次第变黄。", "target_word": "次第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳升起，山谷里的鸟儿次第唱起歌来。", "target_word": "次第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "烟花次第升上夜空，孩子们都看呆了。", "target_word": "次第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红灯笼次第挂了起来，新年到了。", "target_word": "次第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰雪融化，河边的柳树次第发芽。", "target_word": "次第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后，草地上的蘑菇次第冒了出来。", "target_word": "次第", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "许多事物一个接着一个地出现或发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e57226eb-7676-4c4b-9e91-9ee86200188c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95393, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "次第", "is_correct": true, "explanation": "「次第」读作 cì dì，表示一个接一个地依次出现，是本题要听辨的词。"}, {"text": "此地", "is_correct": false, "explanation": "cǐ（第三声）与 cì（第四声）声调不同，意思是“这个地方”。"}, {"text": "质地", "is_correct": false, "explanation": "zhì 与 cì 声母不同（zh 与 c），意思是材料的质地。"}, {"text": "次日", "is_correct": false, "explanation": "rì 与 dì 声母不同（r 与 d），意思是第二天。"}], "explanations": {"次第": "「次第」读作 cì dì，表示一个接一个地依次出现，是本题要听辨的词。", "此地": "cǐ（第三声）与 cì（第四声）声调不同，意思是“这个地方”。", "质地": "zhì 与 cì 声母不同（zh 与 c），意思是材料的质地。", "次日": "rì 与 dì 声母不同（r 与 d），意思是第二天。"}, "sentence_index": null, "correct_answer": "次第"}, "level_3": {"options": [{"text": "次第", "is_correct": true, "explanation": "表示花一个接一个地依次开放，与“春天来了，山上的花……开放”的语境相符。"}, {"text": "齐声", "is_correct": false, "explanation": "搭配：“齐声”指很多人同时发出声音，不能用来修饰花开。"}, {"text": "从不", "is_correct": false, "explanation": "语义：“从不”表示从来没有，与春天花开的情景相矛盾。"}, {"text": "倒退", "is_correct": false, "explanation": "语义：“倒退”指向后移动，与花开放的语境完全不符。"}], "explanations": {"次第": "表示花一个接一个地依次开放，与“春天来了，山上的花……开放”的语境相符。", "齐声": "搭配：“齐声”指很多人同时发出声音，不能用来修饰花开。", "从不": "语义：“从不”表示从来没有，与春天花开的情景相矛盾。", "倒退": "语义：“倒退”指向后移动，与花开放的语境完全不符。"}, "sentence_index": 0, "correct_answer": "次第"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子们次第起立，动作一致。", "explanation": "这里应该用〈整齐〉。“次第”表示依次先后，与同时整齐起立的场面相反。"}, {"text": "铃声一响，所有的灯次第在同一秒亮了。", "explanation": "这里应该用〈同时〉。“次第”表示一个接一个先后出现，与“在同一秒”同时亮起相矛盾。"}, {"text": "一个人次第走进了教室。", "explanation": "这里应该用〈独自〉。“次第”需要两个或更多的人或事物依次进行，单人行动时不能用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e75261c7-f620-4be4-87ac-2f670776b085') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95393, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "次第", "is_correct": true, "explanation": "表示烟花一个接一个地依次升空，与句意相符。"}, {"text": "擅自", "is_correct": false, "explanation": "语义：“擅自”指未经许可就自作主张，烟花升空没有这种意味。"}, {"text": "倒转", "is_correct": false, "explanation": "语义：“倒转”指方向相反地转动，与烟花向上升空的情景相矛盾。"}, {"text": "一概", "is_correct": false, "explanation": "语义：“一概”表示全部、毫无例外，与“次第”逐个升空的过程相冲突。"}], "explanations": {"次第": "表示烟花一个接一个地依次升空，与句意相符。", "擅自": "语义：“擅自”指未经许可就自作主张，烟花升空没有这种意味。", "倒转": "语义：“倒转”指方向相反地转动，与烟花向上升空的情景相矛盾。", "一概": "语义：“一概”表示全部、毫无例外，与“次第”逐个升空的过程相冲突。"}, "sentence_index": 6, "correct_answer": "次第"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨后，草地上的蘑菇次第一下子全冒了出来。", "explanation": "这里应该用〈一下子〉，去掉“次第”。“次第”表示一个接一个先后出现，与“一下子全”同时出现相矛盾。"}, {"text": "雨后，草地上只有一个蘑菇次第冒了出来。", "explanation": "这里应该用〈悄悄〉。“次第”需要多个事物先后出现，只有一个时不能用。"}, {"text": "雨后，草地上的蘑菇次第同时冒了出来。", "explanation": "这里应该用〈同时〉，去掉“次第”。“次第”指先后依次，不能与“同时”共用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e75261c7-f620-4be4-87ac-2f670776b085') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95393, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨停了，屋檐下的水滴次第的落下。", "corrected_sentence": "雨停了，屋檐下的水滴次第落下。", "error_description": "结构助词错误：“次第”是副词，修饰动词时后面不能加“的”，应说“次第落下”，不能说“次第的落下”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e75261c7-f620-4be4-87ac-2f670776b085') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95393, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "路灯次第亮了起去。", "corrected_sentence": "路灯次第亮了起来。", "error_description": "补语错误：“亮起来”是“亮”加趋向补语“起来”，不能说“起去”。改为：路灯次第亮了起来。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e75261c7-f620-4be4-87ac-2f670776b085') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
