INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95394, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "依次；按顺序。", "primary_collocate": null, "pronunciation": "cì dì", "ipa": "tsʰɨ˥˩ ti˥˩", "syllable_count": 2, "sentences": [{"text": "客人到了，大家次第入座。", "target_word": "次第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请同学们次第走进教室。", "target_word": "次第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议开始，经理们次第发言。", "target_word": "次第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人次第走进诊室，医生一个一个检查。", "target_word": "次第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "队伍次第通过了检查口。", "target_word": "次第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演员们次第上台，向观众鞠躬。", "target_word": "次第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动员次第走进体育场。", "target_word": "次第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师叫到名字，学生们次第上前领奖。", "target_word": "次第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车辆次第驶出了停车场。", "target_word": "次第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客们次第登上了小船。", "target_word": "次第", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "人或事物按先后顺序依次行动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e57226eb-7676-4c4b-9e91-9ee86200188c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95394, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "次第", "is_correct": true, "explanation": "「次第」读作 cì dì，表示按顺序一个接一个地进行，是本题要听辨的词。"}, {"text": "此地", "is_correct": false, "explanation": "cǐ（第三声）与 cì（第四声）声调不同，意思是“这个地方”。"}, {"text": "质地", "is_correct": false, "explanation": "zhì 与 cì 声母不同（zh 与 c），意思是材料的质地。"}, {"text": "次日", "is_correct": false, "explanation": "rì 与 dì 声母不同（r 与 d），意思是第二天。"}], "explanations": {"次第": "「次第」读作 cì dì，表示按顺序一个接一个地进行，是本题要听辨的词。", "此地": "cǐ（第三声）与 cì（第四声）声调不同，意思是“这个地方”。", "质地": "zhì 与 cì 声母不同（zh 与 c），意思是材料的质地。", "次日": "rì 与 dì 声母不同（r 与 d），意思是第二天。"}, "sentence_index": null, "correct_answer": "次第"}, "level_3": {"options": [{"text": "次第", "is_correct": true, "explanation": "表示大家按先后顺序一个接一个地入座，与“客人到了”的语境相符。"}, {"text": "齐声", "is_correct": false, "explanation": "搭配：“齐声”指很多人同时发出声音，不能用来修饰入座。"}, {"text": "从不", "is_correct": false, "explanation": "语义：“从不”表示从来没有，与“客人到了，大家”后入座的情景相矛盾。"}, {"text": "反复", "is_correct": false, "explanation": "语义：“反复”表示多次重复，入座只是一次性的动作，与句意不符。"}], "explanations": {"次第": "表示大家按先后顺序一个接一个地入座，与“客人到了”的语境相符。", "齐声": "搭配：“齐声”指很多人同时发出声音，不能用来修饰入座。", "从不": "语义：“从不”表示从来没有，与“客人到了，大家”后入座的情景相矛盾。", "反复": "语义：“反复”表示多次重复，入座只是一次性的动作，与句意不符。"}, "sentence_index": 0, "correct_answer": "次第"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "同学们次第一起跑向操场。", "explanation": "这里应该用〈一起〉。“次第”指依次先后，与“一起”的同时行动相矛盾。"}, {"text": "病人一齐次第走进诊室，医生一个一个检查。", "explanation": "这里应该用〈同时〉。“次第”强调依次先后，不能用来修饰表示同一时刻进行的动作。"}, {"text": "他一个人次第走进诊室，医生一个一个检查。", "explanation": "这里应该用〈独自〉。“次第”需要两个或更多的人依次进行，只有一人时不能用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e75261c7-f620-4be4-87ac-2f670776b085') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95394, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "次第", "is_correct": true, "explanation": "表示运动员一个接一个地依次进场，与句意相符。"}, {"text": "擅自", "is_correct": false, "explanation": "语义：“擅自”指未经许可就自作主张，与运动员按顺序进场的语境不符。"}, {"text": "一概", "is_correct": false, "explanation": "语义：“一概”表示全部、毫无例外，与“次第”逐个进场的过程相冲突。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”多与否定词连用，这里不能说“从来走进体育场”。"}], "explanations": {"次第": "表示运动员一个接一个地依次进场，与句意相符。", "擅自": "语义：“擅自”指未经许可就自作主张，与运动员按顺序进场的语境不符。", "一概": "语义：“一概”表示全部、毫无例外，与“次第”逐个进场的过程相冲突。", "从来": "搭配：“从来”多与否定词连用，这里不能说“从来走进体育场”。"}, "sentence_index": 6, "correct_answer": "次第"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "游客们次第登船，乱成一团。", "explanation": "这里应该用〈纷纷〉。“纷纷”指许多人杂乱地行动，与“次第”的有序先后相反。"}, {"text": "雨点次第同时落下，地上一片狼藉。", "explanation": "这里应该用〈一齐〉。“次第”指依次先后，不能用来表示全部在同一时刻落下。"}, {"text": "学生们次第一起上了车。", "explanation": "这里应该用〈一起〉。“次第”指依次先后，与“一起”的同时行动相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e75261c7-f620-4be4-87ac-2f670776b085') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95394, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会议结束后，同学们次第的离场。", "corrected_sentence": "会议结束后，同学们次第离场。", "error_description": "“次第”是副词，修饰动词时不能加“的”，应说“次第离场”；“次第的离场”结构错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e75261c7-f620-4be4-87ac-2f670776b085') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95394, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工作人员通知后，观众们次第的进场。", "corrected_sentence": "工作人员通知后，观众们次第进场。", "error_description": "“次第”是副词，修饰动词时不能加“的”，应说“观众们次第进场”；“次第的进场”结构错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e75261c7-f620-4be4-87ac-2f670776b085') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
