INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95395, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "歌里唱的那些话。", "primary_collocate": null, "pronunciation": "gē cí", "ipa": "kɤ˥ tsʰɨ˧˥", "syllable_count": 2, "sentences": [{"text": "这首歌的歌词很美，我很喜欢。", "target_word": "歌词", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我听不懂这首英文歌的歌词。", "target_word": "歌词", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她唱歌的时候忘了歌词，很不好意思。", "target_word": "歌词", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这句歌词让我想起了妈妈。", "target_word": "歌词", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟能记住每一句歌词。", "target_word": "歌词", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请我们看着歌词一起唱。", "target_word": "歌词", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写的歌词都是关于家乡的故事。", "target_word": "歌词", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "歌词里说，明天会更好。", "target_word": "歌词", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌的歌词太长，我一下子记不住。", "target_word": "歌词", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把歌词抄在本子上，想慢慢学唱。", "target_word": "歌词", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一句歌词", "label": "量词"}, {"form": "一段歌词", "label": "量词"}, {"form": "歌詞", "label": "繁体"}], "register": "中性", "sense_fingerprint": "歌里唱出来的话语内容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c139710-9a85-4ec9-b9b6-0cb261a0b0c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95395, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "歌词", "is_correct": true, "explanation": "正确：“歌词”是歌里唱的文字，可以用“美”来形容。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”指大气状况，不是歌的组成部分。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“美”形容外观或声音，不能用来说价格。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”是做饭的地方，与歌无关。"}], "explanations": {"歌词": "正确：“歌词”是歌里唱的文字，可以用“美”来形容。", "天气": "语义：“天气”指大气状况，不是歌的组成部分。", "价格": "搭配：“美”形容外观或声音，不能用来说价格。", "厨房": "语义：“厨房”是做饭的地方，与歌无关。"}, "sentence_index": 0, "correct_answer": "歌词"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌的歌词是用钢琴弹出来的，很好听。", "explanation": "这里应该用〈旋律〉。“旋律”可以用乐器演奏，歌词是文字，不能用钢琴弹。"}, {"text": "我把歌词切成三块，放进锅里煮。", "explanation": "这里把“歌词”误当成食材这类实物。“歌词”是歌里唱的文字，不能切块、下锅。"}, {"text": "这首歌词跑得特别快，一下子就到了门口。", "explanation": "这里应该用〈节奏〉。“歌词”是歌里唱的文字，不能像人或动物那样跑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f8b4656-bee1-4fd8-ab2a-1afecd013050') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95395, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "歌词", "is_correct": true, "explanation": "正确：“歌词”可以“写”，并且能讲述家乡的故事。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：“钥匙”是开门的工具，不能讲故事。"}, {"text": "早餐", "is_correct": false, "explanation": "搭配：“写”不能与“早餐”搭配，早餐不能被写。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：“汽车”是交通工具，不能写出关于家乡的故事。"}], "explanations": {"歌词": "正确：“歌词”可以“写”，并且能讲述家乡的故事。", "钥匙": "语义：“钥匙”是开门的工具，不能讲故事。", "早餐": "搭配：“写”不能与“早餐”搭配，早餐不能被写。", "汽车": "语义：“汽车”是交通工具，不能写出关于家乡的故事。"}, "sentence_index": 6, "correct_answer": "歌词"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把歌词放进冰箱里，想让它保持新鲜。", "explanation": "这里把“歌词”误当成食物。“歌词”是歌里唱的文字，不能放进冰箱保鲜。"}, {"text": "他写了一颗歌词，很感人。", "explanation": "这里应该用〈段〉。“颗”用于圆形小物，歌词常用“段”或“句”计量。"}, {"text": "我们在歌词里吃午饭，很开心。", "explanation": "这里把“歌词”误当成可以进入、用来吃饭的场所。应说〈餐厅〉。“歌词”是歌里唱的文字，不能在里面吃饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f8b4656-bee1-4fd8-ab2a-1afecd013050') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95395, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我吃了这首歌的歌词。", "corrected_sentence": "我看了这首歌的歌词。", "error_description": "动词搭配错误：“吃”不能用于歌词（歌词是要看、要唱的文字），应说“看”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f8b4656-bee1-4fd8-ab2a-1afecd013050') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95395, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她喝了一首关于大海的歌词。", "corrected_sentence": "她写了一首关于大海的歌词。", "error_description": "动词搭配错误：歌词是文字，可以“写、唱、看”，不能“喝”，应说“写了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f8b4656-bee1-4fd8-ab2a-1afecd013050') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
