INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95396, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "歌曲中的文字部分。", "primary_collocate": null, "pronunciation": "gē cí", "ipa": "kɤ˥ tsʰɨ˧˥", "syllable_count": 2, "sentences": [{"text": "手机屏幕上有这首歌的歌词。", "target_word": "歌词", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "歌词印在盒子里的小本子上。", "target_word": "歌词", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌只有曲子，没有歌词。", "target_word": "歌词", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把歌词发给我，我想学唱。", "target_word": "歌词", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的歌词写得很简单，容易记。", "target_word": "歌词", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌的歌词一共有三段。", "target_word": "歌词", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在网上找到了这首歌的歌词。", "target_word": "歌词", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "歌词和曲子配得很好。", "target_word": "歌词", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屏幕上的歌词一句一句地出现。", "target_word": "歌词", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她正在为新歌写歌词。", "target_word": "歌词", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一段歌词", "label": "量词"}, {"form": "一句歌词", "label": "量词"}, {"form": "歌詞", "label": "繁体"}], "register": "中性", "sense_fingerprint": "歌曲里与曲子相对的文字部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c139710-9a85-4ec9-b9b6-0cb261a0b0c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95396, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "歌词", "is_correct": true, "explanation": "正确：“歌词”是歌曲中的文字部分，可以出现在屏幕上。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指人或动物的重量，歌曲没有体重。"}, {"text": "胃口", "is_correct": false, "explanation": "语义：“胃口”指食欲，不能用于歌曲。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”指人的高矮，歌曲没有身高。"}], "explanations": {"歌词": "正确：“歌词”是歌曲中的文字部分，可以出现在屏幕上。", "体重": "语义：“体重”指人或动物的重量，歌曲没有体重。", "胃口": "语义：“胃口”指食欲，不能用于歌曲。", "身高": "语义：“身高”指人的高矮，歌曲没有身高。"}, "sentence_index": 0, "correct_answer": "歌词"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请把歌词发给我，我想学弹。", "explanation": "这里应该用〈曲谱〉。学弹要看乐谱，歌词只是文字。"}, {"text": "这首歌词在厨房里做饭，味道很好。", "explanation": "“歌词”是文字，不能做饭，句子把它当作有行为能力的对象。"}, {"text": "我把歌词擦了擦，然后放进冰箱。", "explanation": "歌词是文字内容，不是可以擦拭、放进冰箱保存的实物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f8b4656-bee1-4fd8-ab2a-1afecd013050') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95396, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "歌词", "is_correct": true, "explanation": "正确：“歌词”可以在网上找到，与句意相符。"}, {"text": "手指", "is_correct": false, "explanation": "语义：“手指”是身体部位，不是可以在网上找到的内容。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“体温”是测量的对象，不能与“找到”搭配。"}, {"text": "房间", "is_correct": false, "explanation": "语义：“房间”是居住的空间，不是歌的一部分，与句意矛盾。"}], "explanations": {"歌词": "正确：“歌词”可以在网上找到，与句意相符。", "手指": "语义：“手指”是身体部位，不是可以在网上找到的内容。", "体温": "搭配：“体温”是测量的对象，不能与“找到”搭配。", "房间": "语义：“房间”是居住的空间，不是歌的一部分，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "歌词"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她正在为新歌取歌词。", "explanation": "这里应该用〈歌名〉。“取”多用于名字，歌词是歌里的文字内容，不说“取歌词”。"}, {"text": "这位歌词很有名，大家都认识她。", "explanation": "这里应该用〈歌手〉。“歌词”是歌里唱的文字，不能用量词“位”指人，句中把它当成了歌手。"}, {"text": "她正在为新歌洗歌词，洗得很干净。", "explanation": "“洗”的对象是实物，歌词是文字，不能用来洗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f8b4656-bee1-4fd8-ab2a-1afecd013050') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95396, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我切过这首歌的歌词。", "corrected_sentence": "我看过这首歌的歌词。", "error_description": "动词搭配错误：“切”用于实物，歌词是文字，不能切；应说“看过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f8b4656-bee1-4fd8-ab2a-1afecd013050') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95396, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在书店里吃到了那首老歌的歌词。", "corrected_sentence": "我在书店里看到了那首老歌的歌词。", "error_description": "动词搭配错误：歌词是文字内容，可以“看到、找到”，不能“吃到”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f8b4656-bee1-4fd8-ab2a-1afecd013050') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
