INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95397, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "这一类事情，或者这一种办法。", "primary_collocate": null, "pronunciation": "cǐ dào", "ipa": "tsʰɨ˨˩˦ taʊ˥˩", "syllable_count": 2, "sentences": [{"text": "他在此道上很有经验。", "target_word": "此道", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我对此道一点儿也不懂。", "target_word": "此道", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这位老师精通此道。", "target_word": "此道", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "说到做生意，他是此道高手。", "target_word": "此道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他多年研究此道，很有心得。", "target_word": "此道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她十岁开始学书法，一直深爱此道。", "target_word": "此道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不懂此道，你去问内行人吧。", "target_word": "此道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做菜这件事，他早就是此道中人了。", "target_word": "此道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "修理手表，他可是此道的老手。", "target_word": "此道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对此道见解独到，颇受同行推崇。", "target_word": "此道", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "书面语名词，指前面说到的这一类事情或这一行，常见于“精通此道”“此道高手”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf8e96ba-5843-41cb-ac70-b4245e09e15d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95397, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小狗", "is_correct": false, "explanation": "语义：小狗不是可以积累经验的领域，“在小狗上很有经验”不成立。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：“在…上”后接抽象的领域，不说“在厨房上”，句子说不通。"}, {"text": "此道", "is_correct": true, "explanation": "此道：书面语，指这一类事情或这一行，与“在…上”搭配，正好说“在此道上很有经验”。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空是自然景物，不能作为积累经验的领域。"}], "explanations": {"小狗": "语义：小狗不是可以积累经验的领域，“在小狗上很有经验”不成立。", "厨房": "搭配：“在…上”后接抽象的领域，不说“在厨房上”，句子说不通。", "此道": "此道：书面语，指这一类事情或这一行，与“在…上”搭配，正好说“在此道上很有经验”。", "天空": "语义：天空是自然景物，不能作为积累经验的领域。"}, "sentence_index": 0, "correct_answer": "此道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的此道是医生。", "explanation": "这里应该用〈职业〉。此道指一类事情或办法，不能用来指一个人的职业，说「他的职业是医生」才对。"}, {"text": "他们昨天举办了一场此道。", "explanation": "这里应该用〈比赛〉。此道指一类事情或办法，不指具体的活动，「举办」后应接「比赛」「活动」等。"}, {"text": "我们班来了一只此道。", "explanation": "量词用错：〈只〉用于动物或成对的东西，此道是抽象的事情或一行，不能用〈只〉计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccae7654-d98f-4311-ad19-924bf3796791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95397, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "杯子", "is_correct": false, "explanation": "语义：杯子是器物，不是可以“懂”的一门学问或技艺。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“不懂”的对象应是知识、技艺或事理，不说“不懂窗户”。"}, {"text": "此道", "is_correct": true, "explanation": "此道：书面语，指某一行或某类事情，“我不懂此道”指不懂这一行，与后句“问内行人”照应。"}, {"text": "饭碗", "is_correct": false, "explanation": "语义：饭碗指饭和工作，不能作为“懂”的对象，句子不通。"}], "explanations": {"杯子": "语义：杯子是器物，不是可以“懂”的一门学问或技艺。", "窗户": "搭配：“不懂”的对象应是知识、技艺或事理，不说“不懂窗户”。", "此道": "此道：书面语，指某一行或某类事情，“我不懂此道”指不懂这一行，与后句“问内行人”照应。", "饭碗": "语义：饭碗指饭和工作，不能作为“懂”的对象，句子不通。"}, "sentence_index": 6, "correct_answer": "此道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们去超市买此道吧。", "explanation": "此道指一类事情或一行，是抽象的，不是可以购买的具体东西，不能说“买此道”。"}, {"text": "他把此道挂在墙上了。", "explanation": "此道是抽象的，不能像画一样挂在墙上，这里不这么用。"}, {"text": "他吃完饭，把此道洗干净了。", "explanation": "此道不是有形的器物，不能说“洗干净”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccae7654-d98f-4311-ad19-924bf3796791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95397, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在这个此道上很有名望。", "corrected_sentence": "他在此道上很有名望。", "error_description": "错误在“这个”：“此”已表示“这一”，不能再用“这个”修饰“此道”，应去掉“这个”，说“此道”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccae7654-d98f-4311-ad19-924bf3796791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95397, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她是此道地行家，大家都佩服她。", "corrected_sentence": "她是此道的行家，大家都佩服她。", "error_description": "错误在助词：“此道”修饰名词“行家”时要用“的”，不能用“地”；“地”用于修饰动词或形容词，应说“此道的行家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccae7654-d98f-4311-ad19-924bf3796791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
