INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95398, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccae7654-d98f-4311-ad19-924bf3796791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95398, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "这种事情或这种方法。", "primary_collocate": null, "pronunciation": "cǐ dào", "ipa": "tsʰɨ˨˩˦ taʊ˥˩", "syllable_count": 2, "sentences": [{"text": "他从小喜欢下棋，对此道很有兴趣。", "target_word": "此道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "打鱼是老人的本行，他最懂此道。", "target_word": "此道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你想学钓鱼，就得先懂此道的规矩。", "target_word": "此道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "用蛮力解决问题，此道行不通。", "target_word": "此道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他爱喝茶，是此道的行家。", "target_word": "此道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做饭我不懂，你找精于此道的人吧。", "target_word": "此道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她做了二十年编辑，深知此道的难处。", "target_word": "此道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "先打基础再提高，此道最稳妥。", "target_word": "此道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我对摄影略知一二，不敢说精通此道。", "target_word": "此道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不靠运气，靠勤奋，此道很管用。", "target_word": "此道", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "书面语名词，指前面提到的这种事情或这种方法，如“此道行不通”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf8e96ba-5843-41cb-ac70-b4245e09e15d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95398, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "眼泪", "is_correct": false, "explanation": "语义：眼泪不是可以产生兴趣的对象，句子说不通。"}, {"text": "此道", "is_correct": true, "explanation": "此道：书面语，指下棋这类事情，与“对…有兴趣”搭配，承接前句。"}, {"text": "悲伤", "is_correct": false, "explanation": "搭配：“对…有兴趣”后接可以喜爱或钻研的事，不说“对悲伤有兴趣”。"}, {"text": "疼痛", "is_correct": false, "explanation": "语义：疼痛是身体感受，不能作为兴趣的对象。"}], "explanations": {"眼泪": "语义：眼泪不是可以产生兴趣的对象，句子说不通。", "此道": "此道：书面语，指下棋这类事情，与“对…有兴趣”搭配，承接前句。", "悲伤": "搭配：“对…有兴趣”后接可以喜爱或钻研的事，不说“对悲伤有兴趣”。", "疼痛": "语义：疼痛是身体感受，不能作为兴趣的对象。"}, "sentence_index": 0, "correct_answer": "此道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他退休前的此道是老师。", "explanation": "这里应该用〈职业〉。此道指一类事情或办法，不能指人的职业，说「他退休前的职业是老师」才对。"}, {"text": "他把此道搬到了楼上。", "explanation": "此道是抽象的事情或办法，不是可以搬动的东西，这里不这么用。"}, {"text": "她每天把此道吃得干干净净。", "explanation": "此道是抽象的事情或办法，这里却当成了可以吃的食物，是把它误当成具体东西来用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccae7654-d98f-4311-ad19-924bf3796791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95398, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天空", "is_correct": false, "explanation": "语义：天空不是有难处的事情，“深知天空的难处”说不通。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是器物，不能说有“难处”。"}, {"text": "此道", "is_correct": true, "explanation": "此道：书面语，指编辑这一行，与前句“做了二十年编辑”照应，与“深知…的难处”搭配。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：“难处”指做事的困难，人体器官不能与之搭配。"}], "explanations": {"天空": "语义：天空不是有难处的事情，“深知天空的难处”说不通。", "桌子": "语义：桌子是器物，不能说有“难处”。", "此道": "此道：书面语，指编辑这一行，与前句“做了二十年编辑”照应，与“深知…的难处”搭配。", "眼睛": "搭配：“难处”指做事的困难，人体器官不能与之搭配。"}, "sentence_index": 6, "correct_answer": "此道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们学校每年都举办一场此道。", "explanation": "这里应该用〈比赛〉。此道指事情或办法，不指具体的活动，「举办」后应接「比赛」「活动」等。"}, {"text": "他每月领此道。", "explanation": "这里应该用〈工资〉。此道指事情或办法，不能用来指钱，「领」后应接「工资」「奖金」等。"}, {"text": "我想出了一台此道。", "explanation": "量词用错：〈台〉用于机器，此道是抽象的事情或办法，不能用〈台〉计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccae7654-d98f-4311-ad19-924bf3796791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95398, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "试了很多次，这种此道都行不通。", "corrected_sentence": "试了很多次，此道都行不通。", "error_description": "错误在“这种”：“此”已表示“这一”，不能再与“这种”并用，应去掉“这种”，说“此道”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccae7654-d98f-4311-ad19-924bf3796791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95398, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "慢慢来，把此道最稳妥。", "corrected_sentence": "慢慢来，此道最稳妥。", "error_description": "错误在“把”：“把”字句要求后面接动词性谓语，“此道最稳妥”是主谓结构，不能放在“把”后，去掉“把”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccae7654-d98f-4311-ad19-924bf3796791') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
