INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95402, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "政策、管理或信息等影响无法到达的领域。", "primary_collocate": null, "pronunciation": "sǐ qū", "ipa": "sɿ˨˩˦ tɕʰy˥", "syllable_count": 2, "sentences": [{"text": "这个政策在农村还有死区。", "target_word": "死区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新法律的影响还有很多死区。", "target_word": "死区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司管理中还有一些死区。", "target_word": "死区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这类纠纷在现行规定里仍是死区，无人过问。", "target_word": "死区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小镇是新闻的死区，报纸送不进来。", "target_word": "死区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要找出管理上的死区，别让它们没人管。", "target_word": "死区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山区成了教育政策的死区。", "target_word": "死区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小商店是这条规定的死区，没人检查。", "target_word": "死区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的影响很大，但在老年人中有死区。", "target_word": "死区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个品牌的广告在小城市还是死区。", "target_word": "死区", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "政策、管理、信息等影响不到的领域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3ab1b92-169b-4c40-8f7b-26a651420c25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95402, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "死区", "is_correct": true, "explanation": "死区：政策、管理或信息等影响不到的领域，正确答案。"}, {"text": "死去", "is_correct": false, "explanation": "qù（第四声）与 qū（第一声）声调不同，意思是死亡，与政策或信息无关。"}, {"text": "市区", "is_correct": false, "explanation": "shì（第四声）与 sǐ（第三声）声母与声调都不同，意思是城市里的区域。"}, {"text": "时区", "is_correct": false, "explanation": "shí（第二声）与 sǐ（第三声）声母与声调都不同，意思是地球上按时间划分的区域。"}, {"text": "四区", "is_correct": false, "explanation": "sì（第四声）与 sǐ（第三声）声调不同，意思是第四个区域，与影响范围无关。"}], "explanations": {"死区": "死区：政策、管理或信息等影响不到的领域，正确答案。", "死去": "qù（第四声）与 qū（第一声）声调不同，意思是死亡，与政策或信息无关。", "市区": "shì（第四声）与 sǐ（第三声）声母与声调都不同，意思是城市里的区域。", "时区": "shí（第二声）与 sǐ（第三声）声母与声调都不同，意思是地球上按时间划分的区域。", "四区": "sì（第四声）与 sǐ（第三声）声调不同，意思是第四个区域，与影响范围无关。"}, "sentence_index": null, "correct_answer": "死区"}, "level_3": {"options": [{"text": "死区", "is_correct": true, "explanation": "死区指政策影响不到的领域，与“这个政策在农村”的语境吻合。"}, {"text": "摩天大楼", "is_correct": false, "explanation": "搭配：“农村”与“摩天大楼”搭配不当，句意不通。"}, {"text": "大都市", "is_correct": false, "explanation": "语义：“大都市”与“农村”相对，不能说政策在农村还有大都市。"}, {"text": "冰山", "is_correct": false, "explanation": "语义：冰山不是政策能够影响的领域，与“政策”的所指冲突。"}], "explanations": {"死区": "死区指政策影响不到的领域，与“这个政策在农村”的语境吻合。", "摩天大楼": "搭配：“农村”与“摩天大楼”搭配不当，句意不通。", "大都市": "语义：“大都市”与“农村”相对，不能说政策在农村还有大都市。", "冰山": "语义：冰山不是政策能够影响的领域，与“政策”的所指冲突。"}, "sentence_index": 0, "correct_answer": "死区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份计划有一根死区，需要修改。", "explanation": "这里应该用〈片〉。死区是一片领域，量词“根”用于细长的东西，不能用于“死区”。"}, {"text": "这项新政策在农村还有一条死区，没人关注。", "explanation": "这里应该用〈片〉或〈个〉。死区是一片领域，量词“条”用于长条形事物，不能用于“死区”。"}, {"text": "公司管理中还有一座死区，需要改进。", "explanation": "这里应该用〈片〉或〈个〉。死区是一片领域，量词“座”用于山、楼等大型建筑，不能用于“死区”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bfad034-e6c0-407b-b152-54d3eb16b850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95402, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "死区", "is_correct": true, "explanation": "死区指教育政策影响不到的领域，山区正是这样的地方。"}, {"text": "体育馆", "is_correct": false, "explanation": "语义：体育馆不属于政策的影响领域，“成了……的体育馆”语义不通。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫与“教育政策”无法构成所指关系，句意荒谬。"}, {"text": "火车站", "is_correct": false, "explanation": "搭配：“教育政策的火车站”不成搭配，“山区成了火车站”也与句中语境不符。"}], "explanations": {"死区": "死区指教育政策影响不到的领域，山区正是这样的地方。", "体育馆": "语义：体育馆不属于政策的影响领域，“成了……的体育馆”语义不通。", "小猫": "语义：小猫与“教育政策”无法构成所指关系，句意荒谬。", "火车站": "搭配：“教育政策的火车站”不成搭配，“山区成了火车站”也与句中语境不符。"}, "sentence_index": 6, "correct_answer": "死区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个品牌的广告在小城市是一座死区，没人看。", "explanation": "这里应该用〈片〉。死区是一片领域，量词“座”用于山、楼等大型建筑，不能用于“死区”。"}, {"text": "这个品牌的广告在小城市是一张死区，没人看。", "explanation": "这里应该用〈片〉。死区是一片领域，量词“张”用于平面的东西，不能用于“死区”。"}, {"text": "这个品牌的广告在小城市是一根死区，没人看。", "explanation": "这里应该用〈片〉。死区是一片领域，量词“根”用于细长的东西，不能用于“死区”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bfad034-e6c0-407b-b152-54d3eb16b850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95402, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个法规在基层还有一条死区，需要补充细则。", "corrected_sentence": "这个法规在基层还有一片死区，需要补充细则。", "error_description": "量词错误：“死区”应配量词“片”，写作“一条死区”错，应为“一片死区”。“条”用于长条形事物，不用于这类领域。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bfad034-e6c0-407b-b152-54d3eb16b850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95402, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这一带仍是一座信息死区，没人负责。", "corrected_sentence": "这一带仍是一片信息死区，没人负责。", "error_description": "量词错误：“信息死区”指信息影响不到的领域，应配量词“片”，写作“一座信息死区”错，应为“一片信息死区”。“座”用于山、楼等大型建筑，不用于领域。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bfad034-e6c0-407b-b152-54d3eb16b850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
