INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95405, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "菜完炒了，快来吃吧。", "corrected_sentence": "菜炒完了，快来吃吧。", "error_description": "结果补语位置错误：“炒”在前，结果补语“完”在后，应说“炒完了”，不能说“完炒了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b3da8f-38fb-4b17-bfe6-56ca8c06d98f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
