INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95410, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "经过加工、装瓶或装盒出售的日常饮用奶。", "primary_collocate": null, "pronunciation": "niú nǎi", "ipa": "niou˧˥ nai˨˩˦", "syllable_count": 2, "sentences": [{"text": "我每天早饭都喝一杯牛奶。", "target_word": "牛奶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里的牛奶在冰柜旁边。", "target_word": "牛奶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请帮我买两盒牛奶。", "target_word": "牛奶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这瓶牛奶过期了。", "target_word": "牛奶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他睡觉前喜欢喝热牛奶。", "target_word": "牛奶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在咖啡里加了一点牛奶。", "target_word": "牛奶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种牛奶是用盒子装的。", "target_word": "牛奶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对牛奶过敏，不能喝。", "target_word": "牛奶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牛奶和面包是我常吃的早饭。", "target_word": "牛奶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱里还有半瓶牛奶。", "target_word": "牛奶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一杯牛奶", "label": "量词"}, {"form": "一盒牛奶", "label": "量词"}, {"form": "一瓶牛奶", "label": "量词"}], "register": "中性", "sense_fingerprint": "超市里卖的、日常饮用的加工奶", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13e40e28-eddb-4b26-84f8-93c953de069b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95410, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "牛奶", "is_correct": true, "explanation": "正确。“喝一杯”的对象是可饮用的液体，牛奶正符合。"}, {"text": "木头", "is_correct": false, "explanation": "语义：木头不能喝，“喝一杯木头”不成立。"}, {"text": "米饭", "is_correct": false, "explanation": "搭配：“喝”不搭配米饭，米饭要说“吃”。"}, {"text": "钢笔", "is_correct": false, "explanation": "语义：钢笔是书写工具，不能喝。"}], "explanations": {"牛奶": "正确。“喝一杯”的对象是可饮用的液体，牛奶正符合。", "木头": "语义：木头不能喝，“喝一杯木头”不成立。", "米饭": "搭配：“喝”不搭配米饭，米饭要说“吃”。", "钢笔": "语义：钢笔是书写工具，不能喝。"}, "sentence_index": 0, "correct_answer": "牛奶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一根牛奶。", "explanation": "这里应该用〈瓶〉或〈盒〉。〈根〉用于细长的东西，装牛奶要用容器量词。"}, {"text": "妈妈早上磨了一杯牛奶，给全家做早饭。", "explanation": "这里应该用〈豆浆〉。〈磨〉用于豆子等固体原料，牛奶是现成的液体，不用磨。"}, {"text": "牛奶在草地上吃草。", "explanation": "这里应该用〈牛〉。〈牛奶〉是饮品，不是动物，不能吃草。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d869df1-ec3e-4030-9f24-3c0998b1eb14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95410, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "牛奶", "is_correct": true, "explanation": "正确。牛奶是盒装的液体食品，符合“用盒子装的”描述。"}, {"text": "蒸汽", "is_correct": false, "explanation": "语义：蒸汽是水的气态，不能用盒子装。"}, {"text": "云", "is_correct": false, "explanation": "语义：云是天上的水汽，不能用盒子装。"}, {"text": "阳光", "is_correct": false, "explanation": "搭配：“装”搭配可以装进盒子的东西，阳光不能用盒子装。"}], "explanations": {"牛奶": "正确。牛奶是盒装的液体食品，符合“用盒子装的”描述。", "蒸汽": "语义：蒸汽是水的气态，不能用盒子装。", "云": "语义：云是天上的水汽，不能用盒子装。", "阳光": "搭配：“装”搭配可以装进盒子的东西，阳光不能用盒子装。"}, "sentence_index": 6, "correct_answer": "牛奶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他早饭时咬了一口牛奶，又喝了一口果汁。", "explanation": "这里应该用〈面包〉。〈咬〉用于固体食物，牛奶是液体，不能咬。"}, {"text": "妈妈把牛奶切成薄片，夹进了三明治。", "explanation": "这里应该用〈奶酪〉。〈切成薄片〉用于奶酪这类固体，液体的牛奶不能切。"}, {"text": "我用勺子捏了一大勺牛奶，放进了碗里。", "explanation": "这里应该用〈舀〉。〈捏〉用于可以成团的软物，牛奶是液体，不能捏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d869df1-ec3e-4030-9f24-3c0998b1eb14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95410, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈昨天买了两块牛奶。", "corrected_sentence": "妈妈昨天买了两瓶牛奶。", "error_description": "量词错误：液体的牛奶不能用“块”量。“块”用于有固定形状的块状物。应改为“两瓶牛奶”或“两盒牛奶”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d869df1-ec3e-4030-9f24-3c0998b1eb14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95410, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "冰箱里放着两朵牛奶。", "corrected_sentence": "冰箱里放着两袋牛奶。", "error_description": "量词错误：“朵”用于花朵等，不能用于牛奶。牛奶应说“两袋牛奶”（也可说“两瓶”“两盒”）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d869df1-ec3e-4030-9f24-3c0998b1eb14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
