INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95411, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很喜欢看球赛的人。", "primary_collocate": null, "pronunciation": "qiú mí", "ipa": "tɕʰi̯oʊ˧˥ mi˧˥", "syllable_count": 2, "sentences": [{"text": "我哥哥是个球迷，周末都看球赛。", "target_word": "球迷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今晚的比赛，球迷们都坐在电视前。", "target_word": "球迷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是球迷，一有比赛就不想睡觉。", "target_word": "球迷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球迷都在酒吧里看昨天的球赛。", "target_word": "球迷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不是球迷，所以不知道今天有比赛。", "target_word": "球迷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球迷看到进球，高兴地站起来。", "target_word": "球迷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我邻居是球迷，家里有很大的电视。", "target_word": "球迷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "体育馆里坐满了球迷。", "target_word": "球迷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球迷买了票，想去现场看比赛。", "target_word": "球迷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "世界杯的时候，到处都是球迷。", "target_word": "球迷", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "球迷们", "label": "复数"}, {"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}], "register": "中性", "sense_fingerprint": "很喜欢看球赛的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cbe411f-991a-416c-a28b-6dca83adf8ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95411, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "球迷", "is_correct": true, "explanation": "球迷：指很喜欢看球赛的人，与“周末都看球赛”相符。"}, {"text": "歌迷", "is_correct": false, "explanation": "语义：“歌迷”指喜欢音乐的人，与“看球赛”不符。"}, {"text": "盆栽", "is_correct": false, "explanation": "语义：“盆栽”是植物，不能用来指人。"}, {"text": "球队", "is_correct": false, "explanation": "语义：“球队”是一个集体，“我哥哥”是一个人，不能说他是球队。"}], "explanations": {"球迷": "球迷：指很喜欢看球赛的人，与“周末都看球赛”相符。", "歌迷": "语义：“歌迷”指喜欢音乐的人，与“看球赛”不符。", "盆栽": "语义：“盆栽”是植物，不能用来指人。", "球队": "语义：“球队”是一个集体，“我哥哥”是一个人，不能说他是球队。"}, "sentence_index": 0, "correct_answer": "球迷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我哥哥是一名优秀的球迷，每天都在场上踢球。", "explanation": "这里应该用〈球员〉。球迷是观看比赛的人，不在场上踢球。"}, {"text": "那位球迷负责判罚犯规，场上没人反对。", "explanation": "这里应该用〈裁判〉。球迷不负责判罚，判罚犯规是裁判的工作。"}, {"text": "我昨天遇到一位球迷，他正在给球队安排训练。", "explanation": "这里应该用〈教练〉。球迷是观看比赛的人，不负责给球队安排训练，要用〈教练〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12927d7c-59d1-40f3-ad1f-89500df274f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95411, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "球迷", "is_correct": true, "explanation": "球迷：指很喜欢看球赛的人，与家里有大电视、常看球赛相符。"}, {"text": "书法", "is_correct": false, "explanation": "语义：“书法”是一种艺术，不是人，不能用来说“我邻居是……”。"}, {"text": "雕像", "is_correct": false, "explanation": "语义：“雕像”是物品，不能用来说“我邻居是……”。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：“太阳”不是人，不能用来说“我邻居是……”。"}], "explanations": {"球迷": "球迷：指很喜欢看球赛的人，与家里有大电视、常看球赛相符。", "书法": "语义：“书法”是一种艺术，不是人，不能用来说“我邻居是……”。", "雕像": "语义：“雕像”是物品，不能用来说“我邻居是……”。", "太阳": "语义：“太阳”不是人，不能用来说“我邻居是……”。"}, "sentence_index": 6, "correct_answer": "球迷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是一名出色的球迷，正在比赛场上奔跑。", "explanation": "这里应该用〈运动员〉。球迷是观众，不在场上比赛。"}, {"text": "他是队里的新球迷，比赛时表现很好。", "explanation": "这里应该用〈队员〉。球迷不在队里比赛，“比赛时表现很好”指场上的表现。"}, {"text": "那位球迷在场边为受伤的队员做手术，动作很熟练。", "explanation": "这里应该用〈队医〉。球迷是观众，不是医生，不能为队员做手术，要用〈队医〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12927d7c-59d1-40f3-ad1f-89500df274f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95411, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位忠实地球迷每天都看比赛。", "corrected_sentence": "这位忠实的球迷每天都看比赛。", "error_description": "错误形式：“忠实地球迷”；正确形式：“忠实的球迷”。名词前的修饰语用“的”，“地”用在动词前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12927d7c-59d1-40f3-ad1f-89500df274f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95411, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是一个很热心球迷。", "corrected_sentence": "他是一个很热心的球迷。", "error_description": "错误形式：“很热心球迷”；正确形式：“很热心的球迷”。形容词修饰名词时，中间要加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12927d7c-59d1-40f3-ad1f-89500df274f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
