INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95412, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "热爱球类运动并关注比赛的人。", "primary_collocate": null, "pronunciation": "qiú mí", "ipa": "tɕʰi̯oʊ˧˥ mi˧˥", "syllable_count": 2, "sentences": [{"text": "他是一个真正的球迷，每场比赛都关注。", "target_word": "球迷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位球迷从小就爱打篮球，也爱看比赛。", "target_word": "球迷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球迷们在场外等着球员出来。", "target_word": "球迷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作为球迷，他每天都看体育新闻。", "target_word": "球迷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个球迷收集了很多球星的照片。", "target_word": "球迷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老球迷还记得二十年前的那场比赛。", "target_word": "球迷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球迷们为自己的球队唱歌加油。", "target_word": "球迷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爸爸是个老球迷，常去现场看比赛。", "target_word": "球迷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店专门给球迷卖球衣。", "target_word": "球迷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "许多球迷坐飞机去别的城市看比赛。", "target_word": "球迷", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "球迷们", "label": "复数"}, {"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}], "register": "中性", "sense_fingerprint": "热爱球类运动并关注比赛的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cbe411f-991a-416c-a28b-6dca83adf8ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95412, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "球迷", "is_correct": true, "explanation": "球迷：指热爱球类运动并关注比赛的人，与“每场比赛都关注”相呼应。"}, {"text": "歌迷", "is_correct": false, "explanation": "语义：“歌迷”指喜欢音乐的人，与“每场比赛都关注”不符。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：“厨师”是职业，与“每场比赛都关注”不相关。"}, {"text": "球队", "is_correct": false, "explanation": "语义：“球队”是一个集体，“他”是一个人，不能说他是球队。"}], "explanations": {"球迷": "球迷：指热爱球类运动并关注比赛的人，与“每场比赛都关注”相呼应。", "歌迷": "语义：“歌迷”指喜欢音乐的人，与“每场比赛都关注”不符。", "厨师": "语义：“厨师”是职业，与“每场比赛都关注”不相关。", "球队": "语义：“球队”是一个集体，“他”是一个人，不能说他是球队。"}, "sentence_index": 0, "correct_answer": "球迷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一名优秀的球迷，每天都在训练场上练习。", "explanation": "这里应该用〈球员〉。球迷是观看比赛的人，不在训练场上练习。"}, {"text": "这场比赛的球迷吹响了终场哨，比赛结束了。", "explanation": "这里应该用〈裁判〉。球迷是观看比赛的人，不能吹响终场哨、宣布比赛结束，要用〈裁判〉。"}, {"text": "那位球迷在场边检票，把人都挡在门外。", "explanation": "这里应该用〈检票员〉。球迷是看比赛的人，不负责检票，“检票”要用〈检票员〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12927d7c-59d1-40f3-ad1f-89500df274f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95412, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "球迷", "is_correct": true, "explanation": "球迷：指为球队加油的人，与“为自己的球队唱歌加油”相符。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：“厨师”是职业，与“为自己的球队唱歌加油”无关。"}, {"text": "司机", "is_correct": false, "explanation": "语义：“司机”是职业，与“为自己的球队唱歌加油”无关。"}, {"text": "裁判", "is_correct": false, "explanation": "语义：“裁判”应当公正，不能偏向“自己的球队”。"}], "explanations": {"球迷": "球迷：指为球队加油的人，与“为自己的球队唱歌加油”相符。", "厨师": "语义：“厨师”是职业，与“为自己的球队唱歌加油”无关。", "司机": "语义：“司机”是职业，与“为自己的球队唱歌加油”无关。", "裁判": "语义：“裁判”应当公正，不能偏向“自己的球队”。"}, "sentence_index": 6, "correct_answer": "球迷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位球迷很严格，经常安排训练。", "explanation": "这里应该用〈教练〉。球迷只是观看比赛的人，不能安排训练。"}, {"text": "这位球迷是队里的医生，专门为受伤的队员包扎。", "explanation": "这里应该用〈队医〉。球迷是观众，不会是队里的医生；为队员包扎要说〈队医〉。"}, {"text": "这位球迷每场比赛都带领队友上场，大家都听他的。", "explanation": "这里应该用〈队长〉。球迷是观众，不上场比赛，带领队友上场的是队长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12927d7c-59d1-40f3-ad1f-89500df274f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95412, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两位球迷们在门口等门票。", "corrected_sentence": "两位球迷在门口等门票。", "error_description": "错误形式：“两位球迷们”；正确形式：“两位球迷”。数量词之后不能再加“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12927d7c-59d1-40f3-ad1f-89500df274f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95412, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我妹妹是一个狂热地球迷。", "corrected_sentence": "我妹妹是一个狂热的球迷。", "error_description": "错误形式：“狂热地球迷”；正确形式：“狂热的球迷”。名词前的修饰语用“的”，“地”用在动词前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12927d7c-59d1-40f3-ad1f-89500df274f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
