INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95416, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "目前；现阶段。", "primary_collocate": null, "pronunciation": "dāng xià", "ipa": "tɑŋ˥ ɕja˥˩", "syllable_count": 2, "sentences": [{"text": "当下最要紧的是先把病治好。", "target_word": "当下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当下的天气不太好，我们明天再去吧。", "target_word": "当下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他当下的工作是在银行做客服。", "target_word": "当下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当下很多年轻人喜欢在网上买东西。", "target_word": "当下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "以当下的情况看，我们还不能出发。", "target_word": "当下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当下大家最关心的问题是房价。", "target_word": "当下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司当下没有招人的计划。", "target_word": "当下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "当下的生活比十年前好多了。", "target_word": "当下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你对当下的情况有什么看法？", "target_word": "当下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是当下最受欢迎的手机。", "target_word": "当下", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "目前、现阶段的情况或时期，常修饰情况、问题、生活", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7709e2f0-004d-4e3f-a172-8cd680b047b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95416, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "当下", "is_correct": true, "explanation": "当下：目前、现阶段，与“最要紧”的判断相符。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“最要紧的是”后接事情或问题，天气不是可以“最要紧”的事，不搭配。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是物品，“最要紧的是先把病治好”中不能指它，句子意思不通。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车是交通工具，“最要紧的是”后不能接“汽车”，句子意思不通。"}], "explanations": {"当下": "当下：目前、现阶段，与“最要紧”的判断相符。", "天气": "搭配：“最要紧的是”后接事情或问题，天气不是可以“最要紧”的事，不搭配。", "手机": "语义：手机是物品，“最要紧的是先把病治好”中不能指它，句子意思不通。", "汽车": "语义：汽车是交通工具，“最要紧的是”后不能接“汽车”，句子意思不通。"}, "sentence_index": 0, "correct_answer": "当下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他从小学到大学，当下都很努力。", "explanation": "这里应该用〈一直〉。“当下”指目前或眼前，不能用来概括从小学到大学这样的一段时间。"}, {"text": "去年当下发生了一件大事。", "explanation": "这里应该用〈当时〉。“当下”指目前、现阶段，不能用来指“去年”这样的过去时间；指过去的时候要说当时。"}, {"text": "我们明天当下出发。", "explanation": "“当下”只指目前，不能和“明天”这样的将来时间连用，应说“我们明天出发”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c86e7dfd-757d-49ab-9772-985de72e2145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95416, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "当下", "is_correct": true, "explanation": "当下：目前、现阶段，与“没有招人的计划”的时间状态相符。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫不能制定招人计划，句子意思不通。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能有招人的计划，与句子主语的意义相矛盾。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“计划”要求有行为主体，石头不能作为“有计划”的主语。"}], "explanations": {"当下": "当下：目前、现阶段，与“没有招人的计划”的时间状态相符。", "小猫": "语义：小猫不能制定招人计划，句子意思不通。", "桌子": "语义：桌子是家具，不能有招人的计划，与句子主语的意义相矛盾。", "石头": "搭配：“计划”要求有行为主体，石头不能作为“有计划”的主语。"}, "sentence_index": 6, "correct_answer": "当下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天早上都把当下放进书包。", "explanation": "这里是把“当下”当成“东西、物品”来用，但它是抽象的时间概念，不能放进书包。"}, {"text": "我们把当下的昨天全都忘了。", "explanation": "这里应该用〈当时〉。“当下”指目前，不能修饰“昨天”这样的过去时间，指过去要说当时。"}, {"text": "他曾经当下是一名医生。", "explanation": "这里应该用〈当时〉。“当下”指目前，不能与“曾经”这类指过去的词连用，说过去的情况要用当时。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c86e7dfd-757d-49ab-9772-985de72e2145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95416, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "面对当下地困难，我们要冷静。", "corrected_sentence": "面对当下的困难，我们要冷静。", "error_description": "结构助词错误：“当下”修饰名词“困难”，定语后应用结构助词“的”，不能用“地”（“地”用于动词、形容词前作状语）。应说“当下的困难”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c86e7dfd-757d-49ab-9772-985de72e2145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95416, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想了解当下地市场行情。", "corrected_sentence": "我想了解当下的市场行情。", "error_description": "结构助词错误：“当下”修饰名词“市场行情”时应用结构助词“的”，不能用“地”（“地”用于动词、形容词前作状语）。应说“当下的市场行情”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c86e7dfd-757d-49ab-9772-985de72e2145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
