INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95418, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "真实发生的事情。", "primary_collocate": null, "pronunciation": "zhēn shì", "ipa": "ʈʂən˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "这件真事发生在去年夏天。", "target_word": "真事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "报纸上写的都是真事。", "target_word": "真事", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他把这件真事写成了一本书。", "target_word": "真事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我听过一个真事，很让人难过。", "target_word": "真事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些真事，老人都记得很清楚。", "target_word": "真事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明讲了一件学校里的真事。", "target_word": "真事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在节目里讲了自己的真事。", "target_word": "真事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小城有很多让人感动的真事。", "target_word": "真事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你说的是真事吗？我不太信。", "target_word": "真事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是一件真事，当时很多人都看到了。", "target_word": "真事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一件真事", "label": "量词"}, {"form": "真事儿", "label": "儿化"}], "register": "口语", "sense_fingerprint": "现实中确实发生的事件，常用来讲述或记录", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fada477-7dd1-4bda-82f4-31a16eb79e22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95418, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "真事", "is_correct": true, "explanation": "正确：指现实中确实发生过的事件。"}, {"text": "诊视", "is_correct": false, "explanation": "zhěn（第三声）与 zhēn（第一声）声调不同，意思是医生检查病人。"}, {"text": "诊室", "is_correct": false, "explanation": "zhěn（第三声）与 zhēn（第一声）声调不同，意思是医生给病人看病的房间。"}, {"text": "阵势", "is_correct": false, "explanation": "zhèn（第四声）与 zhēn（第一声）声调不同，意思是阵势。"}], "explanations": {"真事": "正确：指现实中确实发生过的事件。", "诊视": "zhěn（第三声）与 zhēn（第一声）声调不同，意思是医生检查病人。", "诊室": "zhěn（第三声）与 zhēn（第一声）声调不同，意思是医生给病人看病的房间。", "阵势": "zhèn（第四声）与 zhēn（第一声）声调不同，意思是阵势。"}, "sentence_index": null, "correct_answer": "真事"}, "level_3": {"options": [{"text": "真事", "is_correct": true, "explanation": "正确：“真事”指现实中确实发生过的事件，可以有发生的时间。"}, {"text": "幻想", "is_correct": false, "explanation": "语义：幻想只存在于想象中，不会真实地“发生在去年夏天”。"}, {"text": "童话", "is_correct": false, "explanation": "语义：童话是虚构的，不会真实地“发生在去年夏天”。"}, {"text": "梦境", "is_correct": false, "explanation": "语义：梦境不是现实中发生的事，与“真”相矛盾。"}], "explanations": {"真事": "正确：“真事”指现实中确实发生过的事件，可以有发生的时间。", "幻想": "语义：幻想只存在于想象中，不会真实地“发生在去年夏天”。", "童话": "语义：童话是虚构的，不会真实地“发生在去年夏天”。", "梦境": "语义：梦境不是现实中发生的事，与“真”相矛盾。"}, "sentence_index": 0, "correct_answer": "真事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一生都在用这件真事解题。", "explanation": "这里应该用〈公式〉。“解题”用的是公式，“真事”指发生过的事，不能用来解题。"}, {"text": "他编了一个真事，很让人难过。", "explanation": "这里应该用〈故事〉。“编”的是故事，“真事”是确实发生过的事，不能编。"}, {"text": "他出来辟谣，说那些真事都是假的。", "explanation": "这里应该用〈传闻〉。“辟谣”针对的是传闻，“真事”指真实发生过的事，与“都是假的”相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '282b3b7a-c7fc-4917-8b25-1f5d4912721c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95418, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "真事", "is_correct": true, "explanation": "正确：“真事”指自己经历过的真实事件，可以在节目里讲述。"}, {"text": "蛋糕", "is_correct": false, "explanation": "搭配：“讲”的对象不能是“蛋糕”，“讲了自己的蛋糕”不成话。"}, {"text": "皮鞋", "is_correct": false, "explanation": "搭配：“讲”不能与“皮鞋”搭配，句意不通。"}, {"text": "史实", "is_correct": false, "explanation": "语义：“史实”指历史上的事实，不能说是“自己的”经历。"}], "explanations": {"真事": "正确：“真事”指自己经历过的真实事件，可以在节目里讲述。", "蛋糕": "搭配：“讲”的对象不能是“蛋糕”，“讲了自己的蛋糕”不成话。", "皮鞋": "搭配：“讲”不能与“皮鞋”搭配，句意不通。", "史实": "语义：“史实”指历史上的事实，不能说是“自己的”经历。"}, "sentence_index": 6, "correct_answer": "真事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一生都在坚守这件真事。", "explanation": "这里应该用〈信念〉。“坚守”的是信念、原则，“真事”指真实发生过的事，不能坚守。"}, {"text": "这件真事可以用来计算圆的面积。", "explanation": "这里应该用〈公式〉。计算面积用的是公式，“真事”指发生过的事，不能用来计算。"}, {"text": "这件真事是我随口编出来骗他的。", "explanation": "这里应该用〈谎言〉。“编出来骗人”的是谎言，“真事”指真实发生过的事，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '282b3b7a-c7fc-4917-8b25-1f5d4912721c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95418, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本真事后来上了报纸。", "corrected_sentence": "这件真事后来上了报纸。", "error_description": "量词错误：“真事”的量词是“件”，“本”用于书册，应改为“这件真事”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '282b3b7a-c7fc-4917-8b25-1f5d4912721c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95418, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们听了件那真事，都很难过。", "corrected_sentence": "我们听了那件真事，都很难过。", "error_description": "语序错误：指示词“那”应放在量词“件”之前，应说“那件真事”，不能说“件那真事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '282b3b7a-c7fc-4917-8b25-1f5d4912721c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
