INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95420, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人们在社会中为达到某一目的而采取的集体行为。", "primary_collocate": null, "pronunciation": "shè huì xíng dòng", "ipa": "ʂɤ˥˩ xweɪ̯˥˩ ɕiŋ˧˥ tʊŋ˥˩", "syllable_count": 4, "sentences": [{"text": "罢工是一种常见的社会行动。", "target_word": "社会行动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次社会行动得到了很多人的支持。", "target_word": "社会行动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社会行动能让政府听到大家的声音。", "target_word": "社会行动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学者正在研究这次社会行动的原因。", "target_word": "社会行动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保护环境的社会行动越来越多。", "target_word": "社会行动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场社会行动是由学生发起的。", "target_word": "社会行动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一次大型的社会行动需要很多准备。", "target_word": "社会行动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那场社会行动改变了法律。", "target_word": "社会行动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，游行也是一种社会行动。", "target_word": "社会行动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社会行动的目的是让社会变得更好。", "target_word": "社会行动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "社会学中为实现某一目的而采取的集体行为", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e84f4cb-bc76-4322-ba77-d1f9128bfffb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95420, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "社会行动", "is_correct": true, "explanation": "社会行动指为达到某一目的而采取的集体行为，罢工正属于这类行为。"}, {"text": "游戏", "is_correct": false, "explanation": "语义：罢工是劳动者为争取权益而停止工作，不是游戏。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试是检验学习成果的活动，罢工是劳动者停止工作以争取权益，二者不同。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：饮料是可以喝的东西，罢工不能被看作一种饮料。"}], "explanations": {"社会行动": "社会行动指为达到某一目的而采取的集体行为，罢工正属于这类行为。", "游戏": "语义：罢工是劳动者为争取权益而停止工作，不是游戏。", "考试": "语义：考试是检验学习成果的活动，罢工是劳动者停止工作以争取权益，二者不同。", "饮料": "语义：饮料是可以喝的东西，罢工不能被看作一种饮料。"}, "sentence_index": 0, "correct_answer": "社会行动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一个人在公园里晒太阳，这也算是一次社会行动。", "explanation": "这里应该用〈休息〉。社会行动指人们为达到某一目的而采取的集体行为，一个人晒太阳是个人休息，不是集体行为。"}, {"text": "这台洗衣机的社会行动很好，洗得很干净。", "explanation": "这里应该用〈性能〉。社会行动指人们为社会目的而采取的集体行为，洗衣机的洗涤效果属于性能，不能说成社会行动。"}, {"text": "这场社会行动是一场足球比赛，场面很激烈。", "explanation": "这里应该用〈比赛〉。社会行动指为达到社会目的而采取的集体行为，足球比赛是体育竞赛，不属于此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b0cbc1-5c91-41cb-be3a-9ff8c12920a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95420, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "社会行动", "is_correct": true, "explanation": "社会行动指为达到某一目的而采取的集体行为，能够符合“需要很多准备”的大型活动语境。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指人的体型，不是需要很多准备的大型活动。"}, {"text": "手套", "is_correct": false, "explanation": "搭配：手套用“副”计量，不能说“一次大型的手套”。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟是小物件，不是需要很多准备的大型活动。"}], "explanations": {"社会行动": "社会行动指为达到某一目的而采取的集体行为，能够符合“需要很多准备”的大型活动语境。", "身材": "体貌：身材指人的体型，不是需要很多准备的大型活动。", "手套": "搭配：手套用“副”计量，不能说“一次大型的手套”。", "闹钟": "语义：闹钟是小物件，不是需要很多准备的大型活动。"}, "sentence_index": 6, "correct_answer": "社会行动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很懂得社会行动，每天都和同事一起吃午饭。", "explanation": "这里应该用〈社交〉。社会行动指为达到社会目的而采取的集体行为，同事之间吃午饭属于社交，不是这个意思。"}, {"text": "我的社会行动是每个月换一次手机。", "explanation": "这里应该用〈消费〉。社会行动指集体为社会目的而采取的行为，个人换手机属于消费，不能说成社会行动。"}, {"text": "我每天吃饭、睡觉，这些都是社会行动。", "explanation": "这里应该用〈习惯〉。社会行动指集体为达到社会目的而采取的行为，个人每天吃饭、睡觉属于生活习惯，不是这个意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b0cbc1-5c91-41cb-be3a-9ff8c12920a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95420, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人们发起了一本社会行动，要求提高工资。", "corrected_sentence": "工人们发起了一次社会行动，要求提高工资。", "error_description": "量词错误：“本”用于书籍，社会行动应用量词“次”或“场”，应说“一次社会行动”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b0cbc1-5c91-41cb-be3a-9ff8c12920a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95420, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我爷爷年轻时参加着社会行动，后来写了回忆录。", "corrected_sentence": "我爷爷年轻时参加过社会行动，后来写了回忆录。", "error_description": "体标错误：“着”表示动作正在进行或状态持续，“年轻时参加”是过去的经历，应用“过”，说“参加过社会行动”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b0cbc1-5c91-41cb-be3a-9ff8c12920a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
