INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95423, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "说好时间，去见一个人。", "primary_collocate": null, "pronunciation": "yuē jiàn", "ipa": "yɛ˥ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "我约见了一位律师，咨询合同的问题。", "target_word": "约见", "complexity_tier": "T3", "furigana": "yuējiàn", "sentence_source": "generated"}, {"text": "明天上午我约见客户。", "target_word": "约见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想约见王经理谈工作。", "target_word": "约见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者约见了那位专家。", "target_word": "约见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师约见家长，谈孩子的学习。", "target_word": "约见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我已经约见过他两次了。", "target_word": "约见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她约见了一位客户，在咖啡馆谈合作。", "target_word": "约见", "complexity_tier": "T3", "furigana": "yuējiàn", "sentence_source": "generated"}, {"text": "经理约见新同事，了解情况。", "target_word": "约见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们约见的时间是下午三点。", "target_word": "约见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周五你能约见那位律师吗？", "target_word": "约见", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "约见了", "label": "体标"}, {"form": "约见过", "label": "体标"}, {"form": "約見", "label": "繁体"}], "register": "中性", "sense_fingerprint": "说好时间去见某人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23b00b3b-c2c3-4a38-b232-0bb8195a6de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95423, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "约见", "is_correct": true, "explanation": "约见：事先约定时间去见人，与“咨询合同的问题”相符。"}, {"text": "约会", "is_correct": false, "explanation": "语义：约会多指男女之间的见面或约定的相处，与“咨询合同的问题”的语境不符。"}, {"text": "辞退", "is_correct": false, "explanation": "语义：辞退是解雇，与“咨询合同的问题”的语境相反。"}, {"text": "晋见", "is_correct": false, "explanation": "语域：晋见是正式的觐见用语，用于咨询律师的场合不合语域。"}], "explanations": {"约见": "约见：事先约定时间去见人，与“咨询合同的问题”相符。", "约会": "语义：约会多指男女之间的见面或约定的相处，与“咨询合同的问题”的语境不符。", "辞退": "语义：辞退是解雇，与“咨询合同的问题”的语境相反。", "晋见": "语域：晋见是正式的觐见用语，用于咨询律师的场合不合语域。"}, "sentence_index": 0, "correct_answer": "约见"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在路上约见了老同学，大家都很惊讶。", "explanation": "这里应该用〈遇见〉。约见要事先说好时间；偶然碰到老同学不能用“约见”。"}, {"text": "我昨晚约见了去世多年的爷爷，还聊了很久。", "explanation": "这里应该用〈梦见〉。约见要双方事先约定时间见面，已去世的人无法赴约，应说梦见。"}, {"text": "我下午约见了那份合同，准备签字。", "explanation": "这里应该用〈审阅〉。约见的对象只能是人，不能是合同，应说“看合同”或“审阅合同”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a80eb2-dae7-41d8-85ba-45ca7f5997c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95423, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "约见", "is_correct": true, "explanation": "约见：事先约定时间去见人，与“在咖啡馆谈合作”相符。"}, {"text": "打败", "is_correct": false, "explanation": "语义：打败是战胜对方，与“在咖啡馆谈合作”的语境不符。"}, {"text": "训斥", "is_correct": false, "explanation": "语义：训斥是责备，与“谈合作”的语境矛盾。"}, {"text": "拜见", "is_correct": false, "explanation": "语域：拜见是对尊长的敬称用语，用于普通客户不合语域。"}], "explanations": {"约见": "约见：事先约定时间去见人，与“在咖啡馆谈合作”相符。", "打败": "语义：打败是战胜对方，与“在咖啡馆谈合作”的语境不符。", "训斥": "语义：训斥是责备，与“谈合作”的语境矛盾。", "拜见": "语域：拜见是对尊长的敬称用语，用于普通客户不合语域。"}, "sentence_index": 6, "correct_answer": "约见"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "周五你能约见那只狗吗？", "explanation": "这里应该用〈遛〉。约见的对象必须是人，“狗”不能被约见。"}, {"text": "他事先没有约好，却直接跑去约见王经理。", "explanation": "这里应该用〈拜访〉。约见本身要事先约定时间；没有约好就直接上门，应说拜访。"}, {"text": "我昨天约见了去世的外婆，给她带了一束花。", "explanation": "这里应该用〈梦见〉。约见要双方事先约定时间见面，已去世的人无法赴约，应说梦见。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a80eb2-dae7-41d8-85ba-45ca7f5997c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95423, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我下周约见了一位律师，咨询合同的问题。", "corrected_sentence": "我下周约见一位律师，咨询合同的问题。", "error_description": "错误：“约见”后加了“了”，但“下周”表示将来，动作还没有发生，应去掉“了”，说“我下周约见一位律师”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a80eb2-dae7-41d8-85ba-45ca7f5997c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95423, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明天我约见了王总，谈合同。", "corrected_sentence": "明天我约见王总，谈合同。", "error_description": "错误：“约见”后加了“了”，但“明天”表示将来，应去掉“了”，说“明天我约见王总”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a80eb2-dae7-41d8-85ba-45ca7f5997c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
