INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95424, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "事先约定时间会见。", "primary_collocate": null, "pronunciation": "yuē jiàn", "ipa": "yɛ˥ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "市长约见了几位企业代表。", "target_word": "约见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者想约见这位著名作家。", "target_word": "约见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总经理明天约见两家公司的人。", "target_word": "约见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他向秘书提出约见校长。", "target_word": "约见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司约见了新来的客户代表。", "target_word": "约见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "部长约见外国大使，谈合作。", "target_word": "约见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要约见老板，得先和秘书联系。", "target_word": "约见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长约见过几位老师，听他们的想法。", "target_word": "约见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们约见了律师，商量这件事。", "target_word": "约见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察约见了那位证人。", "target_word": "约见", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "约见了", "label": "体标"}, {"form": "约见过", "label": "体标"}, {"form": "約見", "label": "繁体"}], "register": "书面", "sense_fingerprint": "事先约定时间会见某人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23b00b3b-c2c3-4a38-b232-0bb8195a6de2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95424, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "约见", "is_correct": true, "explanation": "约见：事先约定时间去会见，与“几位企业代表”的会见场合相符。"}, {"text": "辞退", "is_correct": false, "explanation": "语义：辞退是解雇，市长不会去解雇企业代表，句子的语境不成立。"}, {"text": "约会", "is_correct": false, "explanation": "语义：约会多指男女之间的相约见面，不用于市长会见企业代表。"}, {"text": "拜见", "is_correct": false, "explanation": "语域：拜见是晚辈或下级对尊长的敬称用语，用于市长会见企业代表不合语域。"}], "explanations": {"约见": "约见：事先约定时间去会见，与“几位企业代表”的会见场合相符。", "辞退": "语义：辞退是解雇，市长不会去解雇企业代表，句子的语境不成立。", "约会": "语义：约会多指男女之间的相约见面，不用于市长会见企业代表。", "拜见": "语域：拜见是晚辈或下级对尊长的敬称用语，用于市长会见企业代表不合语域。"}, "sentence_index": 0, "correct_answer": "约见"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在校门口约见了校长，两人都很意外。", "explanation": "这里应该用〈遇见〉。约见要事先说好时间；偶然在门口碰到校长不能用“约见”。"}, {"text": "他没有提前联系，直接跑去约见校长，把校长吓了一跳。", "explanation": "这里应该用〈拜访〉。约见要事先约定时间，没有提前联系就去约见，应说拜访或直接上门。"}, {"text": "他向秘书提出约见那所学校。", "explanation": "这里应该用〈参观〉。约见的对象只能是人，不能是学校，应说“参观学校”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a80eb2-dae7-41d8-85ba-45ca7f5997c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95424, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "约见", "is_correct": true, "explanation": "约见：事先约定时间去见人，与“先和秘书联系”的程序相符。"}, {"text": "打败", "is_correct": false, "explanation": "语义：打败是战胜对方，与“先和秘书联系”的预约程序无关。"}, {"text": "叫醒", "is_correct": false, "explanation": "语义：叫醒是把睡着的人喊醒，与约见老板的语境不符。"}, {"text": "捐献", "is_correct": false, "explanation": "搭配：“捐献”的对象是财物或机构，不能“捐献”给老板，也不能与“约见”的对象搭配。"}], "explanations": {"约见": "约见：事先约定时间去见人，与“先和秘书联系”的程序相符。", "打败": "语义：打败是战胜对方，与“先和秘书联系”的预约程序无关。", "叫醒": "语义：叫醒是把睡着的人喊醒，与约见老板的语境不符。", "捐献": "搭配：“捐献”的对象是财物或机构，不能“捐献”给老板，也不能与“约见”的对象搭配。"}, "sentence_index": 6, "correct_answer": "约见"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "警察约见了那条狗。", "explanation": "这里应该用〈抓〉。约见的对象必须是人，“狗”不能被约见。"}, {"text": "警察事先没有通知，却直接跑去约见了那位证人。", "explanation": "这里应该用〈拜访〉。约见要事先约定时间，事先没有通知就去约见，应说拜访或直接上门。"}, {"text": "警察在街上约见了那位证人，两人都没料到。", "explanation": "这里应该用〈碰见〉。约见要事先约定，“没料到”的偶然相遇与事先约定相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a80eb2-dae7-41d8-85ba-45ca7f5997c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95424, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "下个月市长约见了几位企业代表。", "corrected_sentence": "下个月市长约见几位企业代表。", "error_description": "错误：“约见”后加了“了”，但“下个月”表示将来，动作还没有发生，应去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a80eb2-dae7-41d8-85ba-45ca7f5997c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95424, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "秘书明天约见了客户，你不用来。", "corrected_sentence": "秘书明天约见客户，你不用来。", "error_description": "错误：“约见”后加了“了”，但“明天”表示将来，应去掉“了”，说“秘书明天约见客户”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58a80eb2-dae7-41d8-85ba-45ca7f5997c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
