INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95425, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "让很多电脑连在一起的本事。", "primary_collocate": null, "pronunciation": "wǎng luò jì shù", "ipa": "uaŋ˨˩ lu̯ɔ˥˩ tɕi˥˩ ʂu˥˩", "syllable_count": 4, "sentences": [{"text": "他有很好的网络技术，会把办公室的电脑连起来。", "target_word": "网络技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我弟弟懂网络技术，能帮你连电脑。", "target_word": "网络技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位工程师的网络技术很强。", "target_word": "网络技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想把几十台电脑连在一起，要有网络技术。", "target_word": "网络技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想学网络技术，以后做工程师。", "target_word": "网络技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王的网络技术很好，大家有问题都找他。", "target_word": "网络技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司招人，要求会网络技术。", "target_word": "网络技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她靠网络技术，让教室里的电脑都能上网。", "target_word": "网络技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小伙子的网络技术是自学的。", "target_word": "网络技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的网络技术这么好，能教教我吗？", "target_word": "网络技术", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "網絡技術", "label": "繁体"}, {"form": "一项网络技术", "label": "量词"}], "register": "中性", "sense_fingerprint": "人掌握的把电脑连起来的本事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a65ce783-209c-496d-8375-67116e6f7c33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95425, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "网络技术", "is_correct": true, "explanation": "“有很好的……，会把电脑连起来”说的是一种本领，网络技术正是人所掌握的这种本领。"}, {"text": "厨艺", "is_correct": false, "explanation": "语义：厨艺指烹饪的本领，与“把办公室的电脑连起来”无关。"}, {"text": "人脉", "is_correct": false, "explanation": "搭配：“会”后接的应是能力，“人脉”是人际关系，不能说“会把电脑连起来”。"}, {"text": "书法", "is_correct": false, "explanation": "语义：书法指写字的艺术，与连接电脑的本领无关。"}], "explanations": {"网络技术": "“有很好的……，会把电脑连起来”说的是一种本领，网络技术正是人所掌握的这种本领。", "厨艺": "语义：厨艺指烹饪的本领，与“把办公室的电脑连起来”无关。", "人脉": "搭配：“会”后接的应是能力，“人脉”是人际关系，不能说“会把电脑连起来”。", "书法": "语义：书法指写字的艺术，与连接电脑的本领无关。"}, "sentence_index": 0, "correct_answer": "网络技术"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的木工网络技术很好，做的椅子很结实。", "explanation": "这里应该用〈手艺〉。网络技术指使电脑联网的本领，不能用来说木工的技艺。"}, {"text": "他有一把网络技术。", "explanation": "这里应该用〈项〉。“把”不用于本领，应说“一项网络技术”。"}, {"text": "我经常去他的网络技术学习。", "explanation": "这里应该用〈学校〉。网络技术是一种本领，不是场所，不能说“去网络技术学习”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '979e2659-c933-4818-bcef-e3cf85849824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95425, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "网络技术", "is_correct": true, "explanation": "“要求会”后接技能，网络技术是招聘中常见的一项技能要求。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“会”后直接接“汽车”不成立，应说“会开汽车”。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是日用品，不是可以掌握的技能。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是疾病，不是技能，“要求会感冒”没有意义。"}], "explanations": {"网络技术": "“要求会”后接技能，网络技术是招聘中常见的一项技能要求。", "汽车": "搭配：“会”后直接接“汽车”不成立，应说“会开汽车”。", "雨伞": "语义：雨伞是日用品，不是可以掌握的技能。", "感冒": "语义：感冒是疾病，不是技能，“要求会感冒”没有意义。"}, "sentence_index": 6, "correct_answer": "网络技术"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌的网络技术很动听。", "explanation": "这里应该用〈旋律〉。网络技术指本领，不能用来形容歌曲的好听；“动听”说的是声音。"}, {"text": "他每天早上都喝一杯网络技术。", "explanation": "这里应该用〈咖啡〉。网络技术是一种本领，不是饮料，不能“喝一杯”。"}, {"text": "他做饭的网络技术很好。", "explanation": "这里应该用〈手艺〉。网络技术指使电脑联网的本领，不能用来说做饭的技艺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '979e2659-c933-4818-bcef-e3cf85849824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95425, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有一只很好的网络技术。", "corrected_sentence": "他有一项很好的网络技术。", "error_description": "量词错误：“网络技术”应搭配“项”，“只”多用于动物，不能说“一只网络技术”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '979e2659-c933-4818-bcef-e3cf85849824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95425, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她学了过网络技术，所以能帮我修电脑。", "corrected_sentence": "她学过网络技术，所以能帮我修电脑。", "error_description": "体标错误：“学过”已表示经历，“了”与“过”不能同用，应说“学过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '979e2659-c933-4818-bcef-e3cf85849824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
