INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95426, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "使计算机互相连接并交换信息的技术。", "primary_collocate": null, "pronunciation": "wǎng luò jì shù", "ipa": "uaŋ˨˩ lu̯ɔ˥˩ tɕi˥˩ ʂu˥˩", "syllable_count": 4, "sentences": [{"text": "网络技术让世界各地的电脑连在一起。", "target_word": "网络技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校开了一门网络技术课。", "target_word": "网络技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在公司做网络技术工作。", "target_word": "网络技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络技术的发展很快。", "target_word": "网络技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的网络技术很先进。", "target_word": "网络技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了网络技术，我们可以马上收发邮件。", "target_word": "网络技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥在大学学的是网络技术。", "target_word": "网络技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络技术越来越好，电脑之间传信息更快了。", "target_word": "网络技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院用网络技术管理病人的信息。", "target_word": "网络技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学好网络技术，才能让电脑互相连接。", "target_word": "网络技术", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "網絡技術", "label": "繁体"}, {"form": "一项网络技术", "label": "量词"}], "register": "中性", "sense_fingerprint": "计算机联网并交换信息的技术", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a65ce783-209c-496d-8375-67116e6f7c33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95426, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "网络技术", "is_correct": true, "explanation": "网络技术指使计算机互相连接的技术，可以作“让”的施事，使世界各地的电脑连在一起。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视用来播放节目，不能让世界各地的电脑连在一起。"}, {"text": "食品", "is_correct": false, "explanation": "语义：食品与电脑连接毫无关系，句子说不通。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车是交通工具，不能让世界各地的电脑连在一起，句子说不通。"}], "explanations": {"网络技术": "网络技术指使计算机互相连接的技术，可以作“让”的施事，使世界各地的电脑连在一起。", "电视": "语义：电视用来播放节目，不能让世界各地的电脑连在一起。", "食品": "语义：食品与电脑连接毫无关系，句子说不通。", "汽车": "语义：汽车是交通工具，不能让世界各地的电脑连在一起，句子说不通。"}, "sentence_index": 0, "correct_answer": "网络技术"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的修车网络技术很强。", "explanation": "这里应该用〈技能〉。网络技术指使计算机联网的技术，不能用来形容修车的本领。"}, {"text": "公司引进了一把网络技术。", "explanation": "这里应该用〈项〉。“把”用于有柄的器具，技术应说“一项网络技术”。"}, {"text": "我经常去网络技术打游戏。", "explanation": "这里应该用〈网吧〉。网络技术是一种技术，不是场所，不能说“去网络技术”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '979e2659-c933-4818-bcef-e3cf85849824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95426, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "网络技术", "is_correct": true, "explanation": "“学的是”后接专业或学科，网络技术是大学里可以学的专业。"}, {"text": "白菜", "is_correct": false, "explanation": "语义：白菜是蔬菜，不是大学里学习的专业，句子说不通。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是日用品，不是可以在大学学习的内容。"}, {"text": "感冒", "is_correct": false, "explanation": "搭配：“学”的宾语应是知识或技能，“感冒”是疾病，不能说“学的是感冒”。"}], "explanations": {"网络技术": "“学的是”后接专业或学科，网络技术是大学里可以学的专业。", "白菜": "语义：白菜是蔬菜，不是大学里学习的专业，句子说不通。", "雨伞": "语义：雨伞是日用品，不是可以在大学学习的内容。", "感冒": "搭配：“学”的宾语应是知识或技能，“感冒”是疾病，不能说“学的是感冒”。"}, "sentence_index": 6, "correct_answer": "网络技术"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌的网络技术很动听。", "explanation": "这里应该用〈旋律〉。网络技术指使计算机联网的技术，不能用来形容歌曲好听；“动听”说的是声音。"}, {"text": "我常去这个网络技术看新闻。", "explanation": "这里应该用〈网站〉。网络技术是一门技术，不是可以浏览内容的地方。"}, {"text": "他每天早上都喝一杯网络技术。", "explanation": "这里应该用〈咖啡〉。网络技术是一门技术，不是饮料，不能“喝一杯”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '979e2659-c933-4818-bcef-e3cf85849824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95426, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想学一只网络技术。", "corrected_sentence": "我想学一门网络技术。", "error_description": "量词错误：“只”多用于动物，“技术”应搭配“门”或“项”。错误形式为“一只网络技术”，正确形式为“一门网络技术”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '979e2659-c933-4818-bcef-e3cf85849824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95426, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我弟弟学了过网络技术，现在在一家公司工作。", "corrected_sentence": "我弟弟学过网络技术，现在在一家公司工作。", "error_description": "体标错误：“学过”已表示经历，“了”与“过”不能同用，应说“学过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '979e2659-c933-4818-bcef-e3cf85849824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
