INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95429, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人和动物身体前面，装着吃的东西的地方。", "primary_collocate": null, "pronunciation": "dù zi", "ipa": "tu˥˩ tsɨ", "syllable_count": 2, "sentences": [{"text": "我的肚子饿了，想吃饭。", "target_word": "肚子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃太多的话，肚子会不舒服。", "target_word": "肚子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他早上没吃东西，肚子一直叫。", "target_word": "肚子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子吃了冷的东西，肚子疼。", "target_word": "肚子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我中午吃了两碗饭，肚子很饱。", "target_word": "肚子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗吃饱了，肚子圆圆的。", "target_word": "肚子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空着肚子不能喝酒。", "target_word": "肚子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喝点热汤，肚子里会舒服一些。", "target_word": "肚子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只猫肚子饿，一直在门口叫。", "target_word": "肚子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的肚子咕咕叫，大家都听到了。", "target_word": "肚子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "小肚子", "label": "复合"}, {"form": "大肚子", "label": "复合"}], "register": "口语", "sense_fingerprint": "装食物的肚子，饿、饱、疼等感觉所在", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dc02faa-5315-4ba7-927d-a2130aa5300f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95429, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "肚子", "is_correct": true, "explanation": "“肚子”（dù zi）指人或动物装食物的腹部，也是饥饿、疼痛感觉所在的部位。"}, {"text": "兔子", "is_correct": false, "explanation": "tù（第四声）与 dù（第四声）声母不同（t 与 d），意思是兔子。"}, {"text": "裤子", "is_correct": false, "explanation": "kù（第四声）与 dù（第四声）声母不同（k 与 d），意思是裤子。"}, {"text": "路子", "is_correct": false, "explanation": "lù（第四声）与 dù（第四声）声母不同（l 与 d），意思是路子。"}], "explanations": {"肚子": "“肚子”（dù zi）指人或动物装食物的腹部，也是饥饿、疼痛感觉所在的部位。", "兔子": "tù（第四声）与 dù（第四声）声母不同（t 与 d），意思是兔子。", "裤子": "kù（第四声）与 dù（第四声）声母不同（k 与 d），意思是裤子。", "路子": "lù（第四声）与 dù（第四声）声母不同（l 与 d），意思是路子。"}, "sentence_index": null, "correct_answer": "肚子"}, "level_3": {"options": [{"text": "肚子", "is_correct": true, "explanation": "“肚子”指装食物的腹部，与“饿了，想吃饭”的语境相符。"}, {"text": "脑袋", "is_correct": false, "explanation": "语义：脑袋不会饿，“饿了，想吃饭”说的是胃肠的感受。"}, {"text": "手", "is_correct": false, "explanation": "搭配：“饿”只用于人或胃肠的感受，不能说手饿了。"}, {"text": "耳朵", "is_correct": false, "explanation": "搭配：“饿”不用于耳朵，耳朵没有饥饿的感觉。"}], "explanations": {"肚子": "“肚子”指装食物的腹部，与“饿了，想吃饭”的语境相符。", "脑袋": "语义：脑袋不会饿，“饿了，想吃饭”说的是胃肠的感受。", "手": "搭配：“饿”只用于人或胃肠的感受，不能说手饿了。", "耳朵": "搭配：“饿”不用于耳朵，耳朵没有饥饿的感觉。"}, "sentence_index": 0, "correct_answer": "肚子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他最近没有肚子，一口饭都不想吃。", "explanation": "这里应该用〈胃口〉。胃口指食欲，“肚子”指身体前面装食物的部位，不能用来表示没有食欲。"}, {"text": "他的肚子很重，特别喜欢吃辣的东西。", "explanation": "这里应该用〈口味〉。口味指对味道的喜好，“肚子”不能用来表示喜欢什么味道。"}, {"text": "他说话的肚子很小，大家都听不清。", "explanation": "这里应该用〈声音〉。“小”形容声音弱时说声音小，“肚子”是身体部位，不能用来形容说话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19a3c267-07e1-44c6-91fc-59e7512c6fb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95429, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "肚子", "is_correct": true, "explanation": "“肚子”（dù zi）指人或动物装食物的腹部，也是饥饿、疼痛感觉所在的部位。"}, {"text": "柱子", "is_correct": false, "explanation": "zhù（第四声）与 dù（第四声）声母不同（zh 与 d），意思是柱子。"}, {"text": "铺子", "is_correct": false, "explanation": "pù（第四声）与 dù（第四声）声母不同（p 与 d），意思是商店。"}, {"text": "豆子", "is_correct": false, "explanation": "dòu（第四声）与 dù（第四声）韵母不同（ou 与 u），意思是豆子。"}, {"text": "独子", "is_correct": false, "explanation": "dú（第二声）与 dù（第四声）声母韵母相同、只差声调，意思是独生的儿子。"}], "explanations": {"肚子": "“肚子”（dù zi）指人或动物装食物的腹部，也是饥饿、疼痛感觉所在的部位。", "柱子": "zhù（第四声）与 dù（第四声）声母不同（zh 与 d），意思是柱子。", "铺子": "pù（第四声）与 dù（第四声）声母不同（p 与 d），意思是商店。", "豆子": "dòu（第四声）与 dù（第四声）韵母不同（ou 与 u），意思是豆子。", "独子": "dú（第二声）与 dù（第四声）声母韵母相同、只差声调，意思是独生的儿子。"}, "sentence_index": null, "correct_answer": "肚子"}, "level_3": {"options": [{"text": "肚子", "is_correct": true, "explanation": "“肚子”指装食物的腹部，“空着肚子”指没有吃东西，与“不能喝酒”的语境相符。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不会空着喝酒，句意说的是人的身体状态。"}, {"text": "肩膀", "is_correct": false, "explanation": "搭配：“空着”不用来形容肩膀，肩膀不能说空着。"}, {"text": "膝盖", "is_correct": false, "explanation": "语义：膝盖不能喝酒，与句中“不能喝酒”的语境不符。"}], "explanations": {"肚子": "“肚子”指装食物的腹部，“空着肚子”指没有吃东西，与“不能喝酒”的语境相符。", "书包": "语义：书包不会空着喝酒，句意说的是人的身体状态。", "肩膀": "搭配：“空着”不用来形容肩膀，肩膀不能说空着。", "膝盖": "语义：膝盖不能喝酒，与句中“不能喝酒”的语境不符。"}, "sentence_index": 6, "correct_answer": "肚子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他感冒了，肚子哑了。", "explanation": "这里应该用〈嗓子〉。“哑”形容嗓音发不出来，只能说嗓子哑，不能说肚子哑。"}, {"text": "他哭得厉害，肚子都红了。", "explanation": "这里应该用〈眼睛〉。“红”形容眼睛哭红，不能用来形容肚子。"}, {"text": "他一夜之间肚子全白了。", "explanation": "这里应该用〈头发〉。“白”形容头发变白，不能用来形容肚子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19a3c267-07e1-44c6-91fc-59e7512c6fb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95429, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子吃了冷的东西，肚子得疼很厉害。", "corrected_sentence": "孩子吃了冷的东西，肚子疼得很厉害。", "error_description": "错误：“得疼”。“得”要放在动词或形容词后面引出补语，不能放在“疼”前面，应说“肚子疼得很厉害”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19a3c267-07e1-44c6-91fc-59e7512c6fb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95429, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他晚上没吃饭，肚子饿睡不着。", "corrected_sentence": "他晚上没吃饭，肚子饿得睡不着。", "error_description": "错误：“饿睡不着”。“饿”后面要用“得”引出程度补语，应说“饿得睡不着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19a3c267-07e1-44c6-91fc-59e7512c6fb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
