INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95430, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人或动物躯干中腹部的部分。", "primary_collocate": null, "pronunciation": "dù zi", "ipa": "tu˥˩ tsɨ", "syllable_count": 2, "sentences": [{"text": "他最近胖了，肚子变大了。", "target_word": "肚子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生按了按我的肚子，问我疼不疼。", "target_word": "肚子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她怀孕了，肚子越来越大。", "target_word": "肚子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天做运动，想减掉肚子上的肉。", "target_word": "肚子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩躺在床上，肚子一上一下地动。", "target_word": "肚子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我趴在地上，肚子贴着地。", "target_word": "肚子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条裤子太小，肚子有点紧。", "target_word": "肚子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸的肚子又圆又大。", "target_word": "肚子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游泳的时候，水只到我的肚子。", "target_word": "肚子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只青蛙的肚子是白色的。", "target_word": "肚子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "小肚子", "label": "复合"}, {"form": "大肚子", "label": "复合"}], "register": "口语", "sense_fingerprint": "身体腹部的外形和位置，如大小、胖瘦", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dc02faa-5315-4ba7-927d-a2130aa5300f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95430, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "肚子", "is_correct": true, "explanation": "“肚子”（dù zi）指人或动物躯干中腹部的部分，即身体前面的外形。"}, {"text": "豆子", "is_correct": false, "explanation": "dòu（第四声）与 dù（第四声）韵母不同（ou 与 u），意思是豆子。"}, {"text": "铺子", "is_correct": false, "explanation": "pù（第四声）与 dù（第四声）声母不同（p 与 d），意思是商店。"}, {"text": "兔子", "is_correct": false, "explanation": "tù（第四声）与 dù（第四声）声母不同（t 与 d），意思是兔子。"}], "explanations": {"肚子": "“肚子”（dù zi）指人或动物躯干中腹部的部分，即身体前面的外形。", "豆子": "dòu（第四声）与 dù（第四声）韵母不同（ou 与 u），意思是豆子。", "铺子": "pù（第四声）与 dù（第四声）声母不同（p 与 d），意思是商店。", "兔子": "tù（第四声）与 dù（第四声）声母不同（t 与 d），意思是兔子。"}, "sentence_index": null, "correct_answer": "肚子"}, "level_3": {"options": [{"text": "肚子", "is_correct": true, "explanation": "“肚子”指腹部的外形，“胖了，肚子变大了”说的正是腹部变大，与语境相符。"}, {"text": "头发", "is_correct": false, "explanation": "语义：头发不会随体重增加而变大，与“胖了”的语境不符。"}, {"text": "眉毛", "is_correct": false, "explanation": "语义：眉毛不会因为胖而变大，与句意不符。"}, {"text": "成绩", "is_correct": false, "explanation": "搭配：“变大”不用来形容成绩，成绩一般说提高或下降。"}], "explanations": {"肚子": "“肚子”指腹部的外形，“胖了，肚子变大了”说的正是腹部变大，与语境相符。", "头发": "语义：头发不会随体重增加而变大，与“胖了”的语境不符。", "眉毛": "语义：眉毛不会因为胖而变大，与句意不符。", "成绩": "搭配：“变大”不用来形容成绩，成绩一般说提高或下降。"}, "sentence_index": 0, "correct_answer": "肚子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的肚子很细，穿什么衣服都好看。", "explanation": "这里应该用〈腰〉。腰指身体中部两侧较细的部位，形容细要说腰细，“肚子”指腹部，不能说肚子细。"}, {"text": "他的肚子很长，跑得很快。", "explanation": "这里应该用〈腿〉。腿指身体下部用来走路的部位，形容长短和跑步要用腿，不能用肚子。"}, {"text": "他感冒了，肚子哑了。", "explanation": "这里应该用〈嗓子〉。“哑”形容嗓音发不出来，不能用来形容肚子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19a3c267-07e1-44c6-91fc-59e7512c6fb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95430, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "肚子", "is_correct": true, "explanation": "“肚子”（dù zi）指人或动物躯干中腹部的部分，即身体前面的外形。"}, {"text": "路子", "is_correct": false, "explanation": "lù（第四声）与 dù（第四声）声母不同（l 与 d），意思是路子。"}, {"text": "柱子", "is_correct": false, "explanation": "zhù（第四声）与 dù（第四声）声母不同（zh 与 d），意思是柱子。"}, {"text": "独子", "is_correct": false, "explanation": "dú（第二声）与 dù（第四声）声母韵母相同、只差声调，意思是独生的儿子。"}, {"text": "裤子", "is_correct": false, "explanation": "kù（第四声）与 dù（第四声）声母不同（k 与 d），意思是裤子。"}], "explanations": {"肚子": "“肚子”（dù zi）指人或动物躯干中腹部的部分，即身体前面的外形。", "路子": "lù（第四声）与 dù（第四声）声母不同（l 与 d），意思是路子。", "柱子": "zhù（第四声）与 dù（第四声）声母不同（zh 与 d），意思是柱子。", "独子": "dú（第二声）与 dù（第四声）声母韵母相同、只差声调，意思是独生的儿子。", "裤子": "kù（第四声）与 dù（第四声）声母不同（k 与 d），意思是裤子。"}, "sentence_index": null, "correct_answer": "肚子"}, "level_3": {"options": [{"text": "肚子", "is_correct": true, "explanation": "“肚子”指腹部，“裤子太小，肚子有点紧”说的是腹部被裤子勒紧，与语境相符。"}, {"text": "脖子", "is_correct": false, "explanation": "语义：裤子不会勒紧脖子，句意说的是裤子太小。"}, {"text": "手腕", "is_correct": false, "explanation": "语义：这里说的是裤子太小，手腕与裤子无关，句意不通。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：“紧”不用来形容眼睛，眼睛不能说有点紧。"}], "explanations": {"肚子": "“肚子”指腹部，“裤子太小，肚子有点紧”说的是腹部被裤子勒紧，与语境相符。", "脖子": "语义：裤子不会勒紧脖子，句意说的是裤子太小。", "手腕": "语义：这里说的是裤子太小，手腕与裤子无关，句意不通。", "眼睛": "搭配：“紧”不用来形容眼睛，眼睛不能说有点紧。"}, "sentence_index": 6, "correct_answer": "肚子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她听到消息，肚子都红了。", "explanation": "这里应该用〈耳朵〉。“红”形容因害羞或激动而泛红的耳朵，不用来形容肚子。"}, {"text": "他笑的时候，肚子很整齐，大家都夸他。", "explanation": "这里应该用〈牙齿〉。“整齐”多形容牙齿排列规整，不能用来形容肚子。"}, {"text": "他感冒了，肚子堵住了，一直流鼻涕。", "explanation": "这里应该用〈鼻子〉。感冒时鼻子堵住、流鼻涕，“肚子”是腹部，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19a3c267-07e1-44c6-91fc-59e7512c6fb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95430, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的肚子大得起来了。", "corrected_sentence": "他的肚子大起来了。", "error_description": "错误：“大得起来”。“得”不能插在形容词“大”和趋向补语“起来”之间，应去掉“得”，说“大起来了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19a3c267-07e1-44c6-91fc-59e7512c6fb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95430, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他吃得太饱，肚子鼓了下来。", "corrected_sentence": "他吃得太饱，肚子鼓了起来。", "error_description": "错误：“鼓了下来”。“鼓”表示向外膨胀，应用趋向补语“起来”，说“鼓了起来”，不能用“下来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19a3c267-07e1-44c6-91fc-59e7512c6fb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
