INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95434, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "游览参观名胜、风景。", "primary_collocate": null, "pronunciation": "guān guāng", "ipa": "kwan˥ kwɑŋ˥", "syllable_count": 2, "sentences": [{"text": "游客们正在长城观光。", "target_word": "观光", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "外国客人到故宫观光，还拍了很多照片。", "target_word": "观光", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个古城每年有很多人来观光。", "target_word": "观光", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市长陪着客人观光了几个名胜。", "target_word": "观光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们来西安观光，参观了兵马俑。", "target_word": "观光", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "旅行团明天上午去西湖观光。", "target_word": "观光", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们在导游带领下观光了整座古城。", "target_word": "观光", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "来北京观光的人，都想去看看天安门。", "target_word": "观光", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座山有很多名胜，吸引了不少人来观光。", "target_word": "观光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他退休以后，到各地的名胜观光。", "target_word": "观光", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "观光了", "label": "体标"}, {"form": "观光团", "label": "复合"}, {"form": "觀光", "label": "繁体"}], "register": "中性", "sense_fingerprint": "游览并参观名胜古迹等著名景点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fada477-7dd1-4bda-82f4-31a16eb79e22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95434, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "观光", "is_correct": true, "explanation": "正确：“观光”指游览名胜、风景，与“游客们正在长城”相符。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：长城上不能游泳，与游客在长城的游览场景不合。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与游客在长城游览的语境不符。"}, {"text": "驾驶", "is_correct": false, "explanation": "配价：“驾驶”需要带宾语（如车辆），单说“长城驾驶”不成立。"}], "explanations": {"观光": "正确：“观光”指游览名胜、风景，与“游客们正在长城”相符。", "游泳": "语义：长城上不能游泳，与游客在长城的游览场景不合。", "睡觉": "语义：“睡觉”与游客在长城游览的语境不符。", "驾驶": "配价：“驾驶”需要带宾语（如车辆），单说“长城驾驶”不成立。"}, "sentence_index": 0, "correct_answer": "观光"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "市长去灾区观光了一天。", "explanation": "这里应该用〈视察〉。“观光”是为玩看风景，去灾区检查工作要用视察。"}, {"text": "市长观光了开幕式。", "explanation": "这里应该用〈参加〉。“观光”的对象是风景名胜，参加仪式要用参加。"}, {"text": "市长在机场观光客人。", "explanation": "这里应该用〈迎接〉。“观光”不能带人作宾语，迎接客人要用迎接。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '282b3b7a-c7fc-4917-8b25-1f5d4912721c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95434, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "观光", "is_correct": true, "explanation": "正确：“观光”指游览名胜古迹，与“在导游带领下”相符。"}, {"text": "攻占", "is_correct": false, "explanation": "语义：“攻占”是军事行动，与导游带领的游览相矛盾。"}, {"text": "修建", "is_correct": false, "explanation": "语义：“修建”是建造，与“在导游带领下”的游览不符。"}, {"text": "装修", "is_correct": false, "explanation": "语义：装修是对房屋做装饰，不是游览，在导游带领下不能“装修”古城。"}], "explanations": {"观光": "正确：“观光”指游览名胜古迹，与“在导游带领下”相符。", "攻占": "语义：“攻占”是军事行动，与导游带领的游览相矛盾。", "修建": "语义：“修建”是建造，与“在导游带领下”的游览不符。", "装修": "语义：装修是对房屋做装饰，不是游览，在导游带领下不能“装修”古城。"}, "sentence_index": 6, "correct_answer": "观光"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司派他去非洲观光了一年。", "explanation": "这里应该用〈考察〉。“观光”是为游玩，考察是为调查研究。"}, {"text": "孩子们在教室里观光。", "explanation": "这里应该用〈上课〉。“观光”是游览风景，在教室里学习应该用上课。"}, {"text": "他每天在公司观光。", "explanation": "这里应该用〈办公〉。“观光”是游玩看风景，在公司工作要用办公。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '282b3b7a-c7fc-4917-8b25-1f5d4912721c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95434, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "上个月我们去苏州观光着。", "corrected_sentence": "上个月我们去苏州观光了。", "error_description": "体标错误：“上个月”表示已完成的事，应用“了”，不能用表示持续的“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '282b3b7a-c7fc-4917-8b25-1f5d4912721c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95434, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们颐和园观光了一上午。", "corrected_sentence": "我们在颐和园观光了一上午。", "error_description": "介词缺失：表示处所的“在”不能省略，应说“在颐和园观光”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '282b3b7a-c7fc-4917-8b25-1f5d4912721c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95435, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82e5dd3c-c450-4323-b6e3-d14b153be005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95435, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82e5dd3c-c450-4323-b6e3-d14b153be005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95435, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对要进门的人说，请你走进来。", "primary_collocate": null, "pronunciation": "qǐng jìn", "ipa": "tɕʰiŋ˨˩˦ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "有人敲门，老师说：“请进！”", "target_word": "请进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“请进，门没有锁。”", "target_word": "请进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到敲门声，他大声说：“请进。”", "target_word": "请进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理在里面说：“请进，请坐。”", "target_word": "请进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我敲了门，里面的人说：“请进。”", "target_word": "请进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“请进，请进，不用换鞋。”", "target_word": "请进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门开着，王医生对我说：“请进。”", "target_word": "请进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她站在门口笑着说：“欢迎，请进！”", "target_word": "请进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“谁呀？请进！”奶奶在屋里喊。", "target_word": "请进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他敲门后，听到一声“请进”，就推门进去了。", "target_word": "请进", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "请进来", "label": "复合"}, {"form": "请进去", "label": "复合"}], "register": "中性", "sense_fingerprint": "对门外要进来的人说的招呼语：请你进来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f204b10a-c94b-4c6b-a243-043a303755e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95435, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "请进", "is_correct": true, "explanation": "请进 qǐng jìn：对门外要进来的人说的招呼语，正确答案。"}, {"text": "亲近", "is_correct": false, "explanation": "亲近 qīnjìn 的第一音节韵母为 -in、声调为第一声，与请进的 qǐng（-ng，第三声）不同，意思是关系密切。"}, {"text": "倾尽", "is_correct": false, "explanation": "倾尽 qīngjìn 只有第一音节声调不同（qīng 第一声，qǐng 第三声），意思是用尽全部。"}, {"text": "精进", "is_correct": false, "explanation": "精进 jīngjìn 的声母为 j（请进为 q），第一音节声调也不同，意思是努力上进。"}, {"text": "请见", "is_correct": false, "explanation": "请见 qǐngjiàn 第二音节韵母为 -ian（请进为 -in），意思是请求接见，也用于「请见附件」。"}], "explanations": {"请进": "请进 qǐng jìn：对门外要进来的人说的招呼语，正确答案。", "亲近": "亲近 qīnjìn 的第一音节韵母为 -in、声调为第一声，与请进的 qǐng（-ng，第三声）不同，意思是关系密切。", "倾尽": "倾尽 qīngjìn 只有第一音节声调不同（qīng 第一声，qǐng 第三声），意思是用尽全部。", "精进": "精进 jīngjìn 的声母为 j（请进为 q），第一音节声调也不同，意思是努力上进。", "请见": "请见 qǐngjiàn 第二音节韵母为 -ian（请进为 -in），意思是请求接见，也用于「请见附件」。"}, "sentence_index": null, "correct_answer": "请进"}, "level_3": {"options": [{"text": "请进", "is_correct": true, "explanation": "请进：对门外要进来的人说的招呼语，符合有人敲门的语境。"}, {"text": "请坐", "is_correct": false, "explanation": "语义：敲门后应先请人进门，请坐要在进门后才说，与敲门的语境冲突。"}, {"text": "请出去", "is_correct": false, "explanation": "语义：「请出去」是赶人离开，与对敲门人的礼貌招呼相矛盾。"}, {"text": "请回", "is_correct": false, "explanation": "搭配：「请回」多指请人返回，不接在敲门之后作招呼语。"}], "explanations": {"请进": "请进：对门外要进来的人说的招呼语，符合有人敲门的语境。", "请坐": "语义：敲门后应先请人进门，请坐要在进门后才说，与敲门的语境冲突。", "请出去": "语义：「请出去」是赶人离开，与对敲门人的礼貌招呼相矛盾。", "请回": "搭配：「请回」多指请人返回，不接在敲门之后作招呼语。"}, "sentence_index": 0, "correct_answer": "请进"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他已经走进办公室了，我还在门口对他说：“请进。”", "explanation": "这里应该用〈请坐〉。请进是门外的人还没进来时招呼他进门，人已在屋里就不说请进。"}, {"text": "客人要走了，我对他说：“请进。”", "explanation": "这里应该用〈请慢走〉。请进是招呼人进来，客人离开时说请慢走。"}, {"text": "司机打开车门，对乘客说：“请进。”", "explanation": "这里应该用〈请上车〉。请进指请人进入房间或院子，招呼乘客上车要说请上车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82e5dd3c-c450-4323-b6e3-d14b153be005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95435, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "请进", "is_correct": true, "explanation": "请进：对门外要进来的人说的招呼语，符合门开着、王医生请我进屋的语境。"}, {"text": "请开门", "is_correct": false, "explanation": "语义：门已经开着，再请人开门与语境矛盾。"}, {"text": "请上车", "is_correct": false, "explanation": "搭配：「上车」用于车辆，不能用于进屋。"}, {"text": "请退后", "is_correct": false, "explanation": "语义：「请退后」是叫人往后站，与请人进屋的招呼相矛盾。"}], "explanations": {"请进": "请进：对门外要进来的人说的招呼语，符合门开着、王医生请我进屋的语境。", "请开门": "语义：门已经开着，再请人开门与语境矛盾。", "请上车": "搭配：「上车」用于车辆，不能用于进屋。", "请退后": "语义：「请退后」是叫人往后站，与请人进屋的招呼相矛盾。"}, "sentence_index": 6, "correct_answer": "请进"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "还没有人敲门，他就大声说：“请进。”", "explanation": "这里应该用〈请稍等〉。请进要等有人敲门或来人时才说，没人来就说请进不合常理。"}, {"text": "我到了老同学家门口，对他说：“请进。”", "explanation": "这里应该用〈打扰了〉。请进是主人请客人进门时说的，客人到门口不能对主人说请进。"}, {"text": "孩子蹦蹦跳跳地跑出门，我说：“请进。”", "explanation": "这里应该用〈慢走〉。请进是请人进来，人正往外走时不说请进。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82e5dd3c-c450-4323-b6e3-d14b153be005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95435, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "听到敲门声，老板说：“请进了吧。”", "corrected_sentence": "听到敲门声，老板说：“请进吧。”", "error_description": "错误：「请进了吧」；正确：「请进吧」。招呼别人进来是祈使语气，不能加「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82e5dd3c-c450-4323-b6e3-d14b153be005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95435, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "客人到了，他说：“请进着吧。”", "corrected_sentence": "客人到了，他说：“请进吧。”", "error_description": "错误：「请进着吧」；正确：「请进吧」。招呼别人进来是一次性的祈使，不能加表示持续的「着」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82e5dd3c-c450-4323-b6e3-d14b153be005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
