INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95436, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "客气地请人进入。", "primary_collocate": null, "pronunciation": "qǐng jìn", "ipa": "tɕʰiŋ˨˩˦ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "王经理把客人请进了会议室。", "target_word": "请进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打开门，客气地把老师请进屋里。", "target_word": "请进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主人笑着把我们请进客厅。", "target_word": "请进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "服务员把客人请进了包间。", "target_word": "请进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长亲自出来，把家长请进办公室。", "target_word": "请进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈开门，把邻居请进家里坐。", "target_word": "请进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口的保安把我请进了大楼。", "target_word": "请进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他热情地把王老师请进了家门。", "target_word": "请进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把远道而来的亲戚请进了新家。", "target_word": "请进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板把客人请进茶室，给他倒了茶。", "target_word": "请进", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "请进来", "label": "复合"}, {"form": "请进去", "label": "复合"}], "register": "中性", "sense_fingerprint": "主人客气地邀请客人进入屋内或房间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f204b10a-c94b-4c6b-a243-043a303755e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95436, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "请进", "is_correct": true, "explanation": "请进 qǐng jìn：客气地请人进入，正确答案。"}, {"text": "亲近", "is_correct": false, "explanation": "亲近 qīnjìn 的第一音节韵母为 -in、声调为第一声，与请进的 qǐng（-ng，第三声）不同，意思是关系密切。"}, {"text": "倾尽", "is_correct": false, "explanation": "倾尽 qīngjìn 只有第一音节声调不同（qīng 第一声，qǐng 第三声），意思是用尽全部。"}, {"text": "精进", "is_correct": false, "explanation": "精进 jīngjìn 的声母为 j（请进为 q），第一音节声调也不同，意思是努力上进。"}, {"text": "请见", "is_correct": false, "explanation": "请见 qǐngjiàn 第二音节韵母为 -ian（请进为 -in），意思是请求接见，也用于「请见附件」。"}], "explanations": {"请进": "请进 qǐng jìn：客气地请人进入，正确答案。", "亲近": "亲近 qīnjìn 的第一音节韵母为 -in、声调为第一声，与请进的 qǐng（-ng，第三声）不同，意思是关系密切。", "倾尽": "倾尽 qīngjìn 只有第一音节声调不同（qīng 第一声，qǐng 第三声），意思是用尽全部。", "精进": "精进 jīngjìn 的声母为 j（请进为 q），第一音节声调也不同，意思是努力上进。", "请见": "请见 qǐngjiàn 第二音节韵母为 -ian（请进为 -in），意思是请求接见，也用于「请见附件」。"}, "sentence_index": null, "correct_answer": "请进"}, "level_3": {"options": [{"text": "请进", "is_correct": true, "explanation": "请进：客气地请人进入，符合「把客人……了会议室」的语境。"}, {"text": "拖进", "is_correct": false, "explanation": "语义：「拖」指强行拽，与王经理热情待客的语境冲突。"}, {"text": "押进", "is_correct": false, "explanation": "搭配：「押」多用于押送犯人，不说押客人进入会议室。"}, {"text": "关进", "is_correct": false, "explanation": "语义：「关进」表示关押，与客人受礼遇的语境相矛盾。"}], "explanations": {"请进": "请进：客气地请人进入，符合「把客人……了会议室」的语境。", "拖进": "语义：「拖」指强行拽，与王经理热情待客的语境冲突。", "押进": "搭配：「押」多用于押送犯人，不说押客人进入会议室。", "关进": "语义：「关进」表示关押，与客人受礼遇的语境相矛盾。"}, "sentence_index": 0, "correct_answer": "请进"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈把东西请进了屋子。", "explanation": "这里应该用〈带进〉。请进是礼貌地请人进入，东西不能用「请」。"}, {"text": "救护车把病人请进了医院。", "explanation": "这里应该用〈送进〉。请进带有待客的礼貌，救护车运送病人不能说请进。"}, {"text": "公司请进了一台新设备。", "explanation": "这里应该用〈引进〉。请进只用于请人进入，设备要说引进。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82e5dd3c-c450-4323-b6e3-d14b153be005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95436, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "请进", "is_correct": true, "explanation": "请进：客气地请人进入，符合门口保安引导来客的语境。"}, {"text": "扔进", "is_correct": false, "explanation": "语义：「扔」是抛掷，与保安礼貌引导我进入的语境冲突。"}, {"text": "装进", "is_correct": false, "explanation": "语义：「装进」指把东西放入容器，不能用于把人送进大楼。"}, {"text": "塞进", "is_correct": false, "explanation": "语义：「塞进」是硬把人或东西挤进去，与保安礼貌引导我进入的语境冲突。"}], "explanations": {"请进": "请进：客气地请人进入，符合门口保安引导来客的语境。", "扔进": "语义：「扔」是抛掷，与保安礼貌引导我进入的语境冲突。", "装进": "语义：「装进」指把东西放入容器，不能用于把人送进大楼。", "塞进": "语义：「塞进」是硬把人或东西挤进去，与保安礼貌引导我进入的语境冲突。"}, "sentence_index": 6, "correct_answer": "请进"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "客人吃完饭要走了，服务员又把他请进了包间。", "explanation": "这里应该用〈送出〉。请进是请人进入，客人要离开时应把他送出去。"}, {"text": "客人已经走进包间了，老板还把他请进包间。", "explanation": "这里应该用〈请坐〉。请进是请人进入，客人已经进了包间，不能再说请进，应说请坐。"}, {"text": "老板把一箱水果请进了仓库。", "explanation": "这里应该用〈搬进〉。请进只用于客气地请人进入，东西要说搬进。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82e5dd3c-c450-4323-b6e3-d14b153be005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95436, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师把学生请进着办公室。", "corrected_sentence": "老师把学生请进了办公室。", "error_description": "错误：「请进着」；正确：「请进了」。表示一次性完成的请人进入，要用「了」；「着」表示持续的状态，与此句的动作不符。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82e5dd3c-c450-4323-b6e3-d14b153be005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95436, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈把客人请进来了屋里。", "corrected_sentence": "妈妈把客人请进了屋里。", "error_description": "错误：「请进来了屋里」；正确：「请进了屋里」。「请进」后接处所宾语时，「来」不能插在「进」与处所之间，多余的「来」应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82e5dd3c-c450-4323-b6e3-d14b153be005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
