INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95437, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "没有人证明过的假话，大家传来传去。", "primary_collocate": null, "pronunciation": "yáo yán", "ipa": "jɑʊ̯˧˥ jɛn˧˥", "syllable_count": 2, "sentences": [{"text": "这个谣言传得很快。", "target_word": "谣言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别相信网上的谣言。", "target_word": "谣言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的是谣言，不是真的。", "target_word": "谣言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司里有一个谣言，说老板要走了。", "target_word": "谣言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谣言越传越多，大家都很担心。", "target_word": "谣言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察说，这个谣言是假的。", "target_word": "谣言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从来没有听过这种谣言。", "target_word": "谣言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很生气，因为有人在传她的谣言。", "target_word": "谣言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要再传这个谣言了。", "target_word": "谣言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个小谣言让全班同学都紧张起来。", "target_word": "谣言", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "没有证实、被人传来传去的假话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c29519-b224-40c3-87a0-c14ac1f50481') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95437, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "谣言", "is_correct": true, "explanation": "谣言 yáoyán 指没有证实、四处流传的假话。"}, {"text": "耀眼", "is_correct": false, "explanation": "耀眼 yàoyǎn 两个音节的声调都与 yáoyán 不同（yào 第四声、yǎn 第三声），意思是光线明亮刺眼。"}, {"text": "妖艳", "is_correct": false, "explanation": "妖艳 yāoyàn 两个音节的声调都与 yáoyán 不同（yāo 第一声、yàn 第四声），意思是艳丽而妖媚。"}, {"text": "要言", "is_correct": false, "explanation": "要言 yàoyán 第一音节为第四声，只与 yáo 差一个声调，意思是扼要的话。"}], "explanations": {"谣言": "谣言 yáoyán 指没有证实、四处流传的假话。", "耀眼": "耀眼 yàoyǎn 两个音节的声调都与 yáoyán 不同（yào 第四声、yǎn 第三声），意思是光线明亮刺眼。", "妖艳": "妖艳 yāoyàn 两个音节的声调都与 yáoyán 不同（yāo 第一声、yàn 第四声），意思是艳丽而妖媚。", "要言": "要言 yàoyán 第一音节为第四声，只与 yáo 差一个声调，意思是扼要的话。"}, "sentence_index": null, "correct_answer": "谣言"}, "level_3": {"options": [{"text": "谣言", "is_correct": true, "explanation": "正确。谣言指没有证实的假话，可以“传得很快”。"}, {"text": "证据", "is_correct": false, "explanation": "语义：证据是用来证明事实的，不会像谣言那样“传得很快”。"}, {"text": "礼物", "is_correct": false, "explanation": "语义：“传得很快”说的是话或消息在人们之间流传，礼物不会这样“传开”。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子是实物，不会被“传”开，句子说的是流传的话。"}], "explanations": {"谣言": "正确。谣言指没有证实的假话，可以“传得很快”。", "证据": "语义：证据是用来证明事实的，不会像谣言那样“传得很快”。", "礼物": "语义：“传得很快”说的是话或消息在人们之间流传，礼物不会这样“传开”。", "房子": "语义：房子是实物，不会被“传”开，句子说的是流传的话。"}, "sentence_index": 0, "correct_answer": "谣言"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个谣言是真的，我们都证实了。", "explanation": "这里应该用〈消息〉。谣言指没有证实的假话，不能说“真的谣言”，与“已经证实”相矛盾。"}, {"text": "这个谣言很可靠，大家都相信了。", "explanation": "这里应该用〈消息〉。谣言是没有证实的假话，不能用“很可靠”来形容。"}, {"text": "医生根据这个谣言给病人开了药。", "explanation": "这里应该用〈检查结果〉。谣言没有根据，医生不能用它来开药。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cdfabf4-1fd2-44eb-a396-a79b343c6c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95437, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "谣言", "is_correct": true, "explanation": "正确。“听过”的是流传的假话，谣言符合句意。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“听”不能和“味道”搭配，说味道要用“闻”。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“听”不能和“颜色”搭配，说颜色要用“看”。"}, {"text": "形状", "is_correct": false, "explanation": "语义：形状不是声音，耳朵听不到，与“听过”的意思冲突。"}], "explanations": {"谣言": "正确。“听过”的是流传的假话，谣言符合句意。", "味道": "搭配：“听”不能和“味道”搭配，说味道要用“闻”。", "颜色": "搭配：“听”不能和“颜色”搭配，说颜色要用“看”。", "形状": "语义：形状不是声音，耳朵听不到，与“听过”的意思冲突。"}, "sentence_index": 6, "correct_answer": "谣言"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这篇谣言是真实的，记者亲眼看到了。", "explanation": "这里应该用〈报道〉。谣言没有证实，不能说“真实的谣言”，“亲眼看到”也与之矛盾。"}, {"text": "科学家通过这个谣言得出了结论。", "explanation": "这里应该用〈实验〉。谣言没有根据，不能用来得出科学结论。"}, {"text": "老师夸他的谣言写得很认真。", "explanation": "这里应该用〈作文〉。谣言是流传的没有根据的话，不是认真写出来交给老师的作业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cdfabf4-1fd2-44eb-a396-a79b343c6c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95437, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我听到了一把谣言。", "corrected_sentence": "我听到了一条谣言。", "error_description": "量词错误：谣言应用“条”或“个”，不能用“把”。正确说法是“一条谣言”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cdfabf4-1fd2-44eb-a396-a79b343c6c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95437, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家都很担心这张谣言。", "corrected_sentence": "大家都很担心这个谣言。", "error_description": "量词错误：谣言应用“个”或“条”，不能用“张”（“张”用于纸张、桌子等）。应说“这个谣言”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cdfabf4-1fd2-44eb-a396-a79b343c6c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
