INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95438, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "没有事实根据而四处流传的话。", "primary_collocate": null, "pronunciation": "yáo yán", "ipa": "jɑʊ̯˧˥ jɛn˧˥", "syllable_count": 2, "sentences": [{"text": "这件事根本没有根据，只是谣言。", "target_word": "谣言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻说，那些话都是谣言。", "target_word": "谣言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谣言让这家小店没有了客人。", "target_word": "谣言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不听谣言，只看事实。", "target_word": "谣言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天城里到处都是谣言。", "target_word": "谣言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师告诉我们要分清事实和谣言。", "target_word": "谣言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人故意散布谣言，想让大家害怕。", "target_word": "谣言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谣言过了几天就慢慢没有了。", "target_word": "谣言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个谣言伤害了很多人。", "target_word": "谣言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到谣言后，我先问了朋友。", "target_word": "谣言", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "没有事实根据、到处流传的话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c29519-b224-40c3-87a0-c14ac1f50481') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95438, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "谣言", "is_correct": true, "explanation": "谣言 yáoyán 指没有事实根据、到处流传的话。"}, {"text": "耀眼", "is_correct": false, "explanation": "耀眼 yàoyǎn 两个音节的声调都与 yáoyán 不同（yào 第四声、yǎn 第三声），意思是光线明亮刺眼。"}, {"text": "妖艳", "is_correct": false, "explanation": "妖艳 yāoyàn 两个音节的声调都与 yáoyán 不同（yāo 第一声、yàn 第四声），意思是艳丽而妖媚。"}, {"text": "要言", "is_correct": false, "explanation": "要言 yàoyán 第一音节为第四声，只与 yáo 差一个声调，意思是扼要的话。"}], "explanations": {"谣言": "谣言 yáoyán 指没有事实根据、到处流传的话。", "耀眼": "耀眼 yàoyǎn 两个音节的声调都与 yáoyán 不同（yào 第四声、yǎn 第三声），意思是光线明亮刺眼。", "妖艳": "妖艳 yāoyàn 两个音节的声调都与 yáoyán 不同（yāo 第一声、yàn 第四声），意思是艳丽而妖媚。", "要言": "要言 yàoyán 第一音节为第四声，只与 yáo 差一个声调，意思是扼要的话。"}, "sentence_index": null, "correct_answer": "谣言"}, "level_3": {"options": [{"text": "谣言", "is_correct": true, "explanation": "正确。“只是谣言”说明这件事没有根据，符合句意。"}, {"text": "事实", "is_correct": false, "explanation": "语义：前句说“没有根据”，“事实”是有根据的，与“只是”后的判断矛盾。"}, {"text": "证据", "is_correct": false, "explanation": "语义：证据用来证明有根据，与“根本没有根据”相矛盾。"}, {"text": "礼物", "is_correct": false, "explanation": "搭配：“只是”后接的应是说明事情性质的词，“礼物”不能用来说明“这件事”。"}], "explanations": {"谣言": "正确。“只是谣言”说明这件事没有根据，符合句意。", "事实": "语义：前句说“没有根据”，“事实”是有根据的，与“只是”后的判断矛盾。", "证据": "语义：证据用来证明有根据，与“根本没有根据”相矛盾。", "礼物": "搭配：“只是”后接的应是说明事情性质的词，“礼物”不能用来说明“这件事”。"}, "sentence_index": 0, "correct_answer": "谣言"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "法官根据这个谣言作出了判决。", "explanation": "这里应该用〈证据〉。谣言没有事实根据，法官不能凭它判决。"}, {"text": "这份谣言是他们认真调查后写的。", "explanation": "这里应该用〈报告〉。谣言没有事实根据，不能说是认真调查后写的。"}, {"text": "他带来了一个好谣言。", "explanation": "这里应该用〈消息〉。谣言指假话，不能用“好”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cdfabf4-1fd2-44eb-a396-a79b343c6c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95438, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "谣言", "is_correct": true, "explanation": "正确。“散布谣言”是故意传播没有根据的话，让大家害怕。"}, {"text": "钱", "is_correct": false, "explanation": "语义：钱不能被“散布”来让人害怕，句子说的是流传的话。"}, {"text": "食物", "is_correct": false, "explanation": "搭配：“散布”多用于消息、言论、恐慌，不说“散布食物”。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶是器物，不能“散布”，与“想让大家害怕”无关。"}], "explanations": {"谣言": "正确。“散布谣言”是故意传播没有根据的话，让大家害怕。", "钱": "语义：钱不能被“散布”来让人害怕，句子说的是流传的话。", "食物": "搭配：“散布”多用于消息、言论、恐慌，不说“散布食物”。", "花瓶": "语义：花瓶是器物，不能“散布”，与“想让大家害怕”无关。"}, "sentence_index": 6, "correct_answer": "谣言"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这篇谣言有证据支持，是真的。", "explanation": "这里应该用〈报道〉。谣言没有事实根据，不能说“有证据支持，是真的”。"}, {"text": "这是一段真实的谣言。", "explanation": "这里应该用〈历史〉。谣言不是真实发生的事，“真实的谣言”自相矛盾。"}, {"text": "这组谣言很准确。", "explanation": "这里应该用〈数据〉。谣言不可靠，不能用“准确”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cdfabf4-1fd2-44eb-a396-a79b343c6c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95438, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他不相信那把谣言。", "corrected_sentence": "他不相信那条谣言。", "error_description": "量词错误：谣言应用“条”或“个”，不能用“把”。正确说法是“那条谣言”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cdfabf4-1fd2-44eb-a396-a79b343c6c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95438, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张谣言吓坏了小朋友。", "corrected_sentence": "这个谣言吓坏了小朋友。", "error_description": "量词错误：谣言应用“个”或“条”，不能用“张”（“张”用于纸张、桌子等）。应说“这个谣言”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cdfabf4-1fd2-44eb-a396-a79b343c6c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
