INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95439, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "房子里让人走路的那一条路。", "primary_collocate": null, "pronunciation": "zǒu dào", "ipa": "tsoʊ˨˩˦ taʊ˥˩", "syllable_count": 2, "sentences": [{"text": "我家的走道很短，只有三米。", "target_word": "走道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把鞋子放在走道里，妈妈有点生气。", "target_word": "走道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间门外的走道里有一盏小灯。", "target_word": "走道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走道的墙上挂着很多全家的照片。", "target_word": "走道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上，孩子在走道里跑来跑去。", "target_word": "走道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个走道太窄，大桌子搬不过去。", "target_word": "走道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把走道打扫干净，客人马上就到。", "target_word": "走道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从客厅到卧室，要经过一条长长的走道。", "target_word": "走道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "楼上的走道里放着一辆小自行车。", "target_word": "走道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷喜欢在家里的走道上慢慢散步。", "target_word": "走道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "一条走道", "label": "量词搭配"}], "register": "中性", "sense_fingerprint": "房子里连接房间的通道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91f27bcb-e915-4d91-af5c-63c661bfa7ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95439, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "走道", "is_correct": true, "explanation": "正确：房内连接房间的通道，“我家的走道”合理，“只有三米”说的是长度。"}, {"text": "牛奶", "is_correct": false, "explanation": "语义：牛奶不能用“米”量长度，“我家的牛奶只有三米”不成立。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“只有三米”量的是长度，不能用来量“时间”。"}, {"text": "河流", "is_correct": false, "explanation": "语义：房子里没有河流，“我家的河流”不成立。"}], "explanations": {"走道": "正确：房内连接房间的通道，“我家的走道”合理，“只有三米”说的是长度。", "牛奶": "语义：牛奶不能用“米”量长度，“我家的牛奶只有三米”不成立。", "时间": "搭配：“只有三米”量的是长度，不能用来量“时间”。", "河流": "语义：房子里没有河流，“我家的河流”不成立。"}, "sentence_index": 0, "correct_answer": "走道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他扶着栏杆，一级一级地爬上走道。", "explanation": "这里应该用〈楼梯〉。走道是房间里水平的通道，一级一级地往上走要用楼梯"}, {"text": "他把钥匙插进走道，然后打开了房门。", "explanation": "这里应该用〈门锁〉。钥匙要插进门锁，走道是通道，不能插钥匙"}, {"text": "他打开走道，拿出一瓶冰牛奶。", "explanation": "这里应该用〈冰箱〉。冰牛奶放在冰箱里，走道是通道，不能打开拿东西"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '688b247e-a2ac-4095-bcf3-0f9f901c9e49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95439, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "走道", "is_correct": true, "explanation": "正确：“打扫”的对象是房内的通道，与“客人马上就到”的语境相符。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“打扫”的对象是地面、房间等，不能用于“作业”。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不能被打扫干净，与房内场景不符。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“打扫”不能用于“空气”，不能说“把空气打扫干净”。"}], "explanations": {"走道": "正确：“打扫”的对象是房内的通道，与“客人马上就到”的语境相符。", "作业": "搭配：“打扫”的对象是地面、房间等，不能用于“作业”。", "天空": "语义：天空不能被打扫干净，与房内场景不符。", "空气": "搭配：“打扫”不能用于“空气”，不能说“把空气打扫干净”。"}, "sentence_index": 6, "correct_answer": "走道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天把车停在走道里，出门很方便。", "explanation": "这里应该用〈车库〉。走道供人步行，不能用来停车"}, {"text": "他一脚踢开走道，冲进了房间。", "explanation": "这里应该用〈门〉。走道不能踢开，要踢开的是门"}, {"text": "她把冬天的衣服叠好，放进了走道的抽屉里。", "explanation": "这里应该用〈衣柜〉。放衣服的抽屉在衣柜里，走道是通道，没有抽屉"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '688b247e-a2ac-4095-bcf3-0f9f901c9e49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95439, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们家有一只很长的走道。", "corrected_sentence": "我们家有一条很长的走道。", "error_description": "量词错误：“走道”的量词是“条”，应说“一条很长的走道”，不能说“一只很长的走道”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '688b247e-a2ac-4095-bcf3-0f9f901c9e49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95439, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条很长走道，尽头有一扇小窗。", "corrected_sentence": "这条很长的走道，尽头有一扇小窗。", "error_description": "结构错误：“很长”修饰“走道”时中间需加“的”，应写作“很长的走道”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '688b247e-a2ac-4095-bcf3-0f9f901c9e49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
