INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95440, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "供人行走的通道。", "primary_collocate": null, "pronunciation": "zǒu dào", "ipa": "tsoʊ˨˩˦ taʊ˥˩", "syllable_count": 2, "sentences": [{"text": "飞机上的走道很窄，请不要站在这里。", "target_word": "走道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影院的走道上有小灯。", "target_word": "走道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市的走道很宽，两个人可以一起走过。", "target_word": "走道", "complexity_tier": "T3", "furigana": "chāo shì de zǒu dào hěn kuān, liǎng gè rén kě yǐ yì qǐ zǒu guò.", "sentence_source": "generated"}, {"text": "火车上有人把行李放在走道里，别人过不去。", "target_word": "走道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要在走道上大声说话。", "target_word": "走道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室里的走道不宽，同学们要慢慢走。", "target_word": "走道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商场的走道两边都是商店。", "target_word": "走道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐在走道旁边的人，可以很快站起来。", "target_word": "走道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院的走道里，护士推着车走过来。", "target_word": "走道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "体育场的走道上都是等着进门的人。", "target_word": "走道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "一条走道", "label": "量词搭配"}], "register": "中性", "sense_fingerprint": "公共场所供人通行的过道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91f27bcb-e915-4d91-af5c-63c661bfa7ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95440, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "走道", "is_correct": true, "explanation": "正确：走道指供人行走的通道，“飞机上的走道”是常见说法。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：飞机上没有沙发，句子说的是供人通行的地方。"}, {"text": "行李", "is_correct": false, "explanation": "搭配：“很窄”形容空间，不能用来形容行李。"}, {"text": "花园", "is_correct": false, "explanation": "语义：飞机机舱内没有花园，与“飞机上”冲突。"}], "explanations": {"走道": "正确：走道指供人行走的通道，“飞机上的走道”是常见说法。", "沙发": "语义：飞机上没有沙发，句子说的是供人通行的地方。", "行李": "搭配：“很窄”形容空间，不能用来形容行李。", "花园": "语义：飞机机舱内没有花园，与“飞机上”冲突。"}, "sentence_index": 0, "correct_answer": "走道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天太热了，孩子们都跳进走道里游泳。", "explanation": "这里应该用〈游泳池〉。走道是供人行走的通道，里面没有水，不能游泳"}, {"text": "他慢慢爬上走道，一步一步很吃力。", "explanation": "这里应该用〈楼梯〉。走道是水平的通道，一步一步往上爬要用楼梯，不能用走道"}, {"text": "这张走道很长，我们快点走过去吧。", "explanation": "这里应该用〈条〉。走道是长条形的通道，量词用“条”，不用“张”"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '688b247e-a2ac-4095-bcf3-0f9f901c9e49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95440, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "走道", "is_correct": true, "explanation": "正确：走道是两侧有店铺的通道，“两边都是商店”合理。"}, {"text": "车库", "is_correct": false, "explanation": "语义：商场里的车库两边不会都是商店，车库供停车用。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“两边都是”说空间位置，不能用于“价格”。"}, {"text": "墙壁", "is_correct": false, "explanation": "语义：墙壁不是可以两边开店的场所，与“商店”的场景不符。"}], "explanations": {"走道": "正确：走道是两侧有店铺的通道，“两边都是商店”合理。", "车库": "语义：商场里的车库两边不会都是商店，车库供停车用。", "价格": "搭配：“两边都是”说空间位置，不能用于“价格”。", "墙壁": "语义：墙壁不是可以两边开店的场所，与“商店”的场景不符。"}, "sentence_index": 6, "correct_answer": "走道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "汽车在走道上行驶，速度很快。", "explanation": "这里应该用〈马路〉。走道是供人步行的通道，汽车不能在上面行驶"}, {"text": "我们走过这条走道，就到了河的对岸。", "explanation": "这里应该用〈桥〉。走道是场所里供人通行的过道，跨过河要用桥"}, {"text": "我把车停在走道上，然后去买东西。", "explanation": "这里应该用〈停车场〉。走道供人步行，不能用来停车"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '688b247e-a2ac-4095-bcf3-0f9f901c9e49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95440, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只走道很长，大家可以并排走。", "corrected_sentence": "这条走道很长，大家可以并排走。", "error_description": "量词错误：“走道”应使用量词“条”，说“这条走道”，不能说“这只走道”。“只”用于动物或成对物中的一个。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '688b247e-a2ac-4095-bcf3-0f9f901c9e49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95440, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条很窄走道，只能容一个人通过。", "corrected_sentence": "这条很窄的走道，只能容一个人通过。", "error_description": "结构错误：“很窄”修饰“走道”时中间需加“的”，应写作“很窄的走道”，不能省略“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '688b247e-a2ac-4095-bcf3-0f9f901c9e49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
