INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95442, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情前进的方向。", "primary_collocate": null, "pronunciation": "lù xiàng", "ipa": "lu˥˩ ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "毕业以后，他还没想好人生的路向。", "target_word": "路向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司要找准今后的路向，大家一起商量。", "target_word": "路向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次会议讨论了学校今后的路向。", "target_word": "路向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她换了工作，想找新的路向。", "target_word": "路向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母希望孩子自己选择未来的路向。", "target_word": "路向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济不好时，小公司要重新看清路向。", "target_word": "路向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事的路向，现在还不清楚。", "target_word": "路向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师帮他看清了学习的路向。", "target_word": "路向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有目标的人，常常找不到路向。", "target_word": "路向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书给年轻人指明了路向。", "target_word": "路向", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "人生、事业或事情发展的方向", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c139710-9a85-4ec9-b9b6-0cb261a0b0c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95442, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "路向", "is_correct": true, "explanation": "正确。路向 lù xiàng，指道路或事情前进的方向。"}, {"text": "木像", "is_correct": false, "explanation": "mù 与 lù 声母不同（m 与 l），意思是木雕的像。"}, {"text": "怒相", "is_correct": false, "explanation": "声母不同（n 与 l），声调相同，意思是愤怒的神色。"}, {"text": "立像", "is_correct": false, "explanation": "韵母不同（i 与 u），声调相同，意思是雕像，与道路无关。"}], "explanations": {"路向": "正确。路向 lù xiàng，指道路或事情前进的方向。", "木像": "mù 与 lù 声母不同（m 与 l），意思是木雕的像。", "怒相": "声母不同（n 与 l），声调相同，意思是愤怒的神色。", "立像": "韵母不同（i 与 u），声调相同，意思是雕像，与道路无关。"}, "sentence_index": null, "correct_answer": "路向"}, "level_3": {"options": [{"text": "路向", "is_correct": true, "explanation": "正确。“毕业以后，他还没想好人生的路向”中，路向指人生的前进方向，与“想好”搭配。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重指身体的重量，与“人生的方向”不相关。"}, {"text": "价钱", "is_correct": false, "explanation": "语义：价钱指价格，不能指人生的方向。"}, {"text": "路面", "is_correct": false, "explanation": "搭配：“路面”指道路的表层，不能用于人生的规划。"}], "explanations": {"路向": "正确。“毕业以后，他还没想好人生的路向”中，路向指人生的前进方向，与“想好”搭配。", "体重": "语义：体重指身体的重量，与“人生的方向”不相关。", "价钱": "语义：价钱指价格，不能指人生的方向。", "路面": "搭配：“路面”指道路的表层，不能用于人生的规划。"}, "sentence_index": 0, "correct_answer": "路向"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的路向很高，比我高出一个头。", "explanation": "这里应该用〈身高〉。路向指前进的方向，不能说高矮；说人有多高要用身高。"}, {"text": "汽车的路向每小时超过一百公里。", "explanation": "这里应该用〈速度〉。路向指前进的方向，不指快慢，说每小时多少公里要用速度。"}, {"text": "他的路向重七十公斤。", "explanation": "这里应该用〈体重〉。路向指事情前进的方向，不能用公斤计量，说人的重量要用体重。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f8b4656-bee1-4fd8-ab2a-1afecd013050') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95442, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "路向", "is_correct": true, "explanation": "正确。路向 lù xiàng，指道路或事情前进的方向。"}, {"text": "炉香", "is_correct": false, "explanation": "声调不同：lú xiāng 与 lù xiàng，意思是香炉里烧的香。"}, {"text": "乳香", "is_correct": false, "explanation": "声母和声调不同（r 与 l），rǔ xiāng 是一种香料。"}, {"text": "互相", "is_correct": false, "explanation": "声母不同（h 与 l），hù xiāng 意思是彼此，与方向无关。"}], "explanations": {"路向": "正确。路向 lù xiàng，指道路或事情前进的方向。", "炉香": "声调不同：lú xiāng 与 lù xiàng，意思是香炉里烧的香。", "乳香": "声母和声调不同（r 与 l），rǔ xiāng 是一种香料。", "互相": "声母不同（h 与 l），hù xiāng 意思是彼此，与方向无关。"}, "sentence_index": null, "correct_answer": "路向"}, "level_3": {"options": [{"text": "路向", "is_correct": true, "explanation": "正确。“这件事的路向，现在还不清楚”中，路向指事情发展的方向，与“不清楚”搭配。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高指人的身体高度，不能指一件事的方向。"}, {"text": "房租", "is_correct": false, "explanation": "语义：房租指租住房屋的费用，与事情的方向无关。"}, {"text": "饭量", "is_correct": false, "explanation": "搭配：“饭量”指吃饭的多少，只用于人或动物的进食，不能说“这件事的饭量”。"}], "explanations": {"路向": "正确。“这件事的路向，现在还不清楚”中，路向指事情发展的方向，与“不清楚”搭配。", "身高": "语义：身高指人的身体高度，不能指一件事的方向。", "房租": "语义：房租指租住房屋的费用，与事情的方向无关。", "饭量": "搭配：“饭量”指吃饭的多少，只用于人或动物的进食，不能说“这件事的饭量”。"}, "sentence_index": 6, "correct_answer": "路向"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我来这里的路向是三月三十号。", "explanation": "这里应该用〈日期〉。路向指前进的方向，不能指日子；说具体哪天要用日期。"}, {"text": "这个机器的路向是噪音很小。", "explanation": "这里应该用〈特点〉。路向指事情前进的方向，不能描述机器的性质；说事物突出的性质或优点要用特点。"}, {"text": "工程的路向比原计划快了一周。", "explanation": "这里应该用〈进度〉。路向指方向，说快慢和完成的程度要用进度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f8b4656-bee1-4fd8-ab2a-1afecd013050') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95442, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师帮他看清了自己路向。", "corrected_sentence": "老师帮他看清了自己的路向。", "error_description": "错误形式：“自己路向”；正确形式：“自己的路向”。“自己”修饰“路向”时须加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f8b4656-bee1-4fd8-ab2a-1afecd013050') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95442, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他找到了一只适合自己的路向。", "corrected_sentence": "他找到了一个适合自己的路向。", "error_description": "错误形式：“一只适合自己的路向”；正确形式：“一个适合自己的路向”。“只”多用于动物或成对的物品，抽象的“路向”应用“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f8b4656-bee1-4fd8-ab2a-1afecd013050') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
