INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95443, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用脚压在东西上面。", "primary_collocate": null, "pronunciation": "cǎi", "ipa": "tsʰaɪ̯˨˩˦", "syllable_count": 1, "sentences": [{"text": "对不起，我踩到你的脚了。", "target_word": "踩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小心，别踩草地。", "target_word": "踩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一脚踩在水里。", "target_word": "踩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上有香蕉皮，我踩了一下。", "target_word": "踩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子喜欢踩着雪走路。", "target_word": "踩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不小心踩了我一脚。", "target_word": "踩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别踩我的新鞋！", "target_word": "踩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我踩到了一块石头。", "target_word": "踩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要踩椅子。", "target_word": "踩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他踩着地毯走进房间。", "target_word": "踩", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "踩了", "label": "体标"}, {"form": "踩过", "label": "体标"}, {"form": "踩着", "label": "体标"}, {"form": "踩踩", "label": "重叠"}], "register": "口语", "sense_fingerprint": "脚落在东西上并压住它", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c29519-b224-40c3-87a0-c14ac1f50481') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95443, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "踩", "is_correct": true, "explanation": "踩 cǎi 指用脚压在东西上面。"}, {"text": "菜", "is_correct": false, "explanation": "cài（第四声）与 cǎi（第三声）声调不同，意思是蔬菜。"}, {"text": "猜", "is_correct": false, "explanation": "cāi（第一声）与 cǎi（第三声）声调不同，意思是猜测。"}, {"text": "惨", "is_correct": false, "explanation": "cǎn 与 cǎi 韵母不同（an 与 ai），意思是悲惨。"}, {"text": "才", "is_correct": false, "explanation": "cái（第二声）与 cǎi（第三声）声调不同，意思是刚刚、才能。"}], "explanations": {"踩": "踩 cǎi 指用脚压在东西上面。", "菜": "cài（第四声）与 cǎi（第三声）声调不同，意思是蔬菜。", "猜": "cāi（第一声）与 cǎi（第三声）声调不同，意思是猜测。", "惨": "cǎn 与 cǎi 韵母不同（an 与 ai），意思是悲惨。", "才": "cái（第二声）与 cǎi（第三声）声调不同，意思是刚刚、才能。"}, "sentence_index": null, "correct_answer": "踩"}, "level_3": {"options": [{"text": "踩", "is_correct": true, "explanation": "正确。“踩到你的脚”是脚压在对方脚上，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语是食物，不能说“吃到你的脚”。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”只用于饮料，不能说“喝到你的脚”。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”是发出歌声，与脚碰到别人的意思不符。"}], "explanations": {"踩": "正确。“踩到你的脚”是脚压在对方脚上，符合句意。", "吃": "搭配：“吃”的宾语是食物，不能说“吃到你的脚”。", "喝": "搭配：“喝”只用于饮料，不能说“喝到你的脚”。", "唱": "语义：“唱”是发出歌声，与脚碰到别人的意思不符。"}, "sentence_index": 0, "correct_answer": "踩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一脚踩开了门。", "explanation": "这里应该用〈踹〉。踹是用脚猛力踢，踩是用脚压在东西上，不能表示“一脚踹开”。"}, {"text": "她踩着栏杆下楼。", "explanation": "这里应该用〈扶〉。下楼时要用手扶栏杆，踩是用脚压在东西上，不能说“踩着栏杆”下楼。"}, {"text": "他用头踩了一下门。", "explanation": "这里应该用〈撞〉。踩必须用脚，不能用头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cdfabf4-1fd2-44eb-a396-a79b343c6c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95443, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "踩", "is_correct": true, "explanation": "踩 cǎi 指用脚压在东西上面。"}, {"text": "财", "is_correct": false, "explanation": "cái（第二声）与 cǎi（第三声）声调不同，意思是钱财。"}, {"text": "材", "is_correct": false, "explanation": "cái（第二声）与 cǎi（第三声）声调不同，意思是材料。"}, {"text": "裁", "is_correct": false, "explanation": "cái（第二声）与 cǎi（第三声）声调不同，意思是裁判、裁剪。"}], "explanations": {"踩": "踩 cǎi 指用脚压在东西上面。", "财": "cái（第二声）与 cǎi（第三声）声调不同，意思是钱财。", "材": "cái（第二声）与 cǎi（第三声）声调不同，意思是材料。", "裁": "cái（第二声）与 cǎi（第三声）声调不同，意思是裁判、裁剪。"}, "sentence_index": null, "correct_answer": "踩"}, "level_3": {"options": [{"text": "踩", "is_correct": true, "explanation": "正确。“别踩我的新鞋”是不让脚压在鞋上，符合句意。"}, {"text": "读", "is_correct": false, "explanation": "搭配：“读”的宾语是书、报纸等文字材料，不能说“读我的新鞋”。"}, {"text": "听", "is_correct": false, "explanation": "搭配：“听”的宾语是声音、音乐，不能说“听我的新鞋”。"}, {"text": "睡", "is_correct": false, "explanation": "语法：“睡”是不及物动词，不能直接带“我的新鞋”作宾语。"}], "explanations": {"踩": "正确。“别踩我的新鞋”是不让脚压在鞋上，符合句意。", "读": "搭配：“读”的宾语是书、报纸等文字材料，不能说“读我的新鞋”。", "听": "搭配：“听”的宾语是声音、音乐，不能说“听我的新鞋”。", "睡": "语法：“睡”是不及物动词，不能直接带“我的新鞋”作宾语。"}, "sentence_index": 6, "correct_answer": "踩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在河里踩水，救起了一个孩子。", "explanation": "这里是“踩水”（在水中用脚蹬动、保持漂浮）的意思，不是“用脚压在东西上”。"}, {"text": "比赛中他用手踩线，被裁判判犯规。", "explanation": "这里应该用〈碰〉。踩必须用脚，不能用手。"}, {"text": "孩子们踩着鼓点行进。", "explanation": "这里是“踩着鼓点”（随节拍行进）的意思，不是“用脚压在东西上”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cdfabf4-1fd2-44eb-a396-a79b343c6c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95443, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她踩了到一个水坑。", "corrected_sentence": "她踩到了一个水坑。", "error_description": "补语位置错误：“到”是“踩”的补语，要紧跟动词，应说“踩到了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cdfabf4-1fd2-44eb-a396-a79b343c6c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95443, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他坏踩了我的鞋。", "corrected_sentence": "他踩坏了我的鞋。", "error_description": "补语位置错误：结果补语“坏”要放在动词后，应说“踩坏了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cdfabf4-1fd2-44eb-a396-a79b343c6c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
