INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95444, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用脚底压在物体上。", "primary_collocate": null, "pronunciation": "cǎi", "ipa": "tsʰaɪ̯˨˩˦", "syllable_count": 1, "sentences": [{"text": "小狗踩了一脚泥。", "target_word": "踩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我踩上凳子拿书。", "target_word": "踩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在院子里踩落叶玩。", "target_word": "踩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她踩住了那张纸。", "target_word": "踩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机踩了一下刹车。", "target_word": "踩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我踩在冰上，差点摔倒。", "target_word": "踩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在泥地上踩出了很多脚印。", "target_word": "踩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别踩那条线。", "target_word": "踩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把烟踩灭了。", "target_word": "踩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我踩了踩这块木板，很结实。", "target_word": "踩", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "踩了", "label": "体标"}, {"form": "踩过", "label": "体标"}, {"form": "踩着", "label": "体标"}, {"form": "踩踩", "label": "重叠"}], "register": "口语", "sense_fingerprint": "用脚底踏在物体上并用力压", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c29519-b224-40c3-87a0-c14ac1f50481') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95444, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "踩", "is_correct": true, "explanation": "踩 cǎi 指用脚底压在物体上。"}, {"text": "菜", "is_correct": false, "explanation": "cài（第四声）与 cǎi（第三声）声调不同，意思是蔬菜。"}, {"text": "猜", "is_correct": false, "explanation": "cāi（第一声）与 cǎi（第三声）声调不同，意思是猜测。"}, {"text": "惨", "is_correct": false, "explanation": "cǎn 与 cǎi 韵母不同（an 与 ai），意思是悲惨。"}, {"text": "才", "is_correct": false, "explanation": "cái（第二声）与 cǎi（第三声）声调不同，意思是刚刚、才能。"}], "explanations": {"踩": "踩 cǎi 指用脚底压在物体上。", "菜": "cài（第四声）与 cǎi（第三声）声调不同，意思是蔬菜。", "猜": "cāi（第一声）与 cǎi（第三声）声调不同，意思是猜测。", "惨": "cǎn 与 cǎi 韵母不同（an 与 ai），意思是悲惨。", "才": "cái（第二声）与 cǎi（第三声）声调不同，意思是刚刚、才能。"}, "sentence_index": null, "correct_answer": "踩"}, "level_3": {"options": [{"text": "踩", "is_correct": true, "explanation": "正确。“小狗踩了一脚泥”是脚压在泥上，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语多是食物，不能说“吃一脚泥”。"}, {"text": "摸", "is_correct": false, "explanation": "语义：“摸”是用手轻触，不能表示脚压在泥上。"}, {"text": "抱", "is_correct": false, "explanation": "搭配：“抱”的对象是人或可以抱的东西，不能和“一脚泥”搭配。"}], "explanations": {"踩": "正确。“小狗踩了一脚泥”是脚压在泥上，符合句意。", "吃": "搭配：“吃”的宾语多是食物，不能说“吃一脚泥”。", "摸": "语义：“摸”是用手轻触，不能表示脚压在泥上。", "抱": "搭配：“抱”的对象是人或可以抱的东西，不能和“一脚泥”搭配。"}, "sentence_index": 0, "correct_answer": "踩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用手踩住了那张纸。", "explanation": "这里应该用〈压〉。踩是用脚底压，不能用手去踩。"}, {"text": "他提前去踩点，熟悉了比赛场地。", "explanation": "这里是“踩点”（事先实地察看）的意思，不是“用脚底压在物体上”。"}, {"text": "他一脚踩飞了球。", "explanation": "这里应该用〈踢〉。踩是用脚压在东西上，不能表示用力把球踢飞。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cdfabf4-1fd2-44eb-a396-a79b343c6c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95444, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "踩", "is_correct": true, "explanation": "踩 cǎi 指用脚底压在物体上。"}, {"text": "财", "is_correct": false, "explanation": "cái（第二声）与 cǎi（第三声）声调不同，意思是钱财。"}, {"text": "材", "is_correct": false, "explanation": "cái（第二声）与 cǎi（第三声）声调不同，意思是材料。"}, {"text": "裁", "is_correct": false, "explanation": "cái（第二声）与 cǎi（第三声）声调不同，意思是裁判、裁剪。"}], "explanations": {"踩": "踩 cǎi 指用脚底压在物体上。", "财": "cái（第二声）与 cǎi（第三声）声调不同，意思是钱财。", "材": "cái（第二声）与 cǎi（第三声）声调不同，意思是材料。", "裁": "cái（第二声）与 cǎi（第三声）声调不同，意思是裁判、裁剪。"}, "sentence_index": null, "correct_answer": "踩"}, "level_3": {"options": [{"text": "踩", "is_correct": true, "explanation": "正确。“踩出脚印”是脚压在泥地上留下痕迹，符合句意。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写出”的对象是字句，不能和“脚印”搭配。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能说“吃出脚印”。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”是去掉污渍，不能在泥地上“洗出”脚印。"}], "explanations": {"踩": "正确。“踩出脚印”是脚压在泥地上留下痕迹，符合句意。", "写": "搭配：“写出”的对象是字句，不能和“脚印”搭配。", "吃": "搭配：“吃”的对象是食物，不能说“吃出脚印”。", "洗": "语义：“洗”是去掉污渍，不能在泥地上“洗出”脚印。"}, "sentence_index": 6, "correct_answer": "踩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她踩着节拍跳起了舞。", "explanation": "这里是“踩着节拍”（随节拍做动作）的意思，不是“用脚压在东西上”。"}, {"text": "足球场上他用手踩了边线，球权归对方。", "explanation": "这里应该用〈碰〉。踩必须用脚，不能用手。"}, {"text": "他一个人踩起了那只大箱子。", "explanation": "这里应该用〈抬〉。踩是用脚压在东西上，不能表示把箱子抬起来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cdfabf4-1fd2-44eb-a396-a79b343c6c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95444, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我不小心踩了一下了他的脚。", "corrected_sentence": "我不小心踩了一下他的脚。", "error_description": "“了”重复：“踩了一下”中的“了”已表示动作完成，后面再加“了”多余，应说“踩了一下他的脚”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cdfabf4-1fd2-44eb-a396-a79b343c6c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95444, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把纸踩了烂。", "corrected_sentence": "他把纸踩烂了。", "error_description": "补语位置错误：“了”应放在补语“烂”之后，“踩了烂”语序不通，应说“踩烂了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4cdfabf4-1fd2-44eb-a396-a79b343c6c82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
