INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95445, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "人死了。", "primary_collocate": null, "pronunciation": "shēn wáng", "ipa": "ʂən˥ waŋ˧˥", "syllable_count": 2, "sentences": [{"text": "老人因病身亡，家人很难过。", "target_word": "身亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在医院里不幸身亡。", "target_word": "身亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师去年因病身亡了。", "target_word": "身亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说他在国外身亡，大家都很吃惊。", "target_word": "身亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人送到医院后不久就身亡了。", "target_word": "身亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的朋友身亡后，他一直很难过。", "target_word": "身亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位老人昨天夜里身亡。", "target_word": "身亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的丈夫多年前病重身亡。", "target_word": "身亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战士在战场上身亡，国家记住了他。", "target_word": "身亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不幸身亡的消息传到了家乡。", "target_word": "身亡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "身亡了", "label": "体标"}], "register": "书面", "sense_fingerprint": "人因病等原因去世（泛指人死）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0dc02faa-5315-4ba7-927d-a2130aa5300f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95445, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "身亡", "is_correct": true, "explanation": "正确：身亡指人因病等原因死去，与句中的“因病”和“家人很难过”相符。"}, {"text": "痊愈", "is_correct": false, "explanation": "语义：痊愈表示病好了，与“家人很难过”的悲伤语境相反。"}, {"text": "康复", "is_correct": false, "explanation": "语义：康复指身体恢复，与“家人很难过”的语境矛盾。"}, {"text": "结婚", "is_correct": false, "explanation": "搭配：“因病”之后不能接“结婚”，两者没有逻辑关系，搭配不当。"}], "explanations": {"身亡": "正确：身亡指人因病等原因死去，与句中的“因病”和“家人很难过”相符。", "痊愈": "语义：痊愈表示病好了，与“家人很难过”的悲伤语境相反。", "康复": "语义：康复指身体恢复，与“家人很难过”的语境矛盾。", "结婚": "搭配：“因病”之后不能接“结婚”，两者没有逻辑关系，搭配不当。"}, "sentence_index": 0, "correct_answer": "身亡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家的那只小猫昨天身亡了。", "explanation": "这里应该用〈死〉。“身亡”只用于人的死亡，小猫是动物，应说“死了”。"}, {"text": "那盆花在冬天身亡了。", "explanation": "这里应该用〈枯萎〉。“身亡”只用于人的死亡，花的死去应说“枯萎”。"}, {"text": "那辆旧车去年身亡了。", "explanation": "这里应该用〈报废〉。“身亡”只用于人的死亡，车辆失去使用价值应说“报废”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19a3c267-07e1-44c6-91fc-59e7512c6fb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95445, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身亡", "is_correct": true, "explanation": "正确：身亡可以指老人在夜里去世，句中“昨天夜里”的时间与之相符。"}, {"text": "上学", "is_correct": false, "explanation": "语义：上学是学生的活动，与“老人”不相称，句意不通。"}, {"text": "出生", "is_correct": false, "explanation": "语义：出生指婴儿降生，老人不会“出生”，与句意矛盾。"}, {"text": "分娩", "is_correct": false, "explanation": "搭配：分娩是产妇生育的动作，不说老人分娩，与“老人”搭配不当。"}], "explanations": {"身亡": "正确：身亡可以指老人在夜里去世，句中“昨天夜里”的时间与之相符。", "上学": "语义：上学是学生的活动，与“老人”不相称，句意不通。", "出生": "语义：出生指婴儿降生，老人不会“出生”，与句意矛盾。", "分娩": "搭配：分娩是产妇生育的动作，不说老人分娩，与“老人”搭配不当。"}, "sentence_index": 6, "correct_answer": "身亡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他和朋友的友谊在那次争吵后身亡了。", "explanation": "这里是比喻义，指友谊破灭，不是人死去，与本义不符。"}, {"text": "我对这个计划的希望在去年就身亡了。", "explanation": "这里是比喻义，指希望落空，与人死亡的本义不同。"}, {"text": "那次失败以后，他的信心身亡了。", "explanation": "这里是比喻义，指信心丧失，与人死亡的本义不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19a3c267-07e1-44c6-91fc-59e7512c6fb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95445, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父亲被心脏病身亡。", "corrected_sentence": "父亲因心脏病身亡。", "error_description": "被字句误用：“身亡”是不及物动词，不能用“被”构成被动，“心脏病”是原因，应用“因”引出，说“因心脏病身亡”，不能说“被心脏病身亡”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19a3c267-07e1-44c6-91fc-59e7512c6fb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95445, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他被意外事故身亡。", "corrected_sentence": "他因意外事故身亡。", "error_description": "被字句误用：“身亡”是不及物动词，不能用“被”构成被动，应说“因意外事故身亡”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19a3c267-07e1-44c6-91fc-59e7512c6fb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
