INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95448, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把借用或拿来的东西归还。", "primary_collocate": null, "pronunciation": "sòng huán", "ipa": "sʊŋ˥˩ xwan˧˥", "syllable_count": 2, "sentences": [{"text": "你用完词典，请记得送还图书馆。", "target_word": "送还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把借的伞送还给我了。", "target_word": "送还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些借来的书，明天必须送还。", "target_word": "送还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我拿错了你的笔，现在送还给你。", "target_word": "送还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把朋友的外套洗好，送还了。", "target_word": "送还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "借的东西用完要及时送还。", "target_word": "送还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明把从同学那儿拿来的玩具送还了。", "target_word": "送还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居送还了上个月借走的梯子。", "target_word": "送还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直没有送还我的那本小说。", "target_word": "送还", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们把拿来的工具送还。", "target_word": "送还", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "送还了", "label": "体标（了）"}, {"form": "送还过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "把借用或拿来的东西归还", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c139710-9a85-4ec9-b9b6-0cb261a0b0c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95448, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "送还", "is_correct": true, "explanation": "正确。“送还”指把借来的东西还回去，与“用完词典”的语境相符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，不能用于图书馆。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”只能带歌曲等对象，不能带“图书馆”作宾语。"}, {"text": "拆", "is_correct": false, "explanation": "语义：“拆”指拆毁或拆开，与“用完词典后归还”的语境不符。"}], "explanations": {"送还": "正确。“送还”指把借来的东西还回去，与“用完词典”的语境相符。", "吃": "语义：“吃”指进食，不能用于图书馆。", "唱": "搭配：“唱”只能带歌曲等对象，不能带“图书馆”作宾语。", "拆": "语义：“拆”指拆毁或拆开，与“用完词典后归还”的语境不符。"}, "sentence_index": 0, "correct_answer": "送还"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在车站送还朋友。", "explanation": "这里应该用〈送别〉。送还指归还借来的东西，在车站告别朋友应说送别。"}, {"text": "他第一次来我家，临走时我把一盒新茶叶送还给他。", "explanation": "这里应该用〈送给〉。茶叶是我自己的，不是借他的，送礼物应说送给。"}, {"text": "我把写好的信送还给了老师。", "explanation": "这里应该用〈寄送〉。送还只用于归还借来的东西，寄出自己写的信不是归还，要用寄送。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f8b4656-bee1-4fd8-ab2a-1afecd013050') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95448, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "送还", "is_correct": true, "explanation": "正确。“小明把玩具送还了”，送还指归还借来的玩具，与“拿来的”相符。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”只用于食物，不能用于玩具。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”只与饮品等搭配，不能说“喝玩具”。"}, {"text": "送别", "is_correct": false, "explanation": "语义：送别指告别将要离开的人，不能用于玩具。"}], "explanations": {"送还": "正确。“小明把玩具送还了”，送还指归还借来的玩具，与“拿来的”相符。", "煮": "语义：“煮”只用于食物，不能用于玩具。", "喝": "搭配：“喝”只与饮品等搭配，不能说“喝玩具”。", "送别": "语义：送别指告别将要离开的人，不能用于玩具。"}, "sentence_index": 6, "correct_answer": "送还"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家在门口送还刚到的新同学。", "explanation": "这里应该用〈欢迎〉。送还只用于归还借来的东西，迎接刚到的人要用欢迎。"}, {"text": "老师生日那天，我们把一束鲜花送还给了老师。", "explanation": "这里应该用〈赠送〉。鲜花是买来送老师的礼物，不是归还借来的东西，应说赠送。"}, {"text": "工人把货物送还到了工厂，工厂却没有借过这批货。", "explanation": "这里应该用〈运送〉。送还要求东西借自对方，工厂并未借过货物，应说运送。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f8b4656-bee1-4fd8-ab2a-1afecd013050') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95448, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我已经把新买的书送还给图书馆了。", "corrected_sentence": "我已经把借来的书送还给图书馆了。", "error_description": "错误：“新买的书”没有借过，不能用“送还”。“送还”只用于归还借来或拿来的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f8b4656-bee1-4fd8-ab2a-1afecd013050') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95448, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把借的钥匙送还了给邻居。", "corrected_sentence": "我把借的钥匙送还给了邻居。", "error_description": "错误形式：“送还了给”；正确形式：“送还给了”。“了”应放在“送还给”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f8b4656-bee1-4fd8-ab2a-1afecd013050') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (95449, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出生", "is_correct": true, "explanation": "正确：出生与逝世是一对反义词，分别指人降生与去世。"}, {"text": "工作", "is_correct": false, "explanation": "与“逝世”没有反义关系，只是同属动词，意思无对立。"}, {"text": "旅行", "is_correct": false, "explanation": "与“逝世”没有反义关系，指外出游览，与去世无对立。"}, {"text": "睡觉", "is_correct": false, "explanation": "与“逝世”没有反义关系，指休息入睡，二者不构成对立。"}], "correct_answer": "出生", "explanations": {"出生": "正确：出生与逝世是一对反义词，分别指人降生与去世。", "工作": "与“逝世”没有反义关系，只是同属动词，意思无对立。", "旅行": "与“逝世”没有反义关系，指外出游览，与去世无对立。", "睡觉": "与“逝世”没有反义关系，指休息入睡，二者不构成对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d869df1-ec3e-4030-9f24-3c0998b1eb14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
